  ui_story_5051_50510101_1_dialog_content = "又來了。",
  ui_story_5051_50510101_2_dialog_content = "怎麼偏偏還是這個節骨眼！",
  ui_story_5051_50510101_3_dialog_content = "藥劑……有了，在這裡。",
  ui_story_5051_50510101_4_dialog_content = "妳的身體最近越來越差了。",
  ui_story_5051_50510101_5_dialog_content = "僅憑我現有的知識，或許已經……",
