  ui_story_5051_50510101_X23_dialog_content = "信裡說的「使者」到底跑哪去了？",
  ui_story_5051_50510101_23_dialog_content = "伯利恆真厲害，居然連我要參加「<color=#FFB400>舒瓦茲家族日</color>」宴會的事都知道。",
  ui_story_5051_50510101_24_dialog_content = "<size=30>那個……</size>",
  ui_story_5051_50510101_25_dialog_content = "當初收到「家族日」邀請函真把我嚇壞了，畢竟我從來沒參加過這麼隆重的宴會。",
  ui_story_5051_50510101_26_dialog_content = "我這件禮服沒問題吧？不奇怪吧？",
  ui_story_5051_50510101_27_dialog_content = "涉老闆說這是白夜城時下最流行的款式，要花大錢才租得起。",
  ui_story_5051_50510101_28_dialog_content = "我才不懂這些，糊里糊塗就付款了……",
  ui_story_5051_50510101_29_dialog_content = "哎，這時候要是有卡蓮這種行家在身邊就好了。",
  ui_story_5051_50510101_30_dialog_content = "但她最近不知道跑哪去了，根本聯繫不到人。",
  ui_story_5051_50510101_31_dialog_content = "那個……請問……",
  ui_story_5051_50510101_32_dialog_content = "對了，除了禮服還有禮物，我的禮物沒問題吧？",
  ui_story_5051_50510101_33_dialog_content = "那個，請問……！",
  ui_story_5051_50510101_34_dialog_content = "唔哇！！芭、芭芭雅嘎！妳怎麼在這裡？！",
  ui_story_5051_50510101_35_dialog_content = "呀！",
  ui_story_5051_50510101_36_dialog_content = "對、對不起。",
  ui_story_5051_50510101_37_dialog_content = "等等，妳是芭芭雅嘎的另一個人格——<color=#FFB400>蜜雅</color>？",
  ui_story_5051_50510101_38_dialog_content = "嗯，是我。",
  ui_story_5051_50510101_39_dialog_content = "準確來說，我才是這個身體的主人格……",
  ui_story_5051_50510101_40_dialog_content = "只是我沒有芭芭雅嘎那麼厲害，常常控制不好自己，很多事都需要她來代勞。",
  ui_story_5051_50510101_41_dialog_content = "對不起，把你嚇壞了……",
  ui_story_5051_50510101_42_dialog_content = "沒關係啦，妳找我有什麼事嗎？",
  ui_story_5051_50510101_X42_dialog_content = "那個，我聽說PlayerName你要參加「舒瓦茲家族日」的宴會。",
  ui_story_5051_50510101_X43_dialog_content = "可以……帶我一起去嗎？",
  ui_story_5051_50510101_X44_dialog_content = "帶妳一起？可以是可以，但妳為什麼會突然想去宴會呢？",
  ui_story_5051_50510101_X45_dialog_content = "唔……最近經過治療，我的病情好轉了不少。",
  ui_story_5051_50510101_43_dialog_content = "那個，最近經過治療，我的病情好轉了不少。",
  ui_story_5051_50510101_44_dialog_content = "然後呢，我就想起來了……",
  ui_story_5051_50510101_45_dialog_content = "想起什麼了？",
  ui_story_5051_50510101_46_dialog_content = "我是……<color=#FFB400>卡蓮的姐姐</color>。",
  ui_story_5051_50510101_47_dialog_content = "卡蓮的姐姐？！",
  ui_story_5051_50510101_48_dialog_content = "白夜城不是只有一位公主嗎？？",
  ui_story_5051_50510101_49_dialog_content = "再說妳的長相也……不，看久了好像真的有點像。",
  ui_story_5051_50510101_50_dialog_content = "難以相信，對吧？",
  ui_story_5051_50510101_51_dialog_content = "大家都不相信我說的話，伊斯塔萬老爹也一副默不作聲的樣子。",
  ui_story_5051_50510101_52_dialog_content = "但是，在我腦海裡總有一些記憶不斷湧現。",
  ui_story_5051_50510101_53_dialog_content = "時而清晰，時而又會全部忘記……",
  ui_story_5051_50510101_54_dialog_content = "媽媽、妹妹……父親，我的家。",
  ui_story_5051_50510101_55_dialog_content = "以前好像聽妳提過……",
  ui_story_5051_50510101_56_dialog_content = "妳的父親是白夜城的一城之主，母親和妹妹也身居宮殿。",
  ui_story_5051_50510101_57_dialog_content = "妳和芭芭雅嘎似乎都十分在意卡蓮。",
  ui_story_5051_50510101_58_dialog_content = "不過妳似乎常會忘記自己說過的話，所以我也不知道是真是假……",
  ui_story_5051_50510101_59_dialog_content = "現在妳的病情好轉，能想起這些事情，真是太好了。",
  ui_story_5051_50510101_60_dialog_content = "我聽說，最近白夜城要舉辦「舒瓦茲家族日」宴會。",
  ui_story_5051_50510101_61_dialog_content = "「舒瓦茲家族日」……在我印象中，這是很特別、很重要的一天。",
  ui_story_5051_50510101_62_dialog_content = "我的妹妹卡蓮一定也會參加這場宴會吧。",
  ui_story_5051_50510101_X62_dialog_content = "我想去參加宴會，親眼確認那些溫暖的情感到底是不是真的。",
  ui_story_5051_50510101_X63_dialog_content = "就算不行，只要能遠遠看她一眼，也就足夠了……",
  ui_story_5051_50510101_63_dialog_content = "我想去參加宴會，去見見她，確認那些溫暖的情感到底是不是真的。",
  ui_story_5051_50510101_64_dialog_content = "不，即使無法確定這些，只要能遠遠看看她，確認她過得好就夠了……",
  ui_story_5051_50510101_65_dialog_content = "PlayerName，你是卡蓮的朋友，聽說你在白夜城也聲名遠播。",
  ui_story_5051_50510101_X65_dialog_content = "所以我就來找你了……",
  ui_story_5051_50510101_X66_dialog_content = "原來是這樣啊。啊！快來不及了！",
  ui_story_5051_50510101_X67_dialog_content = "蜜雅，妳有適合穿去宴會的禮服嗎？出席宴會的伴手禮也……",
  ui_story_5051_50510101_66_dialog_content = "你能幫幫我嗎……？",
  ui_story_5051_50510101_67_dialog_content = "我今天的確要去參加宴會，但是我不確定能不能帶朋友一起去。",
  ui_story_5051_50510101_68_dialog_content = "呃……一定得是今天嗎？",
  ui_story_5051_50510101_69_dialog_content = "（沒等到北境使者，居然來了向我求助的蜜雅。）",
  ui_story_5051_50510101_70_dialog_content = "（但是，這麼唐突地帶蜜雅過去，真的沒問題嗎？）",
  ui_story_5051_50510101_71_dialog_content = "（「家族日」這種聽起來就很重要的日子，突然帶人去認親是不是有點……）",
  ui_story_5051_50510101_72_dialog_content = "（而且，萬一芭芭雅嘎在宴會上鬧事可就糟了！）",
  ui_story_5051_50510101_73_dialog_content = "我是不是，讓你為難了？",
  ui_story_5051_50510101_74_dialog_content = "不然，還是算了吧。",
  ui_story_5051_50510101_75_dialog_content = "抱歉，說了任性的話，給你這麼大的壓力。",
  ui_story_5051_50510101_76_dialog_content = "這、這些話就當我沒說過好了。",
  ui_story_5051_50510101_77_dialog_content = "哎，不管了！蜜雅，和我一起參加「家族日」的宴會吧！",
  ui_story_5051_50510101_78_dialog_content = "哎？但是，我不會給你添麻煩嗎？",
  ui_story_5051_50510101_79_dialog_content = "今天是「蜜雅」第一次主動和我說這麼多話。",
  ui_story_5051_50510101_80_dialog_content = "平時遇到為難的事，都是芭芭雅嘎出面解決。",
  ui_story_5051_50510101_81_dialog_content = "妳都這麼努力了，我怎麼忍心拒絕妳啊……",
  ui_story_5051_50510101_82_dialog_content = "安啦！我和卡蓮還有白夜城的很多人關係都很好。",
  ui_story_5051_50510101_83_dialog_content = "如果今天沒機會相認，我們就當做是去宴會玩吧。",
  ui_story_5051_50510101_84_dialog_content = "以後一定還有機會的！",
  ui_story_5051_50510101_85_dialog_content = "PlayerName……謝謝你！",
  ui_story_5051_50510101_86_dialog_content = "（雖然不確定的事還有很多。）",
  ui_story_5051_50510101_87_dialog_content = "（但蜜雅對卡蓮的執著非常誠懇，至少讓她們見個面吧。）",
  ui_story_5051_50510101_88_dialog_content = "（不過，為什麼蜜雅只想見卡蓮，卻沒說想見城主大人呢……）",
  ui_story_5051_50510101_89_dialog_content = "<size=45>不好意思，我來晚了！</size>",
  ui_story_5051_50510101_90_dialog_content = "呀！",
  ui_story_5051_50510101_91_dialog_content = "誰、誰啊？？",
  ui_story_5051_50510101_92_dialog_content = "哎呀～影鎮真的有許多稀奇有趣的東西呢！",
  ui_story_5051_50510101_93_dialog_content = "不如說，自從出了北境，一路上所有東西都好有意思啊～",
  ui_story_5051_50510101_94_dialog_content = "搞得我一不小心看入迷，結果就……迷路了，嘿嘿！",
  ui_story_5051_50510101_95_dialog_content = "但是沒關係，畢竟有我可愛的小占卜球在，一定能找到路的！",
  ui_story_5051_50510101_96_dialog_content = "雖然占卜有時也會把我引向懸崖之類的地方……",
  ui_story_5051_50510101_97_dialog_content = "不過旅行就是該如此曲折！充滿刺激！耶利亞老師是這麼說的！",
  ui_story_5051_50510101_98_dialog_content = "剛剛說到哪裡了？喔對，影鎮！",
  ui_story_5051_50510101_99_dialog_content = "影鎮的路真是複雜，但建築的位置卻大有講究。",
  ui_story_5051_50510101_X99_dialog_content = "聽說，內行的人都會把店開在旺財的地方唷！",
  ui_story_5051_50510101_100_dialog_content = "啊，這個說法是聽路上的旅人講的。",
  ui_story_5051_50510101_101_dialog_content = "有機會真想深入學習這方面的知識……這個會飛的是什麼！！",
  ui_story_5051_50510101_102_dialog_content = "那個，請問……",
  ui_story_5051_50510101_103_dialog_content = "你是誰啊？",
  ui_story_5051_50510101_104_dialog_content = "抱歉，忘記自我介紹了！",
  ui_story_5051_50510101_105_dialog_content = "我叫<color=#FFB400>加晴</color>，是來自北境的使者！",
  ui_story_5051_50510101_106_dialog_content = "雖然有點遲到，但俗話說得好，主角都是最後才登場的嘛。",
  ui_story_5051_50510101_107_dialog_content = "<size=45>……妳這也晚過頭了吧？！</size>",
  ui_story_5051_50510101_X107_dialog_content = "嘿、嘿嘿，俗話說得好，主角都是最後才登場的嘛～",
  ui_story_5051_50510101_X108_dialog_content = "咳咳，各位晚安！",
  ui_story_5051_50510101_X109_dialog_content = "今夜，我們相聚一堂。",
  ui_story_5051_50510101_X110_dialog_content = "參加一年一度的盛宴。",
  ui_story_5051_50510101_X111_dialog_content = "享受無與倫比的美饌。",
  ui_story_5051_50510101_X112_dialog_content = "但，再好的肉總會吃膩。",
  ui_story_5051_50510101_X113_dialog_content = "上等美酒終將飲盡。",
  ui_story_5051_50510101_X114_dialog_content = "不如在談笑之間換換空氣。",
  ui_story_5051_50510101_X115_dialog_content = "感受餘興節目帶來的樂趣。",
  ui_story_5051_50510101_108_dialog_content = "各位親愛的來賓。",
  ui_story_5051_50510101_109_dialog_content = "接下來就由我們基汀唱詩班。",
  ui_story_5051_50510101_110_dialog_content = "為各位獻上頌歌一首。",
  ui_story_5051_50510101_111_dialog_content = "曲名為《白夜頌》。",
  ui_story_5051_50510101_112_dialog_content = "敬請聆賞！",
  ui_story_5051_50510101_113_dialog_content = "太陽與群星一同升起～♪",
  ui_story_5051_50510101_114_dialog_content = "余光照耀崇高王座～♪",
  ui_story_5051_50510101_115_dialog_content = "以身為盾～♪",
  ui_story_5051_50510101_116_dialog_content = "以己為矛～♪",
  ui_story_5051_50510101_117_dialog_content = "顯貴光榮乃信仰佐證～♪",
  ui_story_5051_50510101_118_dialog_content = "錚鳴光輝肅清晦暗～♪",
  ui_story_5051_50510101_119_dialog_content = "天空之城永無墜落～♪",
  ui_story_5051_50510101_120_dialog_content = "汝需銘記～♪",
  ui_story_5051_50510101_121_dialog_content = "汝當讚頌～♪",
  ui_story_5051_50510101_122_dialog_content = "陰影漸逝～♪",
  ui_story_5051_50510101_123_dialog_content = "長日無盡～♪",
  ui_story_5051_50510101_124_dialog_content = "白夜至上，感謝諸位。",
  ui_story_5051_50510101_125_dialog_content = "哇～不錯不錯，真是好歌一首～",
  ui_story_5051_50510101_X125_dialog_content = "這些孩子真有藝術天分呢～",
  ui_story_5051_50510101_126_dialog_content = "他們幾個，在正經場合表現得蠻不錯呢！",
  ui_story_5051_50510101_127_dialog_content = "不然，也不會讓他們出席這麼盛大的場合了嘛～",
  ui_story_5051_50510101_128_dialog_content = "要是他們平時也能這麼乖就更好了～",
  ui_story_5051_50510101_129_dialog_content = "……",
  ui_story_5051_50510101_130_dialog_content = "嗯嗯？喔，看來米迦勒也很贊同呢！",
  ui_story_5051_50510101_131_dialog_content = "「錚鳴光輝肅清晦暗，天空之城永無墜落。」",
  ui_story_5051_50510101_132_dialog_content = "——「暗潮危機」。",
  ui_story_5051_50510101_133_dialog_content = "那場噩夢般的浩劫，如今也算是告一段落了。",
  ui_story_5051_50510101_134_dialog_content = "「暗潮危機」，爸爸、媽媽……",
  ui_story_5051_50510101_135_dialog_content = "啊——停停停！難得開心的宴會，不要想些亂七八糟的啦！",
  ui_story_5051_50510101_136_dialog_content = "……",
  ui_story_5051_50510101_137_dialog_content = "你看，米迦勒也點頭贊同了！",
  ui_story_5051_50510101_138_dialog_content = "抱歉，烏列爾，是我失言了。",
  ui_story_5051_50510101_139_dialog_content = "沒關係，我已經習慣這種痛楚了。只是我還是沒辦法習慣宴會。",
  ui_story_5051_50510101_140_dialog_content = "也、也是啦！這裡人好多好熱喔～",
  ui_story_5051_50510101_141_dialog_content = "走走走，我們去拿霜淇淋吃！",
  ui_story_5051_50510101_142_dialog_content = "<size=30>米迦勒，幫我拉著烏列爾！</size>",
  ui_story_5051_50510101_143_dialog_content = "……",
  ui_story_5051_50510101_144_dialog_content = "哎呀，真是群調皮的孩子，一轉眼就不見了呢～",
  ui_story_5051_50510101_145_dialog_content = "但它帶給人們的傷痛，卻依舊鮮明如初。",
  ui_story_5051_50510101_146_dialog_content = "所有親歷者……倖存者，哪怕是如此強大的四天使，也一樣無法釋懷嗎。",
  ui_story_5051_50510101_147_dialog_content = "小伊倫汀～來，笑一笑～",
  ui_story_5051_50510101_148_dialog_content = "本來宴會的節目就夠少了。",
  ui_story_5051_50510101_149_dialog_content = "再不好好享受，就沒機會享受啦～",
  ui_story_5051_50510101_150_dialog_content = "「舒瓦茲家族日」，原本是紀念舒瓦茲家族整體功績的節日。",
  ui_story_5051_50510101_151_dialog_content = "<color=#FFB400>十二年前</color>的今天，現任城主面對一連串危機，再次展現了舒瓦茲家族的實力。",
  ui_story_5051_50510101_152_dialog_content = "但是暗潮危機後，「家族日」的慶祝規模反而縮小了。",
  ui_story_5051_50510101_153_dialog_content = "我記得以前有大型的花車遊行，甚至有遊樂設施。",
  ui_story_5051_50510101_154_dialog_content = "嗯，好像是這樣來著？我記不太清楚了～",
  ui_story_5051_50510101_155_dialog_content = "不過，我記得每年都有人抱怨，「家族日」不該從簡慶祝呢～",
  ui_story_5051_50510101_156_dialog_content = "大家是怎麼說的來著……喔對。",
  ui_story_5051_50510101_157_dialog_content = "「白夜城的青年才俊需要一個能直接向城主表達敬意和忠誠的場合」之類的～",
  ui_story_5051_50510101_158_dialog_content = "所以這個節日才以簡單的宴會形式保留下來。",
  ui_story_5051_50510101_159_dialog_content = "我很贊同城主從簡處理的做法，從財政和人力消耗的方面看非常合理。",
  ui_story_5051_50510101_160_dialog_content = "但是，這樣的節日的確也能為忙於勞動的人們提供休息的機會。",
  ui_story_5051_50510101_161_dialog_content = "以及聽八卦消息的機會～",
  ui_story_5051_50510101_162_dialog_content = "這就不必了。",
  ui_story_5051_50510101_163_dialog_content = "現在應該可以進場了吧？",
  ui_story_5051_50510101_164_dialog_content = "當然可以了！",
  ui_story_5051_50510101_165_dialog_content = "話說，我們為什麼要在門口等裡面的人唱完歌啊？",
  ui_story_5051_50510101_166_dialog_content = "剛才唱詩的時候，裡面那麼安靜，突然闖進去也太顯眼了，很沒禮貌。",
  ui_story_5051_50510101_167_dialog_content = "哎？還有這樣的規矩嗎？",
  ui_story_5051_50510101_168_dialog_content = "嗯、嗯，表演的時候發出聲音很不禮貌……",
  ui_story_5051_50510101_169_dialog_content = "……蜜雅，如果妳當時穿著這身衣服告訴我妳是卡蓮的姐姐。",
  ui_story_5051_50510101_170_dialog_content = "我一定會立即、完全、百分百地相信妳。",
  ui_story_5051_50510101_171_dialog_content = "現在的妳，不論怎麼看都是白夜城的公主！",
  ui_story_5051_50510101_172_dialog_content = "這只是普通的裙裝而已。為、為了配合宴會，要穿適合的衣服……",
  ui_story_5051_50510101_173_dialog_content = "一、二、三，這一路上你已經說了三次了！",
  ui_story_5051_50510101_174_dialog_content = "你不要老盯著人家女孩子看好不好。",
  ui_story_5051_50510101_175_dialog_content = "我、我只是真的很震撼而已。",
  ui_story_5051_50510101_176_dialog_content = "我不信。剛剛在巨像上，你不還答應了一個紫裙子的女孩子，要帶她參加宴會嗎？",
  ui_story_5051_50510101_177_dialog_content = "怎麼現在又換了個夥伴？",
  ui_story_5051_50510101_178_dialog_content = "喂，現在的這個白裙蜜雅，就是巨像上的紫裙蜜雅啊！",
  ui_story_5051_50510101_179_dialog_content = "真的假的？！完全看不出來！這是什麼特殊的光能術嗎？？",
  ui_story_5051_50510101_180_dialog_content = "哎、哎？為什麼突然貼得這麼近……",
  ui_story_5051_50510101_181_dialog_content = "那妳不是也跟我一樣嗎！甚至一路上都沒發現！",
  ui_story_5051_50510101_182_dialog_content = "嘿、嘿嘿～路上光顧著看白夜城的景色了～",
  ui_story_5051_50510101_183_dialog_content = "兩位，我們是不是該進去了……？",
  ui_story_5051_50510101_184_dialog_content = "咳咳，是、是的。",
  ui_story_5051_50510101_185_dialog_content = "那麼，請把禮物準備好。再確認一次，大家都帶了，對嗎？",
  ui_story_5051_50510101_186_dialog_content = "當然！我可是受北境女王所託，帶了獨一無二的禮物來喔～",
  ui_story_5051_50510101_187_dialog_content = "帶是帶了……",
  ui_story_5051_50510101_188_dialog_content = "（但是，一罐蒲公英花蜜會不會太寒酸啊？）",
  ui_story_5051_50510101_189_dialog_content = "（這罐是今年品質最棒的蜂蜜，但怎麼看都不適合放在這座宅邸裡啊。）",
  ui_story_5051_50510101_190_dialog_content = "那罐蜜看起來很誘人，真想加進紅茶裡喝喝看。",
  ui_story_5051_50510101_191_dialog_content = "說不定會在貴族之間掀起一股新的熱潮呢。",
  ui_story_5051_50510101_192_dialog_content = "（被蜜雅看穿了！她居然還不動聲色地安慰我！）",
  ui_story_5051_50510101_193_dialog_content = "希、希望城主會喜歡。我準備好了，走吧！",
  ui_story_5051_50510101_194_dialog_content = "歡迎各位貴賓蒞臨「舒瓦茲家族日」宴會。",
  ui_story_5051_50510101_195_dialog_content = "請來賓出示邀請函，並在這邊登記姓名。",
  ui_story_5051_50510101_196_dialog_content = "邀請函、邀請函～有了！然後簽名！",
  ui_story_5051_50510101_197_dialog_content = "來自北境的使者，沒有問題。",
  ui_story_5051_50510101_198_dialog_content = "請在宴會期間看好您的寵物，安全地享受今晚的盛宴。",
  ui_story_5051_50510101_199_dialog_content = "沒問題～幽呼很乖的，對吧！",
  ui_story_5051_50510101_200_dialog_content = "嘶嘶——",
  ui_story_5051_50510101_X200_dialog_content = "還請您盡情享受今晚的盛宴。",
  ui_story_5051_50510101_X201_dialog_content = "那當然～謝啦！",
  ui_story_5051_50510101_201_dialog_content = "我的邀請函在這裡。",
  ui_story_5051_50510101_202_dialog_content = "來自空之山谷的PlayerName閣下，久仰大名。",
  ui_story_5051_50510101_203_dialog_content = "感謝您在百忙中撥冗蒞臨「舒瓦茲家族日」宴會，請盡情享受今晚的一切。",
  ui_story_5051_50510101_204_dialog_content = "如有任何不便，可以洽詢場內的侍者，我們一定會為您提供最好的服務。",
  ui_story_5051_50510101_205_dialog_content = "嗯？怎麼感覺你的待遇比我好啊？",
  ui_story_5051_50510101_206_dialog_content = "好歹我也是倖存的空之末裔嘛！",
  ui_story_5051_50510101_207_dialog_content = "（原來我這麼受人尊敬的嗎？！）",
  ui_story_5051_50510101_208_dialog_content = "您身後的這位是？請出示您的邀請函。",
  ui_story_5051_50510101_209_dialog_content = "！",
  ui_story_5051_50510101_210_dialog_content = "（蜜雅雖然能和我跟加晴正常說話，但一碰到陌生人就會躲起來。）",
  ui_story_5051_50510101_211_dialog_content = "（尤其是走進舒瓦茲家族宅邸後，總覺得她很害怕這裡的人群。）",
  ui_story_5051_50510101_212_dialog_content = "她、她是我的朋友！",
  ui_story_5051_50510101_213_dialog_content = "原來如此，既然是您的朋友，那就不需要邀請函了。",
  ui_story_5051_50510101_214_dialog_content = "兩位，請進吧。",
  ui_story_5051_50510101_215_dialog_content = "（唔，說話怎麼油腔滑調的，這就是所謂上流社會的交際嗎？）",
  ui_story_5051_50510101_216_dialog_content = "謝謝你，PlayerName……",
  ui_story_5051_50510101_217_dialog_content = "小事一樁！有我在，別怕。",
  ui_story_5051_50510101_218_dialog_content = "呿～怎麼所有人都繞著PlayerName轉，北境使者就這麼沒存在感嗎？",
  ui_story_5051_50510101_219_dialog_content = "您是北境的使者，加晴小姐，對吧？",
  ui_story_5051_50510101_220_dialog_content = "對！我就是北境女王伯利恆親命，新一代的北境使者——加晴！",
  ui_story_5051_50510101_221_dialog_content = "果然如此，和傳聞中一樣，一頭豔麗的紅髮，與前任使者如出一轍。",
  ui_story_5051_50510101_222_dialog_content = "你見過前任使者<color=#FFB400>博阿姿</color>嗎？哼哼，我可是她女兒喔～",
  ui_story_5051_50510101_223_dialog_content = "很好……",
  ui_story_5051_50510101_224_dialog_content = "您好，我是白夜城的凱萊布。今晚和您一樣，也是來拜訪舒瓦茲殿下。",
  ui_story_5051_50510101_225_dialog_content = "請問能否賞光與我同行呢？",
  ui_story_5051_50510101_226_dialog_content = "這個……",
  ui_story_5051_50510101_227_dialog_content = "一路上，我們還可以聊聊您的母親，博阿姿。",
  ui_story_5051_50510101_228_dialog_content = "真的嗎？！那就再好不過啦！",
  ui_story_5051_50510101_X225_dialog_content = "賞光？同行？可不可以有話直說呀……",
  ui_story_5051_50510101_X226_dialog_content = "哈哈哈……一言蔽之，我是城主大人特地派來迎接您的侍者。",
  ui_story_5051_50510101_X227_dialog_content = "城主大人特地派人來迎接我？！",
  ui_story_5051_50510101_X228_dialog_content = "什麼嘛～果然我堂堂北境使者，還是很有派頭的！",
  ui_story_5051_50510101_X229_dialog_content = "你稍等一下，我和一起來的朋友說一聲！",
  ui_story_5051_50510101_229_dialog_content = "嘿嘿～PlayerName！我有專人陪我一起去見城主大人啦，拜拜～",
  ui_story_5051_50510101_230_dialog_content = "啊？妳去哪裡？……怎麼這麼快就不見了。",
  ui_story_5051_50510101_231_dialog_content = "加晴真是的，明明伯利恆陛下還特別寫信要我們同行，結果剛到會場就跟別人走掉了。",
  ui_story_5051_50510101_X231_dialog_content = "（哎，算了。我本來就只是敵不過人家熱情邀請，過來隨便看看。）",
  ui_story_5051_50510101_X232_dialog_content = "（但蜜雅將她與家人聯繫的希望託付在我身上，我不能辜負這份信任，要顧慮到她的心情。）",
  ui_story_5051_50510101_X233_dialog_content = "蜜雅，妳還好嗎？",
  ui_story_5051_50510101_232_dialog_content = "唔……我……",
  ui_story_5051_50510101_233_dialog_content = "（糟了，這裡到處都是白夜城的貴族，蜜雅似乎已經到極限了。）",
  ui_story_5051_50510101_234_dialog_content = "我們先找個休息室坐一會吧？",
  ui_story_5051_50510101_235_dialog_content = "可是，卡蓮……我還沒見到她……",
  ui_story_5051_50510101_236_dialog_content = "沒關係！妳先休息，我一定會把她帶來妳面前的！",
  ui_story_5051_50510101_237_dialog_content = "PlayerName……",
  ui_story_5051_50510101_238_dialog_content = "出門左轉，有一間會客廳……",
  ui_story_5051_50510101_239_dialog_content = "出門左轉，有了！",
  ui_story_5051_50510101_240_dialog_content = "這扇門要往外拉，推會推不開……",
  ui_story_5051_50510101_241_dialog_content = "嘿咻！拉開了！",
  ui_story_5051_50510101_X238_dialog_content = "那裡有三扇門，會客廳門口，放著……兩支白色的花瓶……",
  ui_story_5051_50510101_X239_dialog_content = "卡蓮小時候，還不小心割到那扇門的門框……",
  ui_story_5051_50510101_X240_dialog_content = "出門左轉。沒錯，這裡有三扇門。",
  ui_story_5051_50510101_X241_dialog_content = "放著兩支白色花瓶的，是……最左邊這一扇。",
  ui_story_5051_50510101_X242_dialog_content = "有了，是會客室沒錯！",
  ui_story_5051_50510101_X243_dialog_content = "（門框內側的確有一道不明顯的割痕，跟蜜雅說的完全一樣。）",
  ui_story_5051_50510101_242_dialog_content = "（蜜雅好熟悉這裡的細節，彷彿來過一樣。）",
  ui_story_5051_50510101_243_dialog_content = "（難道說，她真的是白夜城的公主……？）",
  ui_story_5051_50510201_1_dialog_content = "目前，截止至《白夜頌》的節目已經表演完畢。",
  ui_story_5051_50510201_2_dialog_content = "接下來的節目以歌舞為主，均由上層貴族的青年才俊為您呈獻。",
  ui_story_5051_50510201_3_dialog_content = "多位貴賓懇切希望您能親臨現場，欣賞接下來的表演。",
  ui_story_5051_50510201_4_dialog_content = "其中也夾雜一些希望調整節目安排的聲音——",
  ui_story_5051_50510201_5_dialog_content = "「想讓兒子的樂器壓軸獨奏」、「女兒的舞蹈演出需要佈景，希望延後表演時間」等等。",
  ui_story_5051_50510201_6_dialog_content = "這些請求，我已經「適切地」一一處理過了，還請您過目。",
  ui_story_5051_50510201_7_dialog_content = "不必了，我信任妳。",
  ui_story_5051_50510201_8_dialog_content = "感謝妳今日頂替卡蓮，負責宴會的統籌和保全調度。",
  ui_story_5051_50510201_9_dialog_content = "……統籌「家族日」本應是卡蓮的職責。",
  ui_story_5051_50510201_10_dialog_content = "但是多年以來，她始終都選擇逃避。",
  ui_story_5051_50510201_11_dialog_content = "對我來說，每年的今天無非是母親的忌日。",
  ui_story_5051_50510201_12_dialog_content = "她臨終時，我沒能陪在身邊，如今我也不會留在城裡。",
  ui_story_5051_50510201_13_dialog_content = "——每年，她都會丟下這句話，獨自離開白夜城。",
  ui_story_5051_50510201_14_dialog_content = "哪怕她與母親相處的時日不多，失去的傷痛卻能影響她這麼久。",
  ui_story_5051_50510201_15_dialog_content = "您覺得，卡蓮殿下不夠懂事嗎？",
  ui_story_5051_50510201_16_dialog_content = "正好相反，這是我年少輕狂時種下的惡根。",
  ui_story_5051_50510201_17_dialog_content = "如今不過是自食其果罷了。",
  ui_story_5051_50510201_18_dialog_content = "您言重了。",
  ui_story_5051_50510201_19_dialog_content = "人非聖賢，您的輝煌是以凡人之軀鑄造無上偉業。",
  ui_story_5051_50510201_20_dialog_content = "其中的功過幾分，只要望向如今的白夜城，就能一眼辨明。",
  ui_story_5051_50510201_21_dialog_content = "沒有您，再好的導遊也無法帶人領略白夜的絕景。",
  ui_story_5051_50510201_22_dialog_content = "對，白蘭女士說得好！",
  ui_story_5051_50510201_23_dialog_content = "喔不，您這身打扮，我是不是該尊稱您一聲「紅女士」？",
  ui_story_5051_50510201_24_dialog_content = "您好，奧托公爵。今日乃歡慶、讚頌城主殿下偉業的宴會。",
  ui_story_5051_50510201_25_dialog_content = "我不過是個小小配角，您隨意稱呼即可。",
  ui_story_5051_50510201_26_dialog_content = "小小配角？哈哈哈，您可真會說笑啊，「守夜人紅女士」。",
  ui_story_5051_50510201_27_dialog_content = "殿下，恕我遲來問候，沒有打擾到您敘舊吧？",
  ui_story_5051_50510201_28_dialog_content = "宴會之夜，你也不必恪守繁文縟節，盡情享受即可。",
  ui_story_5051_50510201_29_dialog_content = "那怎麼行。今夜的意義，就是讚美城主殿下您對白夜城的偉大貢獻。",
  ui_story_5051_50510201_30_dialog_content = "可惜您身邊的人都不理解啊。",
  ui_story_5051_50510201_31_dialog_content = "這就是所謂的「高處不勝寒」吧？",
  ui_story_5051_50510201_32_dialog_content = "奧托，你不也是一樣？",
  ui_story_5051_50510201_33_dialog_content = "為了特洛伊家族和元老院，你多年來也做了不少「犧牲」。",
  ui_story_5051_50510201_34_dialog_content = "哪裡哪裡，比不上您的一分一毫。",
  ui_story_5051_50510201_35_dialog_content = "待會演出結束，就輪到小犬上台致詞了，還希望您能賞個光。",
  ui_story_5051_50510201_36_dialog_content = "那真是不巧，之後有位貴賓約我見面。",
  ui_story_5051_50510201_37_dialog_content = "你的養子如此優秀，其他賓客必會為他的「才藝表演」獻上掌聲。",
  ui_story_5051_50510201_38_dialog_content = "不差我一人。",
  ui_story_5051_50510201_39_dialog_content = "殿下，侍者前來稟告，約見您的貴客已抵達會場。",
  ui_story_5051_50510201_40_dialog_content = "真巧，說人人到。好好享受宴會吧，奧托。",
  ui_story_5051_50510201_41_dialog_content = "好的，殿下。",
  ui_story_5051_50510201_42_dialog_content = "……所以說，龍這個種族很神奇的～",
  ui_story_5051_50510201_43_dialog_content = "小的只有巴掌那麼大，大的居然有巨像那麼大！",
  ui_story_5051_50510201_44_dialog_content = "話說，龍和巨像看起來有一點點像欸，難道兩者之間有什麼關聯嗎？",
  ui_story_5051_50510201_45_dialog_content = "咳咳，加晴小姐。",
  ui_story_5051_50510201_46_dialog_content = "喔，怎麼啦？",
  ui_story_5051_50510201_47_dialog_content = "聽說前任使者博阿姿女士是個偉大的占卜師。",
  ui_story_5051_50510201_48_dialog_content = "我對北境的占卜術很感興趣，請問您瞭解這方面的知識嗎？",
  ui_story_5051_50510201_49_dialog_content = "當然了～何止瞭解，我就是一位資深……",
  ui_story_5051_50510201_50_dialog_content = "呃，總之我就是個占卜師啦！",
  ui_story_5051_50510201_51_dialog_content = "北境女王可是特地指派我來替「<color=#FFB400>永憶鏡晶</color>」補充鏡湖之水喔。",
  ui_story_5051_50510201_52_dialog_content = "「永憶鏡晶」我有所耳聞。",
  ui_story_5051_50510201_53_dialog_content = "但是，為什麼「永憶鏡晶」需要補充鏡湖之水呢？",
  ui_story_5051_50510201_54_dialog_content = "那不是用來儲存光能的嗎……",
  ui_story_5051_50510201_55_dialog_content = "您好，加晴小姐，終於找到您了。",
  ui_story_5051_50510201_56_dialog_content = "喔，妳好！",
  ui_story_5051_50510201_57_dialog_content = "<size=30>凱萊布先生，這位大姐姐是誰啊？</size>",
  ui_story_5051_50510201_58_dialog_content = "好久不見，白蘭小姐。",
  ui_story_5051_50510201_59_dialog_content = "好久不見。我還是第一次在「家族日」的宴會上見到您，非常感謝您賞光。",
  ui_story_5051_50510201_60_dialog_content = "這位是白蘭小姐，您可以把她當做城主殿下的助手。",
  ui_story_5051_50510201_61_dialog_content = "這樣啊……",
  ui_story_5051_50510201_62_dialog_content = "加晴小姐，城主殿下已經在會客廳等您了，請跟我來。",
  ui_story_5051_50510201_63_dialog_content = "您、您好！我是北境女王委任的新任北境使者——加晴！",
  ui_story_5051_50510201_64_dialog_content = "距離使者上次來訪白夜城，已經過了十二年。",
  ui_story_5051_50510201_65_dialog_content = "我奉女王之命，特來為「永憶鏡晶」補充<color=#FFB400>鏡湖之水</color>。",
  ui_story_5051_50510201_66_dialog_content = "感謝妳的到來，北境使者。",
  ui_story_5051_50510201_67_dialog_content = "此事女王已遞書信交代。多謝妳不遠萬里完成使命。",
  ui_story_5051_50510201_68_dialog_content = "沒事！這是我的職責所在！",
  ui_story_5051_50510201_69_dialog_content = "紅女士，麻煩把「永憶鏡晶」拿過來吧。",
  ui_story_5051_50510201_70_dialog_content = "好的。",
  ui_story_5051_50510201_71_dialog_content = "……",
  ui_story_5051_50510201_72_dialog_content = "我記得，我剛剛是吩咐紅女士，將北境的使者帶來。",
  ui_story_5051_50510201_73_dialog_content = "難道，你在宴會上與北境使者成為朋友了嗎，凱萊布？",
  ui_story_5051_50510201_74_dialog_content = "萬分抱歉，殿下。",
  ui_story_5051_50510201_75_dialog_content = "我只是覺得，事關<color=#FFB400>姐姐的遺物</color>，我身為家屬沒必要回避。",
  ui_story_5051_50510201_76_dialog_content = "沒想到，您會如此顧忌我在場。",
  ui_story_5051_50510201_77_dialog_content = "（姐姐的遺物？家屬？顧忌？……什麼跟什麼呀！怎麼氣氛這麼尷尬啊！）",
  ui_story_5051_50510201_78_dialog_content = "（PlayerName、蜜雅，我錯了……）",
  ui_story_5051_50510201_X78_dialog_content = "（我不該丟下你們，一個人去完成使命的！誰來救救我！）",
  ui_story_5051_50510201_79_dialog_content = "殿下，凱萊布先生是我邀請的。",
  ui_story_5051_50510201_80_dialog_content = "凱萊布先生有事想要見您，鑑於之後您還有其他安排，我便讓他一同前來了。",
  ui_story_5051_50510201_81_dialog_content = "身為親人，他理應在您的行程中享有更高的優先順序。",
  ui_story_5051_50510201_82_dialog_content = "紅女士……有時妳真是精明過頭了。",
  ui_story_5051_50510201_83_dialog_content = "感謝您的誇獎。",
  ui_story_5051_50510201_84_dialog_content = "「永憶鏡晶」在這裡，麻煩您了。",
  ui_story_5051_50510201_85_dialog_content = "好的，交給我吧！",
  ui_story_5051_50510201_86_dialog_content = "（得、得救了！謝啦，白蘭小姐～）",
  ui_story_5051_50510201_87_dialog_content = "凱萊布先生，這杯影鎮的佳釀，是某位貴賓帶來的禮物。",
  ui_story_5051_50510201_88_dialog_content = "據說有凝神靜氣的作用，還請您細細品嘗。",
  ui_story_5051_50510201_89_dialog_content = "……謝謝。",
  ui_story_5051_50510201_90_dialog_content = "凱萊布，你此次前來，難道是為了「永憶鏡晶」嗎？",
  ui_story_5051_50510201_91_dialog_content = "這顆「永憶鏡晶」是北境女王贈予我們夫妻的<color=#FFB400>記錄裝置</color>。",
  ui_story_5051_50510201_92_dialog_content = "十二年前，的確是我的妻子，也就是你的姐姐親手將其啟動。",
  ui_story_5051_50510201_93_dialog_content = "但裡面儲存的，不過是當年的一些回憶罷了。",
  ui_story_5051_50510201_94_dialog_content = "我只是在她走後代為保管，絕無佔有之意。",
  ui_story_5051_50510201_95_dialog_content = "哪怕是女王想將之收回，我也不會有半句怨言。",
  ui_story_5051_50510201_96_dialog_content = "……在您眼裡，與妻女的回憶就如此一文不值？",
  ui_story_5051_50510201_97_dialog_content = "女、女王從來沒說過要收回去喔！",
  ui_story_5051_50510201_98_dialog_content = "畢竟這裡面的世界，已經因為啟動者的光能開始運轉了，女王拿著它也沒用啊！",
  ui_story_5051_50510201_99_dialog_content = "裡面的世界？",
  ui_story_5051_50510201_100_dialog_content = "對，「永憶鏡晶」可不是普通的記錄裝置喔～",
  ui_story_5051_50510201_101_dialog_content = "裡面可是儲存著一個<color=#FFB400>真實的世界</color>呢！",
  ui_story_5051_50510201_102_dialog_content = "這東西到底是怎麼回事？",
  ui_story_5051_50510201_103_dialog_content = "嗯～看來凱萊布先生不太瞭解「永憶鏡晶」。",
  ui_story_5051_50510201_104_dialog_content = "那就讓我介紹一下它的使用方法吧！",
  ui_story_5051_50510201_105_dialog_content = "首先，要確保「永憶鏡晶」擁有充足的鏡湖之水。",
  ui_story_5051_50510201_106_dialog_content = "然後，使用者必須注入自己的光能，用來啟動「永憶鏡晶」。",
  ui_story_5051_50510201_107_dialog_content = "這樣一來，「永憶鏡晶」就可以自動記錄<color=#FFB400>一天之內周遭發生的所有事情</color>。",
  ui_story_5051_50510201_108_dialog_content = "往後這一切都會儲存在「永憶鏡晶」內，透過模擬還原不斷循環播放。",
  ui_story_5051_50510201_109_dialog_content = "只要啟動者再次注入光能，就能進入「永憶鏡晶」親身體驗那個世界！",
  ui_story_5051_50510201_110_dialog_content = "這就是「永憶鏡晶」內部世界的祕密～",
  ui_story_5051_50510201_111_dialog_content = "但是，「永憶鏡晶」也很脆弱……",
  ui_story_5051_50510201_112_dialog_content = "使用者進入後會預設保持隱身狀態，不能與任何人事物產生交集。",
  ui_story_5051_50510201_113_dialog_content = "<size=42>否則要是一不小心改變了既定故事，就會引發難以想像的災難！</size>",
  ui_story_5051_50510201_114_dialog_content = "這就是北境的神祕技術嗎……",
  ui_story_5051_50510201_115_dialog_content = "<size=30>怎麼這麼複雜。</size>",
  ui_story_5051_50510201_116_dialog_content = "嘿咻～好了，鏡湖之水補充完畢！",
  ui_story_5051_50510201_117_dialog_content = "給您，城主大人。",
  ui_story_5051_50510201_118_dialog_content = "您現在可以隨時啟動啦～",
  ui_story_5051_50510201_119_dialog_content = "辛苦妳了，北境使者。",
  ui_story_5051_50510201_120_dialog_content = "……可惜，啟動者現已離開人世。",
  ui_story_5051_50510201_121_dialog_content = "她在時，無人願回首那段過去。",
  ui_story_5051_50510201_122_dialog_content = "她走後，我便也無權再顧影自憐。",
  ui_story_5051_50510201_123_dialog_content = "恐怕無人能再開啟它了。",
  ui_story_5051_50510201_124_dialog_content = "呃……",
  ui_story_5051_50510201_125_dialog_content = "沒、沒關係！有我這個北境占卜師在，一定能想出其他辦法的！",
  ui_story_5051_50510201_126_dialog_content = "讓我看看……操作方法和咒語是～",
  ui_story_5051_50510201_127_dialog_content = "……",
  ui_story_5051_50510201_128_dialog_content = "讓我看看，操作方法和咒語是……",
  ui_story_5051_50510201_129_dialog_content = "約書亞，不是說好要一起學怎麼使用「永憶鏡晶」嗎？",
  ui_story_5051_50510201_130_dialog_content = "我知道妳勤奮好學，但這樣老是被妳搶先一步，我也會感到寂寞。",
  ui_story_5051_50510201_131_dialog_content = "哎呀，原來我也有會讓你感到寂寞的時候。",
  ui_story_5051_50510201_132_dialog_content = "我一直以為，寂寞是只屬於我的情感呢。",
  ui_story_5051_50510201_133_dialog_content = "抱歉，總是忙於政事，疏忽了妳和孩子們。",
  ui_story_5051_50510201_134_dialog_content = "呵呵，我開玩笑的啦～",
  ui_story_5051_50510201_135_dialog_content = "正因你的忙碌，人們才有如此和平的時光，去體會各種情感。",
  ui_story_5051_50510201_136_dialog_content = "幸福、快樂、歡喜……也包括寂寞。",
  ui_story_5051_50510201_137_dialog_content = "不過，現在有了北境女王的禮物。",
  ui_story_5051_50510201_138_dialog_content = "寂寞的時候，我只要進入「永憶鏡晶」裡的世界，就可以見到你了。",
  ui_story_5051_50510201_139_dialog_content = "約書亞……",
  ui_story_5051_50510201_140_dialog_content = "所以，讓我來啟動它，好嗎？",
  ui_story_5051_50510201_141_dialog_content = "沒問題，只要能讓妳開心。",
  ui_story_5051_50510201_142_dialog_content = "說來，妳打算把哪一天記錄到「永憶鏡晶」裡呢？",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>薇羅妮卡</color>的生日？卡蓮的演奏會？還是……",
  ui_story_5051_50510201_144_dialog_content = "暫時保密～",
  ui_story_5051_50510201_145_dialog_content = "拜託，告訴我吧！我可不想在那麼重要的日子裡出什麼糗。",
  ui_story_5051_50510201_146_dialog_content = "天啊，我們偉大的城主殿下居然也會出糗嗎？",
  ui_story_5051_50510201_147_dialog_content = "……比如，不小心踩壞卡蓮的玩具。",
  ui_story_5051_50510201_148_dialog_content = "當時看她沒有反應，就沒放在心上，沒想到她事後躲起來哭了很久……",
  ui_story_5051_50510201_149_dialog_content = "喔對！當時你抱著新玩具，垮著臉站在門外遲遲不敢進去，嚇壞了好多僕人呢。",
  ui_story_5051_50510201_150_dialog_content = "還有嗎？",
  ui_story_5051_50510201_151_dialog_content = "……還有，把薇羅妮卡送的玫瑰花環忘在會客廳裡。",
  ui_story_5051_50510201_152_dialog_content = "當時忙著會客，讓她誤以為我不喜歡那份禮物，隨手丟掉了……",
  ui_story_5051_50510201_153_dialog_content = "事後，你特地派人種了一大片玫瑰園。",
  ui_story_5051_50510201_154_dialog_content = "可惜從那之後，那孩子就沉迷訓練，再也沒編過花環了……",
  ui_story_5051_50510201_155_dialog_content = "哎……",
  ui_story_5051_50510201_156_dialog_content = "親愛的狄安理，這些並不是什麼糗事。",
  ui_story_5051_50510201_157_dialog_content = "這個世界太複雜，而我們能做到的、能看到的事情都太有限了。",
  ui_story_5051_50510201_158_dialog_content = "我覺得，「永憶鏡晶」是一個很好的機會……一個可以毫無保留地記錄我們的機會。",
  ui_story_5051_50510201_159_dialog_content = "回憶總是片面的，但真實的我們，會在這顆水晶球裡永遠保存下去。",
  ui_story_5051_50510201_160_dialog_content = "好的、壞的、對的、錯的……有朝一日，當我們和孩子們感到迷茫困惑的時候……",
  ui_story_5051_50510201_161_dialog_content = "一定可以從這裡面，找到<color=#FFB400>真實的答案</color>。",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>匡當！</color>",
  ui_story_5051_50510201_163_dialog_content = "……",
  ui_story_5051_50510201_164_dialog_content = "何人藏身此處？速速現身！",
  ui_story_5051_50510201_165_dialog_content = "我，是我！PlayerName！抱歉，哈哈哈……",
  ui_story_5051_50510201_166_dialog_content = "我來總結一下。",
  ui_story_5051_50510201_167_dialog_content = "您為了將禮物交給城主殿下，誤打誤撞進入了會客廳。",
  ui_story_5051_50510201_168_dialog_content = "沒想到，殿下一行人突然到來，您下意識躲了起來，錯過了打招呼的時機。",
  ui_story_5051_50510201_169_dialog_content = "所以才躲在窗簾後面，一直偷聽到現在。",
  ui_story_5051_50510201_170_dialog_content = "我說得沒錯吧？",
  ui_story_5051_50510201_171_dialog_content = "對，沒錯，對不起……",
  ui_story_5051_50510201_172_dialog_content = "（準確來說，是蜜雅下意識躲了起來，我也就跟著……）",
  ui_story_5051_50510201_173_dialog_content = "（不過讓混亂之中的蜜雅直接找城主認親，的確有點太著急了。）",
  ui_story_5051_50510201_174_dialog_content = "年輕人，我先謝過你的好意。",
  ui_story_5051_50510201_175_dialog_content = "但是偷聽的行為，可稱不上正人君子。",
  ui_story_5051_50510201_176_dialog_content = "下不為例。",
  ui_story_5051_50510201_177_dialog_content = "好的，謝謝您……",
  ui_story_5051_50510201_178_dialog_content = "那麼，我再問你一個問題。",
  ui_story_5051_50510201_179_dialog_content = "藏於桌布之下的鼠輩，是你的友人嗎？",
  ui_story_5051_50510201_180_dialog_content = "若不是，那紅女士便沒有手下留情的必要了。",
  ui_story_5051_50510201_X177_dialog_content = "那麼，我再問您一個問題。",
  ui_story_5051_50510201_X178_dialog_content = "藏在桌布下面的小老鼠，是您的朋友嗎？",
  ui_story_5051_50510201_X179_dialog_content = "如果不是的話，我可要把「牠」掃地出門囉。",
  ui_story_5051_50510201_181_dialog_content = "啊啊啊！是的是的！",
  ui_story_5051_50510201_182_dialog_content = "出來吧，蜜雅。放心，大家都是好人，別害怕。",
  ui_story_5051_50510201_183_dialog_content = "等、等一下，PlayerName我的面紗不見了……",
  ui_story_5051_50510201_184_dialog_content = "是白夜貴族？但是這樣貌……",
  ui_story_5051_50510201_185_dialog_content = "哎呀……",
  ui_story_5051_50510201_186_dialog_content = "……",
  ui_story_5051_50510201_187_dialog_content = "紅女士，這也是妳替我準備的「驚喜」嗎？",
  ui_story_5051_50510201_188_dialog_content = "算了，在那之前，先幫我調整一下行程吧。",
  ui_story_5051_50510201_189_dialog_content = "萬分抱歉，這是我的疏忽。我先去為您取消之後的行程。",
  ui_story_5051_50510201_190_dialog_content = "麻煩了。",
  ui_story_5051_50510201_191_dialog_content = "這個再加上這個……拼拼湊湊……有了！",
  ui_story_5051_50510201_192_dialog_content = "找到了！我找到適合的咒語了！",
  ui_story_5051_50510201_193_dialog_content = "北境使者，不必了，也請妳和PlayerName繼續去享受宴會吧。",
  ui_story_5051_50510201_194_dialog_content = "接下來，我們三人得單獨談談……",
  ui_story_5051_50510201_195_dialog_content = "咳咳，加晴，那我們不如就先出去……加晴？",
  ui_story_5051_50510201_196_dialog_content = "艾·普勒塔立吐姆，艾·普勒塔立吐姆，艾·普勒塔立吐姆！",
  ui_story_5051_50510201_197_dialog_content = "讓我們走進那段往日時光吧！",
  ui_story_5051_50510201_198_dialog_content = "<size=45>阿布拉「哈」達布拉！</size>",
  ui_story_5051_50510201_199_dialog_content = "什……？！",
  ui_story_5051_50510201_200_dialog_content = "<size=45>怎、怎麼回事？！</size>",
  ui_story_5051_50510201_201_dialog_content = "PlayerName……救命……",
  ui_story_5051_50510201_202_dialog_content = "蜜雅！抓住我的手！！",
  ui_story_5051_50510201_203_dialog_content = "嗯……！",
  ui_story_5051_50510201_204_dialog_content = "呃……嗯……？",
  ui_story_5051_50510201_205_dialog_content = "這裡是哪裡……？",
  ui_story_5051_50510201_206_dialog_content = "太、太好了，你終於醒了！",
  ui_story_5051_50510201_207_dialog_content = "蜜雅，這裡在哪裡？",
  ui_story_5051_50510201_208_dialog_content = "我也不知道……！我們快跑吧，暗鬼來了！",
  ui_story_5051_50510201_209_dialog_content = "——！！",
  ui_story_5051_50510201_210_dialog_content = "暗鬼？！",
  ui_story_5051_50510201_211_dialog_content = "蜜雅，抓住我！往這邊跑！",
  ui_story_5051_50510201_212_dialog_content = "PlayerName，那、那邊也有……",
  ui_story_5051_50510201_213_dialog_content = "——！！",
  ui_story_5051_50510201_214_dialog_content = "我們被包圍了？！",
  ui_story_5051_50510201_215_dialog_content = "芭、芭芭雅嘎！芭芭雅嘎，救命啊！",
  ui_story_5051_50510201_216_dialog_content = "求求妳，為什麼不回應我……",
  ui_story_5051_50510201_217_dialog_content = "可惡……蜜雅，千萬別離開我身後！",
  ui_story_5051_50510201_218_dialog_content = "這群該死的暗鬼，我跟你們拼了！！",
  ui_story_5051_50510201_219_dialog_content = "<size=45>吼——！！</size>",
  ui_story_5051_50510201_220_dialog_content = "不要……",
  ui_story_5051_50510201_221_dialog_content = "不要…………",
  ui_story_5051_50510201_222_dialog_content = "<size=45>不要傷害PlayerName！！！</size>",
  ui_story_5051_50510201_223_dialog_content = "嘎？！",
  ui_story_5051_50510201_224_dialog_content = "蜜、蜜雅……？",
  ui_story_5051_50510201_225_dialog_content = "哈、哈、哈……",
  ui_story_5051_50510201_226_dialog_content = "我……？這是，光能術……？",
  ui_story_5051_50510201_227_dialog_content = "蜜雅，原來妳也能使用光能術！",
  ui_story_5051_50510201_228_dialog_content = "以前的確可以，只是很久都沒成功過了……",
  ui_story_5051_50510201_229_dialog_content = "——！！",
  ui_story_5051_50510201_230_dialog_content = "怎麼還來？！到底有多少啊！",
  ui_story_5051_50510201_231_dialog_content = "妳還能繼續戰鬥嗎？",
  ui_story_5051_50510201_232_dialog_content = "我、我不知道……",
  ui_story_5051_50510201_233_dialog_content = "但是，不戰鬥，PlayerName就會有危險。",
  ui_story_5051_50510201_234_dialog_content = "我想保護PlayerName！",
  ui_story_5051_50510201_235_dialog_content = "蜜雅，妳沒問題的！",
  ui_story_5051_50510201_236_dialog_content = "只要妳能使用光能術，我就能激發妳的力量。",
  ui_story_5051_50510201_237_dialog_content = "相信我，也相信妳自己！",
  ui_story_5051_50510201_238_dialog_content = "相信你，相信自己……",
  ui_story_5051_50510201_239_dialog_content = "好，我試試看！",
  ui_story_5051_50510301_1_dialog_content = "蜜雅，妳還好嗎？",
  ui_story_5051_50510301_2_dialog_content = "我沒事，雖然心裡還是有點慌……",
  ui_story_5051_50510301_3_dialog_content = "但總覺得，稍微恢復一點自信了！",
  ui_story_5051_50510301_4_dialog_content = "PlayerName，你沒被剛剛的戰鬥波及到吧？",
  ui_story_5051_50510301_5_dialog_content = "完全沒有，不用擔心我！",
  ui_story_5051_50510301_6_dialog_content = "蜜雅好厲害啊，一個人居然就能擊退這麼多暗鬼。",
  ui_story_5051_50510301_7_dialog_content = "有、有嗎？我覺得，這都是多虧了你。",
  ui_story_5051_50510301_8_dialog_content = "空之末裔的力量，真神奇啊……",
  ui_story_5051_50510301_9_dialog_content = "說到這個，醒來之後我就感應不到其他人了。",
  ui_story_5051_50510301_10_dialog_content = "大家都去哪了？這裡到底是哪裡啊！",
  ui_story_5051_50510301_11_dialog_content = "你看那邊，遠遠地能看到<color=#FFB400>白夜城</color>。",
  ui_story_5051_50510301_12_dialog_content = "也就是說，這裡是<color=#FFB400>白夜城的郊外</color>？",
  ui_story_5051_50510301_13_dialog_content = "我們怎麼會突然來到這裡……",
  ui_story_5051_50510301_14_dialog_content = "難道說，這裡是「<color=#FFB400>永憶鏡晶</color>」裡面的世界？",
  ui_story_5051_50510301_15_dialog_content = "還真有可能！",
  ui_story_5051_50510301_16_dialog_content = "艾·普勒塔立吐姆，艾·普勒塔立吐姆，艾·普勒塔立吐姆！",
  ui_story_5051_50510301_17_dialog_content = "讓我們走進那段往日時光吧！",
  ui_story_5051_50510301_18_dialog_content = "阿布拉「哈」達布拉！",
  ui_story_5051_50510301_19_dialog_content = "我想起來了……加晴真是個厲害的占卜師。",
  ui_story_5051_50510301_20_dialog_content = "就是有時候，太心急了。",
  ui_story_5051_50510301_21_dialog_content = "是呀……",
  ui_story_5051_50510301_22_dialog_content = "我記得她還說過……",
  ui_story_5051_50510301_23_dialog_content = "「使用者進入後會預設保持隱身狀態，不能與任何人事物產生交集。」",
  ui_story_5051_50510301_24_dialog_content = "「否則要是一不小心改變了既定故事，就會引發難以想像的災難。」",
  ui_story_5051_50510301_25_dialog_content = "不過，我們剛剛就被暗鬼發現了。",
  ui_story_5051_50510301_26_dialog_content = "這又是怎麼回事呢……",
  ui_story_5051_50510301_27_dialog_content = "<size=45>嗚哇啊！！</size>",
  ui_story_5051_50510301_28_dialog_content = "慘、慘叫聲！",
  ui_story_5051_50510301_29_dialog_content = "那是……",
  ui_story_5051_50510301_30_dialog_content = "隊長！暗鬼數量太多了，我們已經……",
  ui_story_5051_50510301_31_dialog_content = "集中注意力！哪怕身旁的同伴倒下了，也不能放下武器！",
  ui_story_5051_50510301_32_dialog_content = "可惡啊！！！",
  ui_story_5051_50510301_33_dialog_content = "貨車、白夜城的士兵……暗鬼正在襲擊白夜城的運輸隊！",
  ui_story_5051_50510301_34_dialog_content = "白夜城外怎麼有這麼多暗鬼？到底發生什麼事了？！",
  ui_story_5051_50510301_35_dialog_content = "我、我們得去救他們！",
  ui_story_5051_50510301_36_dialog_content = "等等！加晴說過，我們不能擅自干預「永憶鏡晶」裡面的世界。",
  ui_story_5051_50510301_37_dialog_content = "如果再和暗鬼戰鬥的話，說不定會引起更大的麻煩。",
  ui_story_5051_50510301_38_dialog_content = "可是……",
  ui_story_5051_50510301_39_dialog_content = "「反抗吧，在面對墳墓之前！」",
  ui_story_5051_50510301_40_dialog_content = "——？！",
  ui_story_5051_50510301_41_dialog_content = "老大，白夜城的士兵沒有大礙，我們可以收工了。",
  ui_story_5051_50510301_42_dialog_content = "不過既然舒瓦茲那傢伙都不管我們死活，我們幹嘛要救他的走狗。",
  ui_story_5051_50510301_43_dialog_content = "明明在過節，卻連食宿也不幫我們準備，收了禮物就把人趕出來。",
  ui_story_5051_50510301_44_dialog_content = "也太不夠意思了吧。",
  ui_story_5051_50510301_45_dialog_content = "別被眼前的蠅頭小利沖昏頭。時機成熟，答案自會浮上水面。",
  ui_story_5051_50510301_46_dialog_content = "是<color=#FFB400>伊斯塔萬</color>老爹……！",
  ui_story_5051_50510301_47_dialog_content = "那是伊斯塔萬？！看起來好年輕啊！",
  ui_story_5051_50510301_48_dialog_content = "什……",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>轟隆——匡當！</color>",
  ui_story_5051_50510301_50_dialog_content = "（雷聲？明明是大晴天，要下雨了嗎？）",
  ui_story_5051_50510301_51_dialog_content = "PlayerName！危險！！",
  ui_story_5051_50510301_52_dialog_content = "怎麼還有暗鬼？！",
  ui_story_5051_50510301_53_dialog_content = "到底有完沒完！",
  ui_story_5051_50510302_1_dialog_content = "哈、哈、哈……",
  ui_story_5051_50510302_2_dialog_content = "應該，不會再來了吧？我已經，到極限了……",
  ui_story_5051_50510302_3_dialog_content = "<color=#FFB400>薇羅妮卡</color>公主殿下，您沒事吧？",
  ui_story_5051_50510302_4_dialog_content = "薇羅妮卡公主殿下？真的是公主殿下！",
  ui_story_5051_50510302_5_dialog_content = "公主殿下怎麼會在這裡？！",
  ui_story_5051_50510302_6_dialog_content = "唔，我、沒事。",
  ui_story_5051_50510302_7_dialog_content = "那就好。",
  ui_story_5051_50510302_8_dialog_content = "今日您驍勇善戰的模樣，與平日的印象相去甚遠。",
  ui_story_5051_50510302_9_dialog_content = "起初我還不敢與您相認，看來是我有眼無珠。",
  ui_story_5051_50510302_10_dialog_content = "不，請您別這麼說！",
  ui_story_5051_50510302_11_dialog_content = "今天只是……有點特殊狀況。",
  ui_story_5051_50510302_12_dialog_content = "（嗯？蜜雅看著我幹什麼？）",
  ui_story_5051_50510302_13_dialog_content = "如此重要的日子，不知您為何會身在此處。",
  ui_story_5051_50510302_14_dialog_content = "也罷……這些事不是我可以操心的。但出門在外，還請您多加小心。",
  ui_story_5051_50510302_15_dialog_content = "謝、謝謝您。",
  ui_story_5051_50510302_16_dialog_content = "方才我與城主大人相見匆忙，也沒能與約書亞夫人敘舊。",
  ui_story_5051_50510302_17_dialog_content = "麻煩公主殿下代我向她問好。",
  ui_story_5051_50510302_18_dialog_content = "可以的話，也希望城主大人能盡快答覆。",
  ui_story_5051_50510302_19_dialog_content = "好的……我一定向家父家母帶到，感謝您平日的照顧。",
  ui_story_5051_50510302_20_dialog_content = "哪裡，都是分內之事。",
  ui_story_5051_50510302_21_dialog_content = "（蜜雅真的是公主！）",
  ui_story_5051_50510302_22_dialog_content = "旁邊的那位少年。",
  ui_story_5051_50510302_23_dialog_content = "我？",
  ui_story_5051_50510302_24_dialog_content = "對，想必你一定是公主殿下重要的友人吧。",
  ui_story_5051_50510302_25_dialog_content = "否則，也不是誰都能有受公主殿下保護的榮幸。",
  ui_story_5051_50510302_26_dialog_content = "男子漢最好還是靠自己的雙手打天下。",
  ui_story_5051_50510302_27_dialog_content = "不要老是躲在別人身後。",
  ui_story_5051_50510302_28_dialog_content = "好、好的……",
  ui_story_5051_50510302_29_dialog_content = "那個，請問，我們之前見過嗎？",
  ui_story_5051_50510302_30_dialog_content = "哈哈哈！這種老套說詞，哪怕是我也有十幾年沒聽過了。",
  ui_story_5051_50510302_31_dialog_content = "答案是「沒有」。",
  ui_story_5051_50510302_32_dialog_content = "有趣的小子，如果你還想見到我，就來影鎮吧。",
  ui_story_5051_50510302_33_dialog_content = "那裡即將變成影子的帝國。",
  ui_story_5051_50510302_34_dialog_content = "影子能包容一切。但要在這當中生存，就得看你的本事了。",
  ui_story_5051_50510302_35_dialog_content = "包容一切啊……也是呢。",
  ui_story_5051_50510302_36_dialog_content = "伊斯塔萬……叔叔的影鎮，一定會是個好地方。",
  ui_story_5051_50510302_37_dialog_content = "能獲得公主殿下的信賴，真是備感榮幸。",
  ui_story_5051_50510302_38_dialog_content = "好了，時候不早，我們要啟程了。",
  ui_story_5051_50510302_39_dialog_content = "薇羅妮卡公主殿下、有趣的小子，再會了。",
  ui_story_5051_50510302_40_dialog_content = "再見……這個伊斯塔萬，總覺得比我認識的那個還要開朗。",
  ui_story_5051_50510302_41_dialog_content = "真是種奇妙的感受。",
  ui_story_5051_50510302_42_dialog_content = "嗯，我記得以前的伊斯塔萬老爹，比現在更加意氣風發一些。",
  ui_story_5051_50510302_43_dialog_content = "後來發生了好多好多事……大家漸漸都變了呢。",
  ui_story_5051_50510302_44_dialog_content = "蜜雅，妳就是「薇羅妮卡」公主？",
  ui_story_5051_50510302_45_dialog_content = "與伊斯塔萬說話也能對答如流，和平常那個害羞內向的蜜雅簡直判若兩人。",
  ui_story_5051_50510302_46_dialog_content = "是、是嗎？",
  ui_story_5051_50510302_47_dialog_content = "我只能想起一些過去的片段，還沒辦法拼湊出完整的回憶。",
  ui_story_5051_50510302_48_dialog_content = "但不知為何，看到年輕的伊斯塔萬老爹之後……",
  ui_story_5051_50510302_49_dialog_content = "我的身體似乎比我更早回憶起相應的言詞禮儀。",
  ui_story_5051_50510302_50_dialog_content = "抱歉，我也說不上來。",
  ui_story_5051_50510302_51_dialog_content = "沒關係。本來妳就是來尋根的，結果中途發生這麼多事，暫時理不清頭緒也很正常。",
  ui_story_5051_50510302_52_dialog_content = "蜜雅，可以跟我說說妳記憶中的薇羅妮卡公主嗎？",
  ui_story_5051_50510302_53_dialog_content = "嗯，沒問題。",
  ui_story_5051_50510302_54_dialog_content = "薇羅妮卡是白夜城的<color=#FFB400>公主</color>，舒瓦茲的<color=#FFB400>大女兒</color>——",
  ui_story_5051_50510302_55_dialog_content = "但是多年前，白夜城對外宣佈了她的<color=#FFB400>死訊</color>……",
  ui_story_5051_50510302_56_dialog_content = "死訊？為什麼？",
  ui_story_5051_50510302_57_dialog_content = "因為她玷污了舒瓦茲家的榮譽。",
  ui_story_5051_50510302_58_dialog_content = "所以，不祥的薇羅妮卡，便沒有資格繼續活下去了。",
  ui_story_5051_50510302_59_dialog_content = "榮譽？不祥？什麼跟什麼……",
  ui_story_5051_50510302_60_dialog_content = "這就是貴族生活的方式。對於貴族來說，面子比什麼都重要……",
  ui_story_5051_50510302_61_dialog_content = "PlayerName，你知道「<color=#FFB400>光能召喚物</color>」吧？",
  ui_story_5051_50510302_62_dialog_content = "除了芭芭雅嘎，在記憶中，我還有一個有點可怕的朋友，叫做「希頗喀」。",
  ui_story_5051_50510302_63_dialog_content = "他是我的光能召喚物。小時候我為了變得更強大，不斷磨練自己……",
  ui_story_5051_50510302_64_dialog_content = "最後得到的結果，就是「希頗喀」。",
  ui_story_5051_50510302_65_dialog_content = "只是，大家都不喜歡他的樣貌——馬頭蛛身，大家都說，他像個怪物。",
  ui_story_5051_50510302_66_dialog_content = "那個人……我的父親，尤其討厭他。他說「希頗喀」為家族惹來無謂的非議。",
  ui_story_5051_50510302_67_dialog_content = "不祥的「希頗喀」不應該存在……久而久之，我也開始對他產生恐懼。",
  ui_story_5051_50510302_68_dialog_content = "明明「希頗喀」就是我本質的體現，但我卻因為他人的質疑不斷抵抗他。",
  ui_story_5051_50510302_69_dialog_content = "到最後，我便失去了使用光能術的資格。",
  ui_story_5051_50510302_70_dialog_content = "後來，和「希頗喀」有幾分相似的芭芭雅嘎現身取而代之，並繼承了一切。",
  ui_story_5051_50510302_71_dialog_content = "這麼看，真是報應一場啊。",
  ui_story_5051_50510302_72_dialog_content = "好可憐的薇羅妮卡公主……",
  ui_story_5051_50510302_73_dialog_content = "不過，現在這裡的人們依舊稱呼妳為薇羅妮卡，也就是說……",
  ui_story_5051_50510302_74_dialog_content = "公主殿下！感謝您剛剛的出手相助！",
  ui_story_5051_50510302_75_dialog_content = "沒事，小、小事一樁。",
  ui_story_5051_50510302_76_dialog_content = "你們還好嗎？",
  ui_story_5051_50510302_77_dialog_content = "請放心，大家只是受了點傷，現在已經重新整備好，可以出發了。",
  ui_story_5051_50510302_78_dialog_content = "方便的話，兩位可以跟我們一起回城。",
  ui_story_5051_50510302_79_dialog_content = "那真是太好了。",
  ui_story_5051_50510302_80_dialog_content = "等一下。請問，今年是哪一年？",
  ui_story_5051_50510302_81_dialog_content = "哪一年？<color=#FFB400>晨光曆1988年</color>啊，怎麼了嗎？",
  ui_story_5051_50510302_82_dialog_content = "（1988年，也就是……<color=#FFB400>十二年前</color>！）",
  ui_story_5051_50510302_83_dialog_content = "（十二年前的話，空之山谷已經覆滅了。）",
  ui_story_5051_50510302_84_dialog_content = "（也就是說，即使在「永憶鏡晶」的世界裡，我也不可能見到其他族人嗎……）",
  ui_story_5051_50510302_85_dialog_content = "PlayerName你怎麼了……？",
  ui_story_5051_50510302_86_dialog_content = "我沒事，蜜雅妳可以過來一下嗎？",
  ui_story_5051_50510302_87_dialog_content = "怎、怎麼了？",
  ui_story_5051_50510302_88_dialog_content = "看來「永憶鏡晶」裡的世界，就是「<color=#FFB400>十二年前的白夜城</color>」。",
  ui_story_5051_50510302_89_dialog_content = "如果我沒猜錯，之前會客廳裡的其他人，應該也都進入了這個世界。",
  ui_story_5051_50510302_90_dialog_content = "雖然加晴說過，不能干涉「永憶鏡晶」裡的世界。",
  ui_story_5051_50510302_91_dialog_content = "但現在情況特殊，我們無法隱藏自己，我的感應能力也無法找到大家。",
  ui_story_5051_50510302_92_dialog_content = "不如藉著妳公主的身分快點找到大家，一起設法離開吧。",
  ui_story_5051_50510302_93_dialog_content = "……",
  ui_story_5051_50510302_94_dialog_content = "蜜雅，怎麼了？",
  ui_story_5051_50510302_95_dialog_content = "那個，PlayerName。",
  ui_story_5051_50510302_96_dialog_content = "我、我們可不可以，在離開前，先去看看我媽媽？",
  ui_story_5051_50510302_97_dialog_content = "剛剛我在桌子底下聽到了。媽媽在我離開的期間，去世了。",
  ui_story_5051_50510302_98_dialog_content = "我本來想，回到白夜城就可以見到妹妹和媽媽，然後和她們說好多話。",
  ui_story_5051_50510302_99_dialog_content = "「我長大了，變得更勇敢了」、「我在外面交到了好多新朋友」。",
  ui_story_5051_50510302_100_dialog_content = "「媽媽，我真的好想妳」……",
  ui_story_5051_50510302_101_dialog_content = "但是，已經沒有機會了。",
  ui_story_5051_50510302_102_dialog_content = "……蜜雅的媽媽，是城主大人的妻子。",
  ui_story_5051_50510302_103_dialog_content = "如果她能幫助我們，一定能更快找到大家！",
  ui_story_5051_50510302_104_dialog_content = "所以，去見她也是為了所有人，不是嗎？",
  ui_story_5051_50510302_105_dialog_content = "唔……PlayerName，這種說法總覺得有點太狡猾了……",
  ui_story_5051_50510302_106_dialog_content = "嘿嘿，偶爾狡猾一點也不壞。",
  ui_story_5051_50510302_107_dialog_content = "這可是巨像上的同伴教我的處事方式喔。",
  ui_story_5051_50510302_108_dialog_content = "嗯，那我也學習一下好了。",
  ui_story_5051_50510302_109_dialog_content = "總、總有一種我在教蜜雅學壞的感覺。",
  ui_story_5051_50510302_110_dialog_content = "那個……兩位說完了嗎？再不出發就來不及了。",
  ui_story_5051_50510302_111_dialog_content = "啊，抱歉抱歉，我們準備好了！",
  ui_story_5051_50510302_112_dialog_content = "聽起來運輸隊似乎在趕時間，請問你們有什麼急事嗎？",
  ui_story_5051_50510302_113_dialog_content = "也不算急事，只是這些物資得提前送到，確切來說就是……",
  ui_story_5051_50510302_114_dialog_content = "趕在「<color=#FFB400>舒瓦茲家族日</color>」慶典開始前。",
  ui_story_5051_50510302_115_dialog_content = "（「舒瓦茲家族日」？這也太巧了吧。）",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>轟隆——</color>",
  ui_story_5051_50510302_117_dialog_content = "又是雷聲……",
  ui_story_5051_50510302_118_dialog_content = "您怎麼了嗎？",
  ui_story_5051_50510302_119_dialog_content = "沒什麼。趁還沒下雨，我們趕快出發吧！",
  ui_story_5051_50510302_120_dialog_content = "下雨？今天會下雨嗎？好吧，我們馬上啟程。",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>……舒…………</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>…………瓦茲…………</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>………………</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "…………",
  ui_story_5051_50510402_2_dialog_content = "呼……怎麼連這種地方都有暗鬼藏身？",
  ui_story_5051_50510402_3_dialog_content = "白夜城什麼時候成了暗鬼巢穴了？",
  ui_story_5051_50510402_4_dialog_content = "哇～得救了得救了！",
  ui_story_5051_50510402_5_dialog_content = "要不是凱萊布先生及時出現，我差點就要變成暗鬼的晚餐了……",
  ui_story_5051_50510402_6_dialog_content = "不對，現在是白天，應該是午餐。",
  ui_story_5051_50510402_7_dialog_content = "針對這一點，我也很疑惑。",
  ui_story_5051_50510402_8_dialog_content = "加晴小姐，剛剛我們還在白夜城宮內，時間是夜晚。",
  ui_story_5051_50510402_9_dialog_content = "怎麼現在突然來到野外的樹林，還變成了白天。",
  ui_story_5051_50510402_10_dialog_content = "難道，這裡是「永憶鏡晶」裡面的世界？",
  ui_story_5051_50510402_11_dialog_content = "沒錯！哎呀～沒想到那個隨便湊湊的咒語居然真的能成功～",
  ui_story_5051_50510402_12_dialog_content = "說不定我是個天才……？",
  ui_story_5051_50510402_13_dialog_content = "（您還真是太「天才」了。）",
  ui_story_5051_50510402_14_dialog_content = "就不遠處的建築風格來看，這裡是白夜城下城的郊區。",
  ui_story_5051_50510402_15_dialog_content = "而加晴小姐妳剛剛不小心坐壞的那個箱子——",
  ui_story_5051_50510402_16_dialog_content = "從上面的標誌來看，似乎是為了慶祝「舒瓦茲家族日」而準備的物資。",
  ui_story_5051_50510402_17_dialog_content = "剛才嚇死我了！",
  ui_story_5051_50510402_18_dialog_content = "那個看起來很堅固的箱子，一坐上去居然直接裂開了！",
  ui_story_5051_50510402_19_dialog_content = "而且還跳出好幾隻暗鬼！",
  ui_story_5051_50510402_20_dialog_content = "這到底是怎麼回事啊？別告訴我你們白夜城人有飼養暗鬼的怪癖。",
  ui_story_5051_50510402_21_dialog_content = "請放心，這座城還沒爛到會以飼養無法溝通的敵對種族為樂。",
  ui_story_5051_50510402_22_dialog_content = "「舒瓦茲家族日」、暗鬼……原來如此，這裡是十二年前的白夜城吧。",
  ui_story_5051_50510402_23_dialog_content = "利用大規模運輸貨物的機會，將暗鬼混入其中，這場混亂的製造者還真大膽。",
  ui_story_5051_50510402_24_dialog_content = "你的意思是……十二年前，暗鬼入侵過白夜城？",
  ui_story_5051_50510402_25_dialog_content = "是啊，雖然不知外界如何評價這座偉岸的天空之城。",
  ui_story_5051_50510402_26_dialog_content = "但是，這座城其實沒有看起來那麼堅不可摧。",
  ui_story_5051_50510402_27_dialog_content = "那個，凱萊布先生……",
  ui_story_5051_50510402_28_dialog_content = "你在和我碰頭前，有見到其他人嗎？",
  ui_story_5051_50510402_29_dialog_content = "沒有。其實我醒來後沒走兩步，就遇到妳了。",
  ui_story_5051_50510402_30_dialog_content = "哈、哈哈……照理說，傳送之後我們應該要待在一起的。",
  ui_story_5051_50510402_31_dialog_content = "而且也不應該被暗鬼發現。",
  ui_story_5051_50510402_32_dialog_content = "看來還是出了點小問題呢～",
  ui_story_5051_50510402_33_dialog_content = "……加晴小姐，我有一個問題。",
  ui_story_5051_50510402_34_dialog_content = "呃咳咳咳，不要擔心！我一定會負起責任，安然無恙把大家帶出去的！",
  ui_story_5051_50510402_35_dialog_content = "我想問的不是這個。",
  ui_story_5051_50510402_36_dialog_content = "我是想問「永憶鏡晶」啟動者的光能，是否就在這個世界裡呢？",
  ui_story_5051_50510402_37_dialog_content = "對，就在這裡！",
  ui_story_5051_50510402_38_dialog_content = "那麼，確切在什麼地方呢？",
  ui_story_5051_50510402_39_dialog_content = "確、確切在什麼地方？我看看喔……",
  ui_story_5051_50510402_40_dialog_content = "「啟動者必須用光能啟動『永憶鏡晶』，這是驅動世界運轉的重要能源。」",
  ui_story_5051_50510402_41_dialog_content = "<size=30>怎麼只有這一句話！</size>",
  ui_story_5051_50510402_42_dialog_content = "咳、咳咳，作為「永憶鏡晶」的重要能源，光能一定保存在最重要的地方！",
  ui_story_5051_50510402_43_dialog_content = "「永憶鏡晶」中最重要的地方，那一定就是——",
  ui_story_5051_50510402_44_dialog_content = "這個世界的「永憶鏡晶」！",
  ui_story_5051_50510402_45_dialog_content = "有幾分道理……",
  ui_story_5051_50510402_46_dialog_content = "我還有個問題，既然是以光能為能源，自然也有耗盡的一天吧。",
  ui_story_5051_50510402_47_dialog_content = "十二年已過，現在「永憶鏡晶」中的光能，還會剩下多少呢？",
  ui_story_5051_50510402_48_dialog_content = "啊，這件事你不用擔心～",
  ui_story_5051_50510402_49_dialog_content = "鏡湖之水都只需要十二年才補充一次，光能當然能維持更久！",
  ui_story_5051_50510402_50_dialog_content = "只是，如果做出一些擾亂世界秩序的事，很有可能會加劇光能的消耗。",
  ui_story_5051_50510402_51_dialog_content = "極端情況下，甚至會讓光能突然消耗殆盡。",
  ui_story_5051_50510402_52_dialog_content = "到時我們就小命難保了。",
  ui_story_5051_50510402_53_dialog_content = "這就是妳之前說的「難以想像的災難」？",
  ui_story_5051_50510402_54_dialog_content = "嗯，差不多吧。當然也不排除一些意料之外的情況……",
  ui_story_5051_50510402_55_dialog_content = "所以！我們得趕快找到大家！",
  ui_story_5051_50510402_56_dialog_content = "在無法隱身的情況下，我們可不能久留。",
  ui_story_5051_50510402_57_dialog_content = "妳說得對。那麼這項重任，就交給身為罪魁禍首的加晴小姐了。",
  ui_story_5051_50510402_58_dialog_content = "我還有別的事要辦，先告辭。",
  ui_story_5051_50510402_59_dialog_content = "哎？！你怎麼可以交給我一個人，轉頭就跑啊！",
  ui_story_5051_50510402_60_dialog_content = "而且我剛不是說過嗎？不可以任意行動！萬一干擾這個世界就糟了！",
  ui_story_5051_50510402_61_dialog_content = "我知道，我會嚴守規則，也希望妳能說服其他人乖乖照做。",
  ui_story_5051_50510402_62_dialog_content = "我也不希望再過度消耗本來就不多的光能。",
  ui_story_5051_50510402_63_dialog_content = "我警告你，這裡可是白夜城，萬一碰到過去的你自己，你要怎麼辦啊！",
  ui_story_5051_50510402_64_dialog_content = "放心，當年的這天，我被派去看守隨騎士團前往影鎮的外甥女，不在城中。",
  ui_story_5051_50510402_65_dialog_content = "哪怕是「永憶鏡晶」，也沒辦法記錄到那麼遠吧？",
  ui_story_5051_50510402_66_dialog_content = "確實……",
  ui_story_5051_50510402_67_dialog_content = "我會以賓客的身分混入城中，見到想見的人之後，就會回來找妳。",
  ui_story_5051_50510402_68_dialog_content = "哪怕冒著生命危險，你也想去見那個人？",
  ui_story_5051_50510402_69_dialog_content = "那是當然。往昔不可諫，像這樣能重拾遺落之物的機會，人生還能有幾次呢。",
  ui_story_5051_50510402_70_dialog_content = "那就麻煩妳盡快找齊其他人了。再見。",
  ui_story_5051_50510402_71_dialog_content = "等等！你還沒說要在哪裡跟我會合啊！",
  ui_story_5051_50510402_72_dialog_content = "居然走得這麼快，一溜煙就不見人影了……",
  ui_story_5051_50510402_73_dialog_content = "話說啊，這傢伙之前那副溫文儒雅的樣子，完全就是裝的吧！",
  ui_story_5051_50510402_74_dialog_content = "到了關鍵時刻，又冷漠又無情！",
  ui_story_5051_50510402_75_dialog_content = "啊——氣死我了！",
  ui_story_5051_50510402_76_dialog_content = "哎……「重拾遺落之物的機會」？",
  ui_story_5051_50510402_77_dialog_content = "我有沒有這樣的機會呢？",
  ui_story_5051_50510402_78_dialog_content = "媽媽，十二年前，妳把「永憶鏡晶」送給白夜城主，接著便返回北境。",
  ui_story_5051_50510402_79_dialog_content = "爸爸說妳是個摸不透的人，為了修行願意拋下家人，一聲不吭就跑進山中隱居。",
  ui_story_5051_50510402_80_dialog_content = "女王陛下說妳很偉大，是不食人間煙火的修行者……這麼看來，我和妳一點也不像。",
  ui_story_5051_50510402_81_dialog_content = "要是妳也在這裡的話，會對我說些什麼呢？",
  ui_story_5051_50510402_82_dialog_content = "……哎呀，我還在想東想西的！！",
  ui_story_5051_50510402_83_dialog_content = "加晴，集中！妳現在可是北境使者！",
  ui_story_5051_50510402_84_dialog_content = "哪怕別人都靠不住，妳也必須靠自己！一定要負起責任，把大家帶出去！",
  ui_story_5051_50510402_85_dialog_content = "呵……呼……",
  ui_story_5051_50510402_86_dialog_content = "好了！北境使者加晴，出發！",
  ui_story_5051_50510501_1_dialog_content = "（舒瓦茲那傢伙能藏匿「永憶鏡晶」的地方不多，八成就在這幢宅邸的某處。）",
  ui_story_5051_50510501_2_dialog_content = "（當年的「家族日」規模更大，為了維持秩序，守衛多半都被調往會場。）",
  ui_story_5051_50510501_3_dialog_content = "（現在只要等節日儀式開始，就可以從守衛薄弱的地方溜進去了。）",
  ui_story_5051_50510501_4_dialog_content = "（在那之前，就避開守衛的視線靜靜等待吧。）",
  ui_story_5051_50510501_5_dialog_content = "（我記得，花園那邊應該沒人……）",
  ui_story_5051_50510501_6_dialog_content = "（鳶尾花……花語是「好消息」、「思念」。）",
  ui_story_5051_50510501_7_dialog_content = "（我記得，這是姐姐為她的大女兒種的。）",
  ui_story_5051_50510501_8_dialog_content = "……我知道，你們的花期就快過了。",
  ui_story_5051_50510501_9_dialog_content = "但是可以再撐一下下嗎？",
  ui_story_5051_50510501_10_dialog_content = "我的女兒馬上就要回家了，我真的很希望她能看到你們。",
  ui_story_5051_50510501_11_dialog_content = "她以前是個很喜歡花的孩子，如果能看到你們，她一定會重拾笑容的。",
  ui_story_5051_50510501_12_dialog_content = "妳……妳是……",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>姐姐</color>……？",
  ui_story_5051_50510501_14_dialog_content = "哎呀。",
  ui_story_5051_50510501_15_dialog_content = "你好，陌生人。",
  ui_story_5051_50510501_16_dialog_content = "如此美好的下午，是什麼風把你吹到這裡來的呢？",
  ui_story_5051_50510501_17_dialog_content = "嗯……抱歉，我想問個有點唐突的問題。",
  ui_story_5051_50510501_18_dialog_content = "請問，我們見過面嗎？",
  ui_story_5051_50510501_19_dialog_content = "……不，我只是個小小貴族，沒有那種榮幸。",
  ui_story_5051_50510501_20_dialog_content = "初次見面，約書亞夫人。",
  ui_story_5051_50510501_21_dialog_content = "是這樣嗎？",
  ui_story_5051_50510501_22_dialog_content = "但是……不，算了，可能只是我一時看錯吧。",
  ui_story_5051_50510501_23_dialog_content = "（姐姐……）",
  ui_story_5051_50510501_24_dialog_content = "（原本找人的說詞，只是為了騙過北境占卜師一時編的藉口。）",
  ui_story_5051_50510501_25_dialog_content = "（沒想到，真的能在這裡見到妳。）",
  ui_story_5051_50510501_26_dialog_content = "（十二年了。闊別十二年，這是我第一次和妳說話。）",
  ui_story_5051_50510501_27_dialog_content = "（但卻只能這樣，假裝成陌生人……）",
  ui_story_5051_50510501_28_dialog_content = "（我來這個世界的目的，是拿回姐姐遺留的光能。）",
  ui_story_5051_50510501_29_dialog_content = "（不能干涉、不能停留。這只是北境祕術所創造的幻影罷了。）",
  ui_story_5051_50510501_30_dialog_content = "（快點結束這場鬧劇吧……！）",
  ui_story_5051_50510501_31_dialog_content = "你還好嗎？你看起來很難過的樣子……",
  ui_story_5051_50510501_32_dialog_content = "萬分抱歉。",
  ui_story_5051_50510501_33_dialog_content = "我還是第一次有幸和您這樣尊貴的人說話，稍微有點慌亂。",
  ui_story_5051_50510501_34_dialog_content = "哈哈，你騙人。",
  ui_story_5051_50510501_35_dialog_content = "你的眼角都泛淚光了。是不是哪裡受了傷，還是有什麼傷心事？",
  ui_story_5051_50510501_36_dialog_content = "別獨自逞強呀。",
  ui_story_5051_50510501_37_dialog_content = "……",
  ui_story_5051_50510501_38_dialog_content = "我、我沒有！",
  ui_story_5051_50510501_39_dialog_content = "我只是眼睛進沙子了！",
  ui_story_5051_50510501_40_dialog_content = "……那些學院裡的老古板，那些傻呼呼的學生，他們懂什麼！",
  ui_story_5051_50510501_41_dialog_content = "什麼叫「凱萊布，雖然你很聰明，但由於缺少父母管教，總是太過心高氣傲。」",
  ui_story_5051_50510501_42_dialog_content = "<size=30>沒有父母又怎麼樣！我有姐姐就夠了……</size>",
  ui_story_5051_50510501_43_dialog_content = "給我等著瞧！早晚有一天，我會改變這裡的一切！",
  ui_story_5051_50510501_44_dialog_content = "嗯，姐姐相信你。",
  ui_story_5051_50510501_45_dialog_content = "我的小天才從不吹牛，你說出口的事情，就一定會辦到。",
  ui_story_5051_50510501_46_dialog_content = "姐姐，妳真的相信我？",
  ui_story_5051_50510501_47_dialog_content = "嗯，那當然。",
  ui_story_5051_50510501_48_dialog_content = "姐姐……如果，有一天，所有人都不必再為食物和安全煩惱。",
  ui_story_5051_50510501_49_dialog_content = "妳是不是，也就不用每天輔佐那個狄安理了？",
  ui_story_5051_50510501_50_dialog_content = "嗯～如果真能變成那樣，政事一定會變少；但身為妻子，我還是得陪伴他呀。",
  ui_story_5051_50510501_51_dialog_content = "……",
  ui_story_5051_50510501_52_dialog_content = "不過，到時候我一定會來陪你做研究，還會出席你的每一場學術發表會，好不好？",
  ui_story_5051_50510501_53_dialog_content = "真的？",
  ui_story_5051_50510501_54_dialog_content = "真的。",
  ui_story_5051_50510501_55_dialog_content = "那……我要把發表會開到世界各地！",
  ui_story_5051_50510501_56_dialog_content = "姐姐，以前妳說妳想去環遊世界，但是結婚之後就再也不提了。",
  ui_story_5051_50510501_57_dialog_content = "既然如此，我就幫妳實現這個夢想。",
  ui_story_5051_50510501_58_dialog_content = "哎呀，你這孩子真是的，我怎麼又上了你的當呢？",
  ui_story_5051_50510501_59_dialog_content = "既然答應我了，就一定要來喔！",
  ui_story_5051_50510501_60_dialog_content = "好，好～我們一言為定。",
  ui_story_5051_50510501_61_dialog_content = "……我，只是，眼睛進沙子了。",
  ui_story_5051_50510501_62_dialog_content = "你看看你，皺著鼻子，強忍難過的樣子。",
  ui_story_5051_50510501_63_dialog_content = "簡直和我弟弟一模一樣……",
  ui_story_5051_50510501_64_dialog_content = "他有著遠超同齡人的智慧，但在某些時候，卻永遠像個可愛的孩子。",
  ui_story_5051_50510501_65_dialog_content = "比如說，每次哭鼻子的時候，都會用眼睛進沙子這種爛藉口蒙混過關。",
  ui_story_5051_50510501_66_dialog_content = "……哎呀，抱歉。",
  ui_story_5051_50510501_67_dialog_content = "因為您和家弟有幾分相似，我就下意識用這麼隨意的口吻和您說話了。",
  ui_story_5051_50510501_68_dialog_content = "如此有失禮數，實在是慚愧不已。",
  ui_story_5051_50510501_69_dialog_content = "不，請別這麼說……",
  ui_story_5051_50510501_70_dialog_content = "不過，真是不可思議呀，明明您和家弟的年齡相差很大。",
  ui_story_5051_50510501_71_dialog_content = "我卻能從您身上看到他的影子……",
  ui_story_5051_50510501_72_dialog_content = "今日的宴會，我會為您提供貴賓席作為賠禮。",
  ui_story_5051_50510501_73_dialog_content = "如果有任何不便，可以報上我的名字。",
  ui_story_5051_50510501_74_dialog_content = "有任何困難，都可以向我開口。",
  ui_story_5051_50510501_75_dialog_content = "所以，有事千萬別一個人撐著。",
  ui_story_5051_50510501_76_dialog_content = "感謝您的好意。我只是前來辦事途經此處，無意參與慶典。",
  ui_story_5051_50510501_77_dialog_content = "這裡的花令我有些觸景生情，不禁駐足，打擾您了。",
  ui_story_5051_50510501_78_dialog_content = "那麼，我先行告退……還請您多多保重。",
  ui_story_5051_50510501_79_dialog_content = "哎呀，怎麼這麼快……",
  ui_story_5051_50510501_80_dialog_content = "至少留下您的名字呀。",
  ui_story_5051_50510501_81_dialog_content = "雖然認識的人都變了……",
  ui_story_5051_50510501_82_dialog_content = "但唯獨白夜城還是和現在一模一樣。",
  ui_story_5051_50510501_83_dialog_content = "沒錯呢。這聖潔而堅固的城牆正是白夜城的象徵，也是人們的信仰所在。",
  ui_story_5051_50510501_84_dialog_content = "所以，多年來大家不惜一切代價，只為守護它的潔白……看來，一切犧牲都是值得的。",
  ui_story_5051_50510501_85_dialog_content = "請出示入城許可證，喂，沒聽到嗎？",
  ui_story_5051_50510501_86_dialog_content = "啊，我……",
  ui_story_5051_50510501_87_dialog_content = "那個，他是我的朋友。",
  ui_story_5051_50510501_88_dialog_content = "薇、薇羅妮卡公主？！",
  ui_story_5051_50510501_89_dialog_content = "請進！請恕在下方才無禮！",
  ui_story_5051_50510501_90_dialog_content = "沒關係。過節還要站崗，真是辛苦你啦，加油喔。",
  ui_story_5051_50510501_91_dialog_content = "遵命！",
  ui_story_5051_50510501_92_dialog_content = "呼～公主的身分真好用啊。",
  ui_story_5051_50510501_93_dialog_content = "我記得上次被門衛攔住，也是靠卡蓮的名號……",
  ui_story_5051_50510501_94_dialog_content = "PlayerName是個好人，所以大家都願意幫你呢。",
  ui_story_5051_50510501_95_dialog_content = "是嗎？嘿嘿，真不好意思。",
  ui_story_5051_50510501_96_dialog_content = "喔對，稍等一下！",
  ui_story_5051_50510501_97_dialog_content = "請問，今天是否看過一位「莊嚴的白髮獨眼老人」，或是「金髮紫瞳的貴族青年」……",
  ui_story_5051_50510501_98_dialog_content = "再或者，一位「紅髮的北境占卜師」，進入白夜城呢？",
  ui_story_5051_50510501_99_dialog_content = "前兩位我沒見過。",
  ui_story_5051_50510501_100_dialog_content = "但是，昨天前來晉見的北境使者，的確符合您的描述。",
  ui_story_5051_50510501_101_dialog_content = "（昨天前來晉見的北境使者……那應該是前任北境使者吧。）",
  ui_story_5051_50510501_102_dialog_content = "好吧，謝謝您。",
  ui_story_5051_50510501_103_dialog_content = "PlayerName，發生什麼事了嗎？",
  ui_story_5051_50510501_104_dialog_content = "我本來想問問門衛有沒有看到其他人，但似乎都沒看到。",
  ui_story_5051_50510501_105_dialog_content = "看來我們還是得自己找了。",
  ui_story_5051_50510501_106_dialog_content = "——！！",
  ui_story_5051_50510501_107_dialog_content = "是暗鬼！貨物裡怎麼會有暗鬼？！",
  ui_story_5051_50510501_108_dialog_content = "怎麼這裡也有暗鬼？！",
  ui_story_5051_50510501_109_dialog_content = "別、別怕！我來對付牠們……！",
  ui_story_5051_50510502_1_dialog_content = "發生什麼事了！？",
  ui_story_5051_50510502_2_dialog_content = "報告，<color=#FFB400>邁木</color>騎士長，方才混入貨物之中的暗鬼突然襲擊了隊伍。",
  ui_story_5051_50510502_3_dialog_content = "已立即逮捕運送該貨物的商販，並未出現人員傷亡。",
  ui_story_5051_50510502_4_dialog_content = "堂堂「家族日」慶典，怎麼會出這種紕漏？",
  ui_story_5051_50510502_5_dialog_content = "把犯人移交給我。如此重犯，我會將他親自押送到審判庭。",
  ui_story_5051_50510502_6_dialog_content = "遵命！",
  ui_story_5051_50510502_7_dialog_content = "那麼，暗鬼呢？你們清除乾淨了嗎？",
  ui_story_5051_50510502_8_dialog_content = "全都除掉了，一隻不留！",
  ui_story_5051_50510502_9_dialog_content = "一切都多虧了薇羅妮卡公主殿下！",
  ui_story_5051_50510502_10_dialog_content = "公主殿下好厲害呀！",
  ui_story_5051_50510502_11_dialog_content = "白夜城驍勇善戰的公主殿下……難道是卡蓮公主？",
  ui_story_5051_50510502_12_dialog_content = "不對不對，剛剛那是薇羅妮卡公主。",
  ui_story_5051_50510502_13_dialog_content = "沒想到大公主薇羅妮卡也如此厲害，舒瓦茲家真是人才輩出啊……",
  ui_story_5051_50510502_14_dialog_content = "<size=30>唔，PlayerName，大家都盯著我看，這種感覺好奇怪……</size>",
  ui_story_5051_50510502_15_dialog_content = "那都是因為蜜雅剛剛的表現太出色了！",
  ui_story_5051_50510502_16_dialog_content = "三兩下就除掉了所有暗鬼，簡直就像戰鬥老手一樣。",
  ui_story_5051_50510502_17_dialog_content = "我……很出色嗎？",
  ui_story_5051_50510502_18_dialog_content = "那是當然了！",
  ui_story_5051_50510502_19_dialog_content = "嗯、嗯……謝謝……",
  ui_story_5051_50510502_20_dialog_content = "犯人交給我等處置即可，剛才麻煩您了。",
  ui_story_5051_50510502_21_dialog_content = "收到，麻煩你們了。",
  ui_story_5051_50510502_22_dialog_content = "（這個人……）",
  ui_story_5051_50510502_23_dialog_content = "（不是<color=#FFB400>希羅娜</color>嗎？！）",
  ui_story_5051_50510502_24_dialog_content = "來者何人，為何凝視於我？",
  ui_story_5051_50510502_25_dialog_content = "若有事相求可以直說，哪怕僅是預備騎士，我也會踐行誓言，鼎力相助。",
  ui_story_5051_50510502_26_dialog_content = "若是沒有，勸你還是老老實實回去做該做的事。",
  ui_story_5051_50510502_27_dialog_content = "（糟了，被她發現了！要趕快糊弄過去，不能和她產生過多交集。）",
  ui_story_5051_50510502_28_dialog_content = "（不過，十二年前的希羅娜……才十四歲吧？原來她從小就這麼嚴肅。）",
  ui_story_5051_50510502_29_dialog_content = "沒什麼，抱歉，只是感覺跟妳很有眼緣。",
  ui_story_5051_50510502_30_dialog_content = "眼緣？虛無縹緲，不知所云。",
  ui_story_5051_50510502_31_dialog_content = "這般陳腔濫調，你還是拿去逗路邊的小孩吧。",
  ui_story_5051_50510502_32_dialog_content = "哈哈哈……抱歉，打擾妳了。",
  ui_story_5051_50510502_33_dialog_content = "如果真有所謂的緣分，那麼我們必會再相見。",
  ui_story_5051_50510502_34_dialog_content = "你就好好對天祈禱吧。",
  ui_story_5051_50510502_35_dialog_content = "不用祈禱我也知道，我們一定會再見的！",
  ui_story_5051_50510502_36_dialog_content = "（畢竟我認識的，就是未來的妳啊。）",
  ui_story_5051_50510502_37_dialog_content = "油腔滑調……",
  ui_story_5051_50510502_38_dialog_content = "喂，你看見沒？希羅娜居然在巡邏的時候跟人閒聊！",
  ui_story_5051_50510502_39_dialog_content = "人家畢竟也是十幾歲的女孩子，貪玩也很正常。",
  ui_story_5051_50510502_40_dialog_content = "說得也對。她平常太早熟了，看了都讓人心疼。",
  ui_story_5051_50510502_41_dialog_content = "哎，我也好想偷懶去看花車遊行啊……",
  ui_story_5051_50510502_42_dialog_content = "<size=45>幾位騎士！</size>",
  ui_story_5051_50510502_43_dialog_content = "今日乃全城上下歡慶之時，吾等榮耀的卡爾帝瑪家族肩負重任，守護民眾安全。",
  ui_story_5051_50510502_44_dialog_content = "希望諸位同胞嚴守崗位，不辱使命。",
  ui_story_5051_50510502_45_dialog_content = "……",
  ui_story_5051_50510502_46_dialog_content = "（哈哈哈……這麼多年過去，希羅娜的個性還是一點都沒變啊。）",
  ui_story_5051_50510502_47_dialog_content = "PlayerName，那個，邁木先生說，可以帶咱們去城堡見媽媽。",
  ui_story_5051_50510502_48_dialog_content = "別、別跟那個女孩子聊天了，我們走吧。",
  ui_story_5051_50510502_49_dialog_content = "（啊，受到節日氣氛感染，我也有點飄飄然了……）",
  ui_story_5051_50510502_50_dialog_content = "（都忘了我們其實身處險境，不該鬆懈。）",
  ui_story_5051_50510502_51_dialog_content = "抱歉，是我不夠謹慎。之後我不會隨便跟人搭話了。",
  ui_story_5051_50510502_52_dialog_content = "不是那個意思……唔，這種感覺，該怎麼表達呢。",
  ui_story_5051_50510502_53_dialog_content = "胸口悶悶的，心又有點酸酸的。",
  ui_story_5051_50510502_54_dialog_content = "妳怎麼了？唉，要是我的感應能力還在就好了。",
  ui_story_5051_50510502_55_dialog_content = "這樣我就可以直接感應妳的內心……",
  ui_story_5051_50510502_56_dialog_content = "不、不用了！別窺探我的內心……",
  ui_story_5051_50510502_57_dialog_content = "PlayerName有時候很聰明，但有時候卻太遲鈍了。",
  ui_story_5051_50510502_58_dialog_content = "那真是太好了。對了，我還有事要拜託騎士團的人，妳稍等一下！",
  ui_story_5051_50510502_59_dialog_content = "咦？PlayerName？",
  ui_story_5051_50510502_60_dialog_content = "您好，您就是邁木先生吧？",
  ui_story_5051_50510502_61_dialog_content = "正是。您有什麼事嗎？",
  ui_story_5051_50510502_62_dialog_content = "我有三個朋友在來的路上走散了，我們都是薇羅妮卡公主的客人。",
  ui_story_5051_50510502_63_dialog_content = "可以的話，想麻煩您幫我尋找以下特徵的三個人……",
  ui_story_5051_50510502_64_dialog_content = "那麼，接下來我還要回去見城主殿下，就不奉陪了。",
  ui_story_5051_50510502_65_dialog_content = "謝謝您，邁木先生。",
  ui_story_5051_50510502_66_dialog_content = "那個，您待會會見父親的時候，可以不要提起我和我朋友的事嗎……？",
  ui_story_5051_50510502_67_dialog_content = "只是「不提起」的話，看在您的面子上，沒有問題。",
  ui_story_5051_50510502_68_dialog_content = "今天由我的騎士團負責節日的巡邏守備，還請您和朋友不要做出令我為難的事情。",
  ui_story_5051_50510502_69_dialog_content = "沒問題，一定不會給您添麻煩的。",
  ui_story_5051_50510502_70_dialog_content = "蜜雅，你們說完了嗎？",
  ui_story_5051_50510502_71_dialog_content = "嗯，已經囑咐過邁木先生，不和父親提起我們的事情了。",
  ui_story_5051_50510502_72_dialog_content = "畢竟當年的這一天，我做了一些任性的事情，如果被父親看到我回來，他一定會生氣的……",
  ui_story_5051_50510502_73_dialog_content = "薇羅妮卡？",
  ui_story_5051_50510502_74_dialog_content = "媽媽……？",
  ui_story_5051_50510502_75_dialog_content = "媽媽！",
  ui_story_5051_50510502_76_dialog_content = "哎呀，我的寶貝，妳這是怎麼了？",
  ui_story_5051_50510502_77_dialog_content = "媽媽……真的是媽媽……我好想妳……",
  ui_story_5051_50510502_78_dialog_content = "嗯，乖，媽媽就在這裡。",
  ui_story_5051_50510502_79_dialog_content = "讓媽媽看看，妳在騎士團裡有沒有受傷？",
  ui_story_5051_50510502_80_dialog_content = "還是說，和朋友吵架了？",
  ui_story_5051_50510502_81_dialog_content = "（她在看我……！不不不不是我，蜜雅的媽媽，妳不要誤會啊！）",
  ui_story_5051_50510502_82_dialog_content = "媽媽，是PlayerName帶我來找妳的……",
  ui_story_5051_50510502_83_dialog_content = "原來如此，妳交到一個很好的朋友呢。",
  ui_story_5051_50510502_84_dialog_content = "哎呀，妳的膝蓋怎麼了？關節上的紋路這是……",
  ui_story_5051_50510502_85_dialog_content = "沒事，媽媽，沒事……",
  ui_story_5051_50510502_86_dialog_content = "我已經變得，更勇敢了。",
  ui_story_5051_50510502_87_dialog_content = "所以，沒事……！",
  ui_story_5051_50510502_88_dialog_content = "是嗎？可是妳這張哭哭臉一點說服力都沒有呢。",
  ui_story_5051_50510502_89_dialog_content = "來，媽媽帶妳去洗一洗，我們坐下來慢慢說。",
  ui_story_5051_50510601_1_dialog_content = "（她們母女二人進去了……）",
  ui_story_5051_50510601_2_dialog_content = "（臨走前蜜雅的媽媽還朝我笑了一下，應該是要我在這裡等。）",
  ui_story_5051_50510601_3_dialog_content = "（那句話怎麼說來著？「不能偷窺淑女梳妝的樣子」，所以要我暫時回避一下吧。）",
  ui_story_5051_50510601_4_dialog_content = "（這一路上遇到了伊斯塔萬、希羅娜、蜜雅的母親……）",
  ui_story_5051_50510601_5_dialog_content = "（所有人都像真人一樣，非常自然地和我們交流。）",
  ui_story_5051_50510601_6_dialog_content = "（「永憶鏡晶」真是太神奇了……）",
  ui_story_5051_50510601_7_dialog_content = "（但是，根據設計的初衷，我們不應該和這些人互動。）",
  ui_story_5051_50510601_8_dialog_content = "（如此跟他們接觸，一定會增加「永憶鏡晶」的負擔。）",
  ui_story_5051_50510601_9_dialog_content = "（唉，現在的處境真是難說好壞，真希望能快點找到加晴他們……）",
  ui_story_5051_50510601_10_dialog_content = "喂。",
  ui_story_5051_50510601_11_dialog_content = "這裡是舒瓦茲家的私人領地。",
  ui_story_5051_50510601_12_dialog_content = "你這行跡可疑的傢伙，是怎麼進來的？",
  ui_story_5051_50510601_13_dialog_content = "嗯？誰在和我說話？",
  ui_story_5051_50510601_14_dialog_content = "無禮之徒，卡蓮在下面！",
  ui_story_5051_50510601_15_dialog_content = "<size=45>卡蓮？！</size>",
  ui_story_5051_50510601_16_dialog_content = "居然敢直呼我的名字？",
  ui_story_5051_50510601_17_dialog_content = "雖然卡蓮不喜歡擺貴族架子，但在這裡，輕視卡蓮就是輕視「舒瓦茲」的名號。",
  ui_story_5051_50510601_18_dialog_content = "在「舒瓦茲家族日」這天，偷偷闖入我等領地……",
  ui_story_5051_50510601_19_dialog_content = "還出言不遜，侮辱背負此姓之人，想必你已經知道後果如何了吧？",
  ui_story_5051_50510601_20_dialog_content = "等等，我只是一下沒反應過來！",
  ui_story_5051_50510601_21_dialog_content = "卡蓮殿下，聽我解釋啊！！",
  ui_story_5051_50510601_22_dialog_content = "猜猜我是誰？",
  ui_story_5051_50510601_23_dialog_content = "<size=45>哇？！</size>",
  ui_story_5051_50510601_24_dialog_content = "什、什麼！",
  ui_story_5051_50510601_25_dialog_content = "卑鄙的闖入者！難道你還有同夥！",
  ui_story_5051_50510601_26_dialog_content = "咦？嗯……",
  ui_story_5051_50510601_27_dialog_content = "對喔！我們是同夥，一起來抓小卡蓮的～",
  ui_story_5051_50510601_28_dialog_content = "卑、卑鄙！卡蓮的槍呢！唔，快放開，卡蓮找不到槍了！",
  ui_story_5051_50510601_29_dialog_content = "等等，這個聲音……難道是姐姐？",
  ui_story_5051_50510601_30_dialog_content = "喔吼吼～不對，我才不是薇羅妮卡～",
  ui_story_5051_50510601_31_dialog_content = "請別用這麼拙劣的怪聲戲弄卡蓮！卡、卡蓮已經不是小孩子了！",
  ui_story_5051_50510601_32_dialog_content = "哎呀，真的嗎～小卡蓮～",
  ui_story_5051_50510601_33_dialog_content = "呵呵呵……卡蓮雖然平時像個小大人一樣，但只要被蒙上眼睛，就會開始緊張呢。",
  ui_story_5051_50510601_34_dialog_content = "母親？母親大人您也在這裡嗎？請叫姐姐放開卡蓮！",
  ui_story_5051_50510601_35_dialog_content = "不要～怎麼又叫我「母親大人」呀？叫我媽媽才要幫妳～",
  ui_story_5051_50510601_36_dialog_content = "怎、怎麼可以這樣！",
  ui_story_5051_50510601_37_dialog_content = "誰叫小卡蓮對客人這麼兇呢？",
  ui_story_5051_50510601_38_dialog_content = "第一次見面就兇巴巴的，這樣可不行喲。",
  ui_story_5051_50510601_39_dialog_content = "原來都是你！卑鄙的闖入者！你到底是怎麼蠱惑姐姐和母親的！",
  ui_story_5051_50510601_40_dialog_content = "沒有沒有，我什麼都沒做啊。",
  ui_story_5051_50510601_41_dialog_content = "嘿嘿，小卡蓮還能忍多久呢～",
  ui_story_5051_50510601_42_dialog_content = "嗚……卡蓮不兇了！姐姐、媽媽，放過卡蓮吧——",
  ui_story_5051_50510601_43_dialog_content = "嘿嘿，好久沒跟小卡蓮這樣玩了，笑得我都要喘不過氣了……",
  ui_story_5051_50510601_44_dialog_content = "唔……姐姐好壞……",
  ui_story_5051_50510601_45_dialog_content = "這才對嘛，薇羅妮卡還是笑起來最可愛了。",
  ui_story_5051_50510601_46_dialog_content = "小卡蓮還是不笑呢……要媽媽搔妳癢嗎？",
  ui_story_5051_50510601_47_dialog_content = "不、不用了！",
  ui_story_5051_50510601_48_dialog_content = "果然一家人就是該這樣啊。要是狄安理也在就好了……",
  ui_story_5051_50510601_49_dialog_content = "抱歉，讓你見笑了。",
  ui_story_5051_50510601_50_dialog_content = "聽薇羅妮卡說，你叫做PlayerName，我可以這樣稱呼你嗎？",
  ui_story_5051_50510601_51_dialog_content = "沒問題，您怎麼稱呼我都可以。",
  ui_story_5051_50510601_52_dialog_content = "就像你稱呼薇羅妮卡為「蜜雅」那樣？",
  ui_story_5051_50510601_53_dialog_content = "啊？這……",
  ui_story_5051_50510601_54_dialog_content = "（之前和蜜雅說的話，居然被她母親聽到了！）",
  ui_story_5051_50510601_X54_dialog_content = "媽媽，那個，其實……PlayerName是我在影鎮認識的朋友，他……",
  ui_story_5051_50510601_56_dialog_content = "呵呵，沒關係，我年輕的時候也經常頂著化名跑出去玩。",
  ui_story_5051_50510601_57_dialog_content = "不論是誰，都會有一些善意的小祕密，媽媽理解的。",
  ui_story_5051_50510601_58_dialog_content = "媽媽……謝謝妳。",
  ui_story_5051_50510601_59_dialog_content = "啊～原來如此，看來在「小蜜雅」眼裡，這個朋友就像勇敢的騎士一樣。",
  ui_story_5051_50510601_60_dialog_content = "只要有他在，就可以帶著迷路的小公主回家，我說得對嗎？",
  ui_story_5051_50510601_61_dialog_content = "唔，媽媽……",
  ui_story_5051_50510601_62_dialog_content = "原來你是姐姐的貼身侍衛？又瘦弱又膽小，你真的能保護姐姐嗎？",
  ui_story_5051_50510601_63_dialog_content = "小卡蓮，妳誤會啦，不是侍衛，可能是「白馬王子」喔？",
  ui_story_5051_50510601_64_dialog_content = "哇！媽、媽媽！PlayerName是我在影鎮認識的朋友！",
  ui_story_5051_50510601_65_dialog_content = "他是溫柔又有耐心的人，所以常常幫助我，僅、僅此而已……",
  ui_story_5051_50510601_66_dialog_content = "善意的小祕密？卡蓮聽不懂……",
  ui_story_5051_50510601_67_dialog_content = "卑鄙的闖入者，快把祕密交出來！",
  ui_story_5051_50510601_68_dialog_content = "那個，我叫PlayerName啦……",
  ui_story_5051_50510601_69_dialog_content = "（她居然踩我的腳耶……）",
  ui_story_5051_50510601_70_dialog_content = "（這個小卡蓮，雖然也有認真早熟的個性，但臉上的表情比較豐富，整個人也更活潑。）",
  ui_story_5051_50510601_71_dialog_content = "（母親去世、姐姐消失，和父親的關係也……卡蓮也經歷了許多難過的事情。）",
  ui_story_5051_50510601_72_dialog_content = "（如果沒經歷這些，現在的卡蓮是不是也會多一些笑容呢？）",
  ui_story_5051_50510601_73_dialog_content = "（說不定，現在也會在生氣的時候踩我的腳。）",
  ui_story_5051_50510601_74_dialog_content = "為什麼盯著我看？你還想被踩嗎？",
  ui_story_5051_50510601_75_dialog_content = "沒有沒有，請放過我，卡蓮大人。",
  ui_story_5051_50510601_76_dialog_content = "抱歉，別看卡蓮平時一板一眼的，其實只是不善表達，她沒有惡意。",
  ui_story_5051_50510601_77_dialog_content = "蜜……薇羅妮卡，妳已經完全回憶起家人的事情了嗎？",
  ui_story_5051_50510601_78_dialog_content = "嗯，和媽媽還有妹妹在一起之後，所有記憶突然就像活過來了一樣。",
  ui_story_5051_50510601_79_dialog_content = "我和妹妹最喜歡一起在花園裡盪鞦韆……",
  ui_story_5051_50510601_80_dialog_content = "「猜猜我是誰」的遊戲，我們永遠都玩不膩……",
  ui_story_5051_50510601_81_dialog_content = "那些記憶、那些情感、那些幸福，原來全是真的啊……",
  ui_story_5051_50510601_82_dialog_content = "是嗎？那真是太好了！",
  ui_story_5051_50510601_83_dialog_content = "（但是，蜜雅始終沒怎麼提到她的父親……之前在會客室見面的時候，氣氛也有點尷尬。）",
  ui_story_5051_50510601_84_dialog_content = "（難道她和卡蓮一樣，與父親的關係不太好嗎？）",
  ui_story_5051_50510601_85_dialog_content = "鬧了這麼久，你們渴不渴？餓不餓？大廳裡有點心喔。",
  ui_story_5051_50510601_86_dialog_content = "姐姐，走，我們一起去吃點心吧。",
  ui_story_5051_50510601_87_dialog_content = "哎呀，別拉我呀……",
  ui_story_5051_50510601_88_dialog_content = "PlayerName，別發呆呀，一起來吧。",
  ui_story_5051_50510601_89_dialog_content = "哈哈……你們一家人難得團聚，我就不打擾了。",
  ui_story_5051_50510601_90_dialog_content = "沒關係的，孩子。",
  ui_story_5051_50510601_91_dialog_content = "……你的眼神，我非常熟悉。",
  ui_story_5051_50510601_92_dialog_content = "雖然很堅定，但其中光彩卻像迷路的孩子一樣孤獨。",
  ui_story_5051_50510601_93_dialog_content = "你在影鎮的生活，沒遇上什麼困難吧？",
  ui_story_5051_50510601_94_dialog_content = "沒有！其實我也不是影鎮的人，我是……",
  ui_story_5051_50510601_95_dialog_content = "（不，不能實話實說。空裔是個封閉的種族，外界對我們所知甚少。）",
  ui_story_5051_50510601_96_dialog_content = "（如果讓其他人得知我是空裔，一定會增加「永憶鏡晶」的負擔。）",
  ui_story_5051_50510601_97_dialog_content = "我只是個無名小卒罷了。",
  ui_story_5051_50510601_98_dialog_content = "我沒有家人，所以就喜歡到處旅行，一路結識新朋友。",
  ui_story_5051_50510601_99_dialog_content = "旅行啊……我也喜歡旅行，可惜沒有機會到處跑。",
  ui_story_5051_50510601_100_dialog_content = "孩子，你覺得現在的生活幸福嗎？",
  ui_story_5051_50510601_101_dialog_content = "嗯，我很幸福。",
  ui_story_5051_50510601_102_dialog_content = "那就好。",
  ui_story_5051_50510601_103_dialog_content = "你是薇羅妮卡的朋友，也是個善良的好孩子。",
  ui_story_5051_50510601_104_dialog_content = "在這裡的時候，就把這個家，當做是你的家吧。",
  ui_story_5051_50510601_105_dialog_content = "謝謝您，夫人……",
  ui_story_5051_50510601_106_dialog_content = "我叫做約書亞，你可以隨意稱呼我。",
  ui_story_5051_50510601_107_dialog_content = "哈哈，我還是叫您約書亞夫人就好。",
  ui_story_5051_50510601_108_dialog_content = "姐姐，妳居然偷偷跟著騎士團去影鎮出任務了？！",
  ui_story_5051_50510601_109_dialog_content = "那是什麼任務？騎士團是怎麼戰鬥的？告訴我嘛！",
  ui_story_5051_50510601_110_dialog_content = "這個……",
  ui_story_5051_50510601_111_dialog_content = "是啊，薇羅妮卡，妳能向我解釋一下這件事嗎？",
  ui_story_5051_50510601_112_dialog_content = "<size=45>父、父親！</size>",
  ui_story_5051_50510601_113_dialog_content = "妳若有身為戰士的武勇，主動請纓奔赴戰場，我不反對。",
  ui_story_5051_50510601_114_dialog_content = "但妳卻又臨陣脫逃，堂而皇之地躲進宮中，享受慶典。",
  ui_story_5051_50510601_115_dialog_content = "在堂堂家族紀念日搞出如此鬧劇，妳想如何收場？",
  ui_story_5051_50510601_116_dialog_content = "…………",
  ui_story_5051_50510601_117_dialog_content = "親愛的，是我把薇羅妮卡叫回來的。",
  ui_story_5051_50510601_118_dialog_content = "今天是舒瓦茲家族成員團聚的日子，她應該和我們在一起，不是嗎？",
  ui_story_5051_50510601_119_dialog_content = "……約書亞。舒瓦茲家，是個「家族」，而不是「家庭」。",
  ui_story_5051_50510601_120_dialog_content = "舒瓦茲家族沒有嬌慣孩子的先例，以後也不應該有。",
  ui_story_5051_50510601_121_dialog_content = "是呀，我們既是一個「家族」，更是一個「家庭」。",
  ui_story_5051_50510601_122_dialog_content = "如果抓不住最親近之人的心，又怎麼抓住一個家族呢。",
  ui_story_5051_50510601_123_dialog_content = "（這是舒瓦茲…？）",
  ui_story_5051_50510601_124_dialog_content = "（雖然威風不減，但和現在完全不一樣，這些年他居然衰老了這麼多。）",
  ui_story_5051_50510601_125_dialog_content = "（氣氛好尷尬，蜜雅的臉色糟透了……怎麼偏偏這時候我不能用感應能力啊！）",
  ui_story_5051_50510601_126_dialog_content = "抱歉，借過一下。",
  ui_story_5051_50510601_127_dialog_content = "（是白蘭女士！她穿著和之前一樣的禮服，原來十二年前她也在為城主大人服務啊。）",
  ui_story_5051_50510601_128_dialog_content = "你又是誰？",
  ui_story_5051_50510601_129_dialog_content = "我？我是薇羅妮卡的朋友……",
  ui_story_5051_50510601_130_dialog_content = "「朋友」？",
  ui_story_5051_50510601_131_dialog_content = "狄安理。",
  ui_story_5051_50510601_132_dialog_content = "哎，就以賓客身分接待這個人吧，紅女士。",
  ui_story_5051_50510601_133_dialog_content = "好的。",
  ui_story_5051_50510601_134_dialog_content = "城主殿下，元老院的成員還在等您。",
  ui_story_5051_50510601_135_dialog_content = "約書亞，既然妳把薇羅妮卡帶回來了，就好好顧好她。",
  ui_story_5051_50510601_136_dialog_content = "別再讓她和她朋友惹出其他麻煩。",
  ui_story_5051_50510601_137_dialog_content = "沒問題，我會照顧好這些孩子的。",
  ui_story_5051_50510601_138_dialog_content = "所以，你也別這麼兇，好嗎？",
  ui_story_5051_50510601_139_dialog_content = "……好吧。",
  ui_story_5051_50510601_140_dialog_content = "巡遊馬上就要開始了，快帶孩子們去做好準備吧。",
  ui_story_5051_50510601_141_dialog_content = "哎……",
  ui_story_5051_50510601_142_dialog_content = "薇羅妮卡，妳還好嗎？",
  ui_story_5051_50510601_143_dialog_content = "爸爸今天只是太忙了，他沒生妳的氣。",
  ui_story_5051_50510601_144_dialog_content = "我……我……",
  ui_story_5051_50510601_145_dialog_content = "乖孩子，不怕。",
  ui_story_5051_50510601_146_dialog_content = "姐姐……",
  ui_story_5051_50510601_147_dialog_content = "夫人，離巡遊開始還有段時間，您可以和家人再敘敘舊，其他準備工作交給我就好。",
  ui_story_5051_50510601_148_dialog_content = "謝謝妳，紅女士。",
  ui_story_5051_50510601_149_dialog_content = "應該的。",
  ui_story_5051_50510601_150_dialog_content = "至於您，麻煩過來和我一起熟悉一下巡遊的流程，為接下來的活動做準備。",
  ui_story_5051_50510601_151_dialog_content = "請放心，夫人很擅長安撫人，薇羅妮卡殿下會沒事的。",
  ui_story_5051_50510601_152_dialog_content = "好吧……麻煩妳了，白蘭女士。",
  ui_story_5051_50510601_153_dialog_content = "白蘭女士？哎呀，這裡居然會有人這麼稱呼我。",
  ui_story_5051_50510601_154_dialog_content = "不知道您是怎麼得知這個名字的。",
  ui_story_5051_50510601_155_dialog_content = "（白蘭女士十二年前不叫這個名字嗎？）",
  ui_story_5051_50510601_156_dialog_content = "（想來，今天在現實中，城主大人也稱她為「紅女士」。）",
  ui_story_5051_50510601_157_dialog_content = "（看來這是她為城主服務時所用的名字。我該怎麼糊弄過去呢……）",
  ui_story_5051_50510601_158_dialog_content = "不必為難，就像我的祕密一樣，您自然有您的祕密，這很正常。",
  ui_story_5051_50510601_159_dialog_content = "您是城主殿下親自委託給我的貴客，讓您渡過美好的一天是我的職責。",
  ui_story_5051_50510601_160_dialog_content = "只是，希望您能暫時稱呼我為「紅女士」，讓我能順利工作。",
  ui_story_5051_50510601_161_dialog_content = "好的，「紅女士」。我不會給妳添麻煩的。",
  ui_story_5051_50510601_162_dialog_content = "感謝您的配合。那麼，這邊請。",
  ui_story_5051_50510701_1_dialog_content = "因瓦尼勒嗚姆～因瓦尼勒嗚姆～因瓦尼勒嗚姆～",
  ui_story_5051_50510701_2_dialog_content = "請告訴我，我心中所想的人，現在在哪裡？",
  ui_story_5051_50510701_3_dialog_content = "<size=45>阿布拉「哈」達布拉！</size>",
  ui_story_5051_50510701_4_dialog_content = "喔喔……前面這邊！",
  ui_story_5051_50510701_5_dialog_content = "聽說另一支騎士團被調去影鎮了。",
  ui_story_5051_50510701_6_dialog_content = "啊？去影鎮幹什麼？",
  ui_story_5051_50510701_7_dialog_content = "去抵擋暗鬼入侵吧？畢竟影鎮也是白夜城的防線。",
  ui_story_5051_50510701_8_dialog_content = "那我們為什麼不去啊？",
  ui_story_5051_50510701_9_dialog_content = "你傻了嗎？我們是<color=#FFB400>卡爾帝瑪</color>家的騎士團，去那種爛地方幹什麼！",
  ui_story_5051_50510701_10_dialog_content = "噓，小聲點，省得又被希羅娜抓到我們偷懶。",
  ui_story_5051_50510701_11_dialog_content = "還是卡爾帝瑪家好，論話語權甚至能和城主平起平坐。",
  ui_story_5051_50510701_12_dialog_content = "原來是這樣啊……",
  ui_story_5051_50510701_13_dialog_content = "原來是這樣啊……",
  ui_story_5051_50510701_14_dialog_content = "喂！妳是誰啊！",
  ui_story_5051_50510701_15_dialog_content = "有可疑人物，快抓住她！",
  ui_story_5051_50510701_16_dialog_content = "抱歉抱歉，我走錯路了，拜拜～",
  ui_story_5051_50510701_17_dialog_content = "阿布拉「哈」達布拉！",
  ui_story_5051_50510701_18_dialog_content = "這次又是哪裡啊？",
  ui_story_5051_50510701_19_dialog_content = "伊倫汀這學期成績又是第一名……",
  ui_story_5051_50510701_20_dialog_content = "伊倫汀學姐長得漂亮，功課又好，黎明學院的老師各個都很尊重她。",
  ui_story_5051_50510701_21_dialog_content = "真令人憧憬啊。",
  ui_story_5051_50510701_22_dialog_content = "哎，說不定之後還會跳級直接畢業。",
  ui_story_5051_50510701_23_dialog_content = "這個人，真是完美過頭了。",
  ui_story_5051_50510701_24_dialog_content = "伊倫汀？誰呀？",
  ui_story_5051_50510701_25_dialog_content = "那個奇裝異服的女孩子是誰呀？紅色的頭髮真漂亮。",
  ui_story_5051_50510701_26_dialog_content = "那是什麼打扮……寡廉鮮恥！我要向審判庭檢舉她！",
  ui_story_5051_50510701_27_dialog_content = "好像又走錯路了，抱歉！！",
  ui_story_5051_50510701_28_dialog_content = "阿布拉……「哈」達布拉……",
  ui_story_5051_50510701_29_dialog_content = "這次是……餐廳？",
  ui_story_5051_50510701_30_dialog_content = "可是這裡也沒有大家的影子啊。",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>咕咕——</color>",
  ui_story_5051_50510701_32_dialog_content = "占卜小球球，你是知道我餓了，所以才帶我來這裡的嗎？",
  ui_story_5051_50510701_33_dialog_content = "啊——但是現在找人更要緊啊！而且在「永憶鏡晶」裡吃飯也沒用吧！",
  ui_story_5051_50510701_34_dialog_content = "再來一次！",
  ui_story_5051_50510701_35_dialog_content = "因瓦尼勒嗚姆～因瓦尼勒嗚姆～因瓦尼勒嗚姆～",
  ui_story_5051_50510701_36_dialog_content = "請告訴我，我心中所想的人，現在在哪裡？",
  ui_story_5051_50510701_37_dialog_content = "阿布拉「哈」達布拉！",
  ui_story_5051_50510701_38_dialog_content = "<size=45>哈哈哈哈哈哈哈！！</size>",
  ui_story_5051_50510701_39_dialog_content = "誰、誰啊！幹嘛突然大笑！嚇死我了……",
  ui_story_5051_50510701_40_dialog_content = "小丫頭，妳的占卜技術，嗝，好爛喔。",
  ui_story_5051_50510701_41_dialog_content = "妳竟然敢說我的占卜技術爛？！",
  ui_story_5051_50510701_42_dialog_content = "我的占卜技術可是從媽媽那裡學來的！我媽媽是最厲害的占卜師！",
  ui_story_5051_50510701_43_dialog_content = "北境占卜師「<color=#FFB400>博阿姿</color>」！可別告訴我妳沒聽過她！",
  ui_story_5051_50510701_44_dialog_content = "「波阿滋」？好耳熟啊……嗝。",
  ui_story_5051_50510701_45_dialog_content = "那又怎麼樣！錯了就是錯了，小丫頭妳還是乖乖認錯吧～",
  ui_story_5051_50510701_46_dialog_content = "嗯——妳這個沒禮貌的傢伙！我今天一定要妳好看！",
  ui_story_5051_50510701_47_dialog_content = "嗝，小丫頭沒什麼本事，口氣倒是不小。",
  ui_story_5051_50510701_48_dialog_content = "要不要出去和我比比看，誰的占卜比較準？",
  ui_story_5051_50510701_49_dialog_content = "比就比！",
  ui_story_5051_50510701_50_dialog_content = "兩位女士，請記得結帳餐費。",
  ui_story_5051_50510701_51_dialog_content = "啊？喔……哎呀，我沒帶錢，嗝。",
  ui_story_5051_50510701_52_dialog_content = "那麼您呢？",
  ui_story_5051_50510701_53_dialog_content = "我？我跟她又不熟，幹嘛要我付啊……",
  ui_story_5051_50510701_54_dialog_content = "如果兩位無法付清餐費，那麼就請在此等待衛兵吧。",
  ui_story_5051_50510701_55_dialog_content = "哎？！不、不行！我還有重要的事要忙欸！",
  ui_story_5051_50510701_56_dialog_content = "妳這個罪魁禍首倒是說句話呀！",
  ui_story_5051_50510701_57_dialog_content = "呼嚕……",
  ui_story_5051_50510701_58_dialog_content = "居然睡著了……",
  ui_story_5051_50510701_59_dialog_content = "要付款還是叫衛兵來，選一個吧，小姐。",
  ui_story_5051_50510701_60_dialog_content = "好吧……一共多少啊？",
  ui_story_5051_50510701_61_dialog_content = "十二萬七千九百三十八白夜幣。",
  ui_story_5051_50510701_62_dialog_content = "<size=45>你說多少？！</size>",
  ui_story_5051_50510701_63_dialog_content = "這位女士點了不少本店的名貴藏品，這個價格已經是節日優惠了。",
  ui_story_5051_50510701_64_dialog_content = "可惡啊……我的旅費……我的小金庫……",
  ui_story_5051_50510701_65_dialog_content = "（不過「永憶鏡晶」裡發生的事並不是真的，出去以後我的錢應該會回來吧。）",
  ui_story_5051_50510701_66_dialog_content = "給你……",
  ui_story_5051_50510701_67_dialog_content = "謝謝惠顧。",
  ui_story_5051_50510701_68_dialog_content = "喂，我幫妳付錢了，這下妳沒藉口逃跑了。",
  ui_story_5051_50510701_69_dialog_content = "今天我要為媽媽的名譽而戰！",
  ui_story_5051_50510701_70_dialog_content = "……咦，人呢？",
  ui_story_5051_50510701_71_dialog_content = "嗯～就這邊吧……嗝。",
  ui_story_5051_50510701_72_dialog_content = "喂，妳給我等等！等一下！",
  ui_story_5051_50510701_73_dialog_content = "別想趁著人多跑路！",
  ui_story_5051_50510701_74_dialog_content = "好，就在這裡……",
  ui_story_5051_50510701_75_dialog_content = "抓到妳了！",
  ui_story_5051_50510701_76_dialog_content = "我都墊了妳的飯錢，竟然還想趁機逃跑…",
  ui_story_5051_50510701_77_dialog_content = "看妳現在還能怎麼逃！",
  ui_story_5051_50510701_78_dialog_content = "嗯，跑什麼跑？喏，妳要找的人就在那邊。",
  ui_story_5051_50510701_79_dialog_content = "我要找的人……？",
  ui_story_5051_50510701_80_dialog_content = "快看，遊行隊伍過來了！",
  ui_story_5051_50510701_81_dialog_content = "城主大人，多麼的英勇偉岸！",
  ui_story_5051_50510701_82_dialog_content = "卡蓮公主和薇羅妮卡公主也在！",
  ui_story_5051_50510701_83_dialog_content = "約書亞夫人——",
  ui_story_5051_50510701_84_dialog_content = "舒瓦茲家族萬歲！",
  ui_story_5051_50510701_85_dialog_content = "薇羅妮卡，抬頭看看吧，大家正在妳和打招呼呢。",
  ui_story_5051_50510701_86_dialog_content = "嗯……嗯。",
  ui_story_5051_50510701_87_dialog_content = "別緊張，來，握住我的手。",
  ui_story_5051_50510701_88_dialog_content = "（蜜雅看起來還是有點緊張。）",
  ui_story_5051_50510701_89_dialog_content = "（遊行還要持續一段時間，她還撐得下去嗎……）",
  ui_story_5051_50510701_90_dialog_content = "（沒想到當年的「舒瓦茲家族日」會是這麼盛大的慶典。）",
  ui_story_5051_50510701_91_dialog_content = "（雖然現實那場宴會就夠奢華了，但和十二年前的慶典簡直無法相提並論。）",
  ui_story_5051_50510701_92_dialog_content = "（十二年後為什麼會變成這樣呢？）",
  ui_story_5051_50510701_93_dialog_content = "（還有，今天在城門遇見的那些暗鬼，顯然不是偶然混進貨物裡的。）",
  ui_story_5051_50510701_94_dialog_content = "（十二年前，有人想趁著節日將暗鬼偷偷運進白夜城。）",
  ui_story_5051_50510701_95_dialog_content = "（騎士團能處理好這件事嗎？還是說，最終會演變成更大的騷動呢……）",
  ui_story_5051_50510701_96_dialog_content = "（唉，希望這些事不會讓大家陷入險境。）",
  ui_story_5051_50510701_97_dialog_content = "（……嗯？怎麼覺得有人在盯著我看。）",
  ui_story_5051_50510701_98_dialog_content = "（不可能吧，看我幹什麼？我只是個小小的隨隊侍從罷了。）",
  ui_story_5051_50510701_99_dialog_content = "（而且紅女士提醒過我，遊行的時候千萬不能東張西望，破壞整齊的隊伍。）",
  ui_story_5051_50510701_100_dialog_content = "（別亂想了！）",
  ui_story_5051_50510701_101_dialog_content = "喂——PlayerName！！蜜雅！！",
  ui_story_5051_50510701_102_dialog_content = "哎呀，人群太吵了！他們完全聽不到啊！",
  ui_story_5051_50510701_103_dialog_content = "嗯～嘿咻！妳別白費力氣啦。",
  ui_story_5051_50510701_104_dialog_content = "就算聽到妳說話，他們也沒辦法脫隊來找妳啊。",
  ui_story_5051_50510701_105_dialog_content = "說得也是……",
  ui_story_5051_50510701_106_dialog_content = "話說，妳怎麼知道我要找人？",
  ui_story_5051_50510701_107_dialog_content = "妳又怎麼知道我要找的人就在這裡啊！",
  ui_story_5051_50510701_108_dialog_content = "不是說要比占卜嗎？",
  ui_story_5051_50510701_109_dialog_content = "我贏囉～",
  ui_story_5051_50510701_110_dialog_content = "……",
  ui_story_5051_50510701_111_dialog_content = "<size=45>太厲害了！</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>請收我為徒！！</size>",
  ui_story_5051_50510701_113_dialog_content = "哎……小聲點，小聲點，妳吵得我頭好痛……",
  ui_story_5051_50510701_114_dialog_content = "我不收徒弟，來這裡只是幫人幹點事，賺賺酒錢。",
  ui_story_5051_50510701_115_dialog_content = "今晚……明天，或是後天？喝夠了我就走了。",
  ui_story_5051_50510701_116_dialog_content = "那請至少告訴我妳的名字！",
  ui_story_5051_50510701_117_dialog_content = "（這樣等我離開「永憶鏡晶」就可以去找妳啦～）",
  ui_story_5051_50510701_118_dialog_content = "好吧好吧，看在飯錢的份上……",
  ui_story_5051_50510701_119_dialog_content = "我叫「博阿姿」。",
  ui_story_5051_50510701_120_dialog_content = "哎……？",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>媽媽</color>？",
  ui_story_5051_50510701_122_dialog_content = "感謝所有白夜城子民今日在此相聚，歡慶這個特殊的節日。",
  ui_story_5051_50510701_123_dialog_content = "舒瓦茲家族，既是白夜城的頂上之冠，也是其立命根基。",
  ui_story_5051_50510701_124_dialog_content = "我們舉臂托起眾人，而我們的利劍也由眾人鑄造。",
  ui_story_5051_50510701_125_dialog_content = "今日，我們在此稱頌「舒瓦茲」的美德，也稱頌白夜城百姓萬眾的美德！",
  ui_story_5051_50510701_126_dialog_content = "我宣佈，「舒瓦茲家族日」慶典，正式開始！",
  ui_story_5051_50510701_127_dialog_content = "接下來舉行「決鬥之儀式」！",
  ui_story_5051_50510701_128_dialog_content = "真是精彩的開幕致詞，辛苦殿下了。",
  ui_story_5051_50510701_129_dialog_content = "……",
  ui_story_5051_50510701_130_dialog_content = "您看，這盛世，正是我們白夜城實力的體現。",
  ui_story_5051_50510701_131_dialog_content = "也就只有舒瓦茲家族配得上如此榮耀了。",
  ui_story_5051_50510701_132_dialog_content = "聽說，今天薇羅妮卡公主還在城門擊退了企圖混入城內的暗鬼。",
  ui_story_5051_50510701_133_dialog_content = "說是見習騎士，但她的英姿完全不遜於正式的騎士團成員啊。",
  ui_story_5051_50510701_134_dialog_content = "聽說節日衛隊趕到的時候，暗鬼已經被砍得灰都不剩了。",
  ui_story_5051_50510701_135_dialog_content = "我記得，負責節日衛隊的是卡爾帝瑪家族吧？果然還是……",
  ui_story_5051_50510701_136_dialog_content = "……小事罷了，不足掛齒。",
  ui_story_5051_50510701_137_dialog_content = "想來，薇羅妮卡也懂得這個道理，才一直沒有向我主動邀功。",
  ui_story_5051_50510701_138_dialog_content = "……",
  ui_story_5051_50510701_139_dialog_content = "別這麼說。",
  ui_story_5051_50510701_140_dialog_content = "這件事已經在城裡傳開了。",
  ui_story_5051_50510701_141_dialog_content = "「薇羅妮卡公主深藏不露，三兩下就解決了危機。」",
  ui_story_5051_50510701_142_dialog_content = "大家想必一定想親眼看看公主戰鬥的英姿吧？",
  ui_story_5051_50510701_143_dialog_content = "路見不平，拔刀相助，是值得讚頌的美德。",
  ui_story_5051_50510701_144_dialog_content = "但小小年紀，不該養成虛榮賣弄的習慣。",
  ui_story_5051_50510701_145_dialog_content = "沉迷表面功夫，成不了大器。",
  ui_story_5051_50510701_146_dialog_content = "您千萬別這麼說啊！",
  ui_story_5051_50510701_147_dialog_content = "薇羅妮卡公主為人低調靦腆，少有美名流傳。",
  ui_story_5051_50510701_148_dialog_content = "相比之下，卡蓮公主便是自幼便獲稱「帝王之術」的奇才。",
  ui_story_5051_50510701_149_dialog_content = "再過幾年，卡蓮公主越發出類拔萃，那薇羅妮卡公主身為長女的威嚴……",
  ui_story_5051_50510701_150_dialog_content = "特洛伊公爵！後繼之事，豈容我等隨意指點！",
  ui_story_5051_50510701_151_dialog_content = "城主殿下向來獨具慧眼，禮賢惜才。",
  ui_story_5051_50510701_152_dialog_content = "這次特地從前線召回公主，想必也是自有考量。",
  ui_story_5051_50510701_153_dialog_content = "哈哈，您說得沒錯！人盡其才！想必薇羅妮卡公主在城裡更能發揮實力。",
  ui_story_5051_50510701_154_dialog_content = "殿下，還請寬恕我的無禮。",
  ui_story_5051_50510701_155_dialog_content = "父親，我……",
  ui_story_5051_50510701_156_dialog_content = "薇羅妮卡，去做準備吧。",
  ui_story_5051_50510701_157_dialog_content = "咦？準備？",
  ui_story_5051_50510701_158_dialog_content = "「按照預定」，馬上該輪到妳上場了。",
  ui_story_5051_50510701_159_dialog_content = "別讓圍觀的民眾久等。",
  ui_story_5051_50510701_160_dialog_content = "是，好的……！",
  ui_story_5051_50510701_161_dialog_content = "兩位伴我左右多年，看來已經摸透了我的心思。",
  ui_story_5051_50510701_162_dialog_content = "本想讓薇羅妮卡壓軸，在開幕式上彰顯舒瓦茲家族新生代的力量。",
  ui_story_5051_50510701_163_dialog_content = "沒想到，已經被兩位看透了。",
  ui_story_5051_50510701_164_dialog_content = "呵呵……老朽隨口說說罷了。",
  ui_story_5051_50510701_165_dialog_content = "薇羅妮卡公主首次登台亮相，真是令人期待啊！",
  ui_story_5051_50510701_166_dialog_content = "蜜雅，妳真的要去嗎？",
  ui_story_5051_50510701_167_dialog_content = "……",
  ui_story_5051_50510701_168_dialog_content = "我覺得現在是逃跑的好機會。",
  ui_story_5051_50510701_169_dialog_content = "本來我們只想見見約書亞夫人，卻因為城主大人的出現，被迫來到了這裡。",
  ui_story_5051_50510701_X169_dialog_content = "雖然錯過向夫人求助，幫忙尋找同伴的時機，但我們不該繼續干涉這裡的一切了。",
  ui_story_5051_50510701_170_dialog_content = "你、你說得對……我們該走了……",
  ui_story_5051_50510701_171_dialog_content = "看台上的那個人只是幻影，不是真正的父親……拒絕他也沒關係……他不會生氣的……",
  ui_story_5051_50510701_X171_dialog_content = "薇羅妮卡，我說過多少次，妳不用練習戰鬥。妳沒有天賦。",
  ui_story_5051_50510701_X172_dialog_content = "薇羅妮卡，為什麼妳不敢和其他人打招呼？妳已經十歲了，不是小孩子了。",
  ui_story_5051_50510701_X173_dialog_content = "加入騎士團？薇羅妮卡，我不求妳有多出眾，至少別讓妳母親擔心！",
  ui_story_5051_50510701_172_dialog_content = "蜜雅……？",
  ui_story_5051_50510701_173_dialog_content = "（蜜雅怎麼會突然開始發抖？難道她害怕違抗父親的命令嗎？）",
  ui_story_5051_50510701_174_dialog_content = "（如果真的是這樣，現在強行帶她離開，只會增加她的壓力。）",
  ui_story_5051_50510701_175_dialog_content = "（她的病情才剛好轉一點啊！）",
  ui_story_5051_50510701_176_dialog_content = "……嗯。",
  ui_story_5051_50510701_177_dialog_content = "蜜雅，妳想參加決鬥嗎？",
  ui_story_5051_50510701_178_dialog_content = "我、我？我都可以……PlayerName，你覺得我該參加嗎？",
  ui_story_5051_50510701_179_dialog_content = "如果參加決鬥能讓妳不再發抖，那就去吧。",
  ui_story_5051_50510701_180_dialog_content = "咦？我……啊，我的病又……",
  ui_story_5051_50510701_181_dialog_content = "蜜雅的手好冰啊。",
  ui_story_5051_50510701_182_dialog_content = "嗯，自從身體變成這樣之後，一直就很冰。",
  ui_story_5051_50510701_183_dialog_content = "PlayerName的手，好溫暖。",
  ui_story_5051_50510701_184_dialog_content = "安心的感覺隨著溫度傳了過來……",
  ui_story_5051_50510701_185_dialog_content = "謝謝你，我現在不怕了。",
  ui_story_5051_50510701_X180_dialog_content = "對不起，給你添麻煩了。",
  ui_story_5051_50510701_X181_dialog_content = "不，蜜雅。答應帶妳來宴會尋親的人是我，所以我有義務照顧妳。",
  ui_story_5051_50510701_X182_dialog_content = "如果參加這場決鬥能解開妳的心結，那就去吧！",
  ui_story_5051_50510701_X183_dialog_content = "一切責任由我承擔！",
  ui_story_5051_50510701_X184_dialog_content = "（大不了我們決鬥完再落跑……！）",
  ui_story_5051_50510701_X185_dialog_content = "PlayerName……我知道你是個溫柔的好人，但為什麼要為了我……",
  ui_story_5051_50510701_X186_dialog_content = "因為我們是朋友啊。",
  ui_story_5051_50510701_X187_dialog_content = "哎……？朋友？",
  ui_story_5051_50510701_X188_dialog_content = "朋友之間相互扶持，希望對方健康、快樂，這不是天經地義的事情嗎？",
  ui_story_5051_50510701_X189_dialog_content = "………………",
  ui_story_5051_50510701_X190_dialog_content = "我、我這些話很奇怪嗎？",
  ui_story_5051_50510701_X191_dialog_content = "嘿嘿……稍微有一點。",
  ui_story_5051_50510701_X192_dialog_content = "哪裡奇怪啊……",
  ui_story_5051_50510701_X193_dialog_content = "因為除了芭芭雅嘎，從來沒有人把我當成朋友。",
  ui_story_5051_50510701_X194_dialog_content = "大家都稱呼我「公主殿下」，或是「可憐的蜜雅」……",
  ui_story_5051_50510701_X195_dialog_content = "PlayerName，我真的可以參加決鬥嗎？",
  ui_story_5051_50510701_X196_dialog_content = "嗯，妳沒問題的。",
  ui_story_5051_50510701_X197_dialog_content = "謝謝你……我一定不會辜負你的信任。",
  ui_story_5051_50510701_X198_dialog_content = "……對了，登台決鬥也能吸引周圍所有人的目光。",
  ui_story_5051_50510701_X199_dialog_content = "在這期間PlayerName可以在看台上觀察人群，尋找父親他們。",
  ui_story_5051_50510701_X200_dialog_content = "這樣即使得不到媽媽的幫助，我們也能靠自己找。",
  ui_story_5051_50510701_X201_dialog_content = "這麼說來，參加決鬥好像也是不錯的決定……",
  ui_story_5051_50510701_X202_dialog_content = "說得好，蜜雅！看來妳已經完全學會我那套阿Ｑ歪理了，啊哈哈。",
  ui_story_5051_50510701_X203_dialog_content = "薇羅妮卡殿下，決鬥馬上就要開始了，請到這邊來。",
  ui_story_5051_50510701_X204_dialog_content = "好的，我這就來。",
  ui_story_5051_50510701_X205_dialog_content = "那麼，我走啦……！",
  ui_story_5051_50510701_X206_dialog_content = "嗯，加油啊蜜雅！",
  ui_story_5051_50510701_186_dialog_content = "加油，蜜雅，就算萬一真的打不過……",
  ui_story_5051_50510701_187_dialog_content = "萬一您真的陷入弱勢，我會放水。",
  ui_story_5051_50510701_188_dialog_content = "哎？您是……",
  ui_story_5051_50510701_189_dialog_content = "薇羅妮卡公主殿下，您好，我是接下來將與您決鬥的衛兵。",
  ui_story_5051_50510701_190_dialog_content = "城主大人已託人吩咐我，我將在確保您安全的前提下與您切磋。",
  ui_story_5051_50510701_191_dialog_content = "武器也請您換成這邊的佩劍，這把訓練用的佩劍，可以確保您不會傷到自己。",
  ui_story_5051_50510701_192_dialog_content = "此為「舒瓦茲家族日」的開幕式，當然也不會讓您蒙羞落敗。",
  ui_story_5051_50510701_193_dialog_content = "之後您只要與我配合，做做樣子將我擊倒即可。",
  ui_story_5051_50510701_194_dialog_content = "做做……樣子……？",
  ui_story_5051_50510701_195_dialog_content = "也就是說，這不是真的比試……？",
  ui_story_5051_50510701_196_dialog_content = "只是，像宴會應酬一樣的逢場作戲而已……？",
  ui_story_5051_50510701_197_dialog_content = "薇羅妮卡，我說過多少次，妳不用練習戰鬥，妳沒有天賦。",
  ui_story_5051_50510701_198_dialog_content = "薇羅妮卡，為什麼妳不敢和其他人打招呼？妳已經十歲了，不是小孩子了。",
  ui_story_5051_50510701_199_dialog_content = "加入騎士團？薇羅妮卡，我不求妳有多出眾，至少別讓妳母親擔心！",
  ui_story_5051_50510701_200_dialog_content = "蜜雅！醒醒！",
  ui_story_5051_50510701_201_dialog_content = "PlayerName……",
  ui_story_5051_50510701_202_dialog_content = "蜜雅，妳不需要等父親伸出橄欖枝才去證明自己。",
  ui_story_5051_50510701_203_dialog_content = "城主的權力是很大，但並不代表他能安排妳的一切。",
  ui_story_5051_50510701_204_dialog_content = "我不知道妳又想起了什麼……",
  ui_story_5051_50510701_205_dialog_content = "但是我知道，妳已經不是十二年前的那個自己了。",
  ui_story_5051_50510701_206_dialog_content = "我……",
  ui_story_5051_50510701_207_dialog_content = "妳一定不喜歡這種作秀般的「勝利」。",
  ui_story_5051_50510701_208_dialog_content = "那就用實力告訴大家，妳可以憑自己的力量獲得真正的「勝利」。",
  ui_story_5051_50510701_209_dialog_content = "但我的對手，他……",
  ui_story_5051_50510701_210_dialog_content = "如果比試對象不願意出全力，那妳就逼他出全力！",
  ui_story_5051_50510701_211_dialog_content = "逼他？唔，逼他使出全力……我做得到嗎？",
  ui_story_5051_50510701_212_dialog_content = "當然了！剛才那些人不是還說，蜜雅搶在騎士團之前消滅暗鬼這件事，已經傳遍全城了。",
  ui_story_5051_50510701_213_dialog_content = "一般的衛兵怎麼會是蜜雅的對手！",
  ui_story_5051_50510701_214_dialog_content = "咳咳，那個，兩位，我還在這裡呢……",
  ui_story_5051_50510701_215_dialog_content = "啊，抱歉，哈哈哈……",
  ui_story_5051_50510701_216_dialog_content = "既然您已經聽到了，那我們就直說了。",
  ui_story_5051_50510701_217_dialog_content = "蜜雅，準備好了嗎？",
  ui_story_5051_50510701_218_dialog_content = "我……PlayerName這麼信任我……第一次有人這麼信任我的力量！",
  ui_story_5051_50510701_219_dialog_content = "我準備好了！",
  ui_story_5051_50510701_220_dialog_content = "那就——",
  ui_story_5051_50510701_221_dialog_content = "「白夜至上，英勇的戰士，請與我決鬥吧！」",
  ui_story_5051_50510701_222_dialog_content = "「拿起劍，或是丟下妳的尊嚴。」",
  ui_story_5051_50510701_223_dialog_content = "「若接受挑戰，雙方便承諾，即使命喪於此，也絕無怨言！」",
  ui_story_5051_50510701_224_dialog_content = "喪命什麼的，是不是太過火了一點……",
  ui_story_5051_50510701_225_dialog_content = "是啊，您饒了我吧，這種事我可承受不起啊……",
  ui_story_5051_50510701_226_dialog_content = "小、小說裡都是這樣寫的，我只是隨口說說……",
  ui_story_5051_50510701_227_dialog_content = "哎……好吧，我保證，不輕易裝死或投降。",
  ui_story_5051_50510701_228_dialog_content = "但如果您實在打不過我，我還是會遵守城主大人的旨意乖乖投降。畢竟我也只是來打工的。",
  ui_story_5051_50510701_229_dialog_content = "太好了，謝謝您！",
  ui_story_5051_50510701_230_dialog_content = "那，這把佩劍……",
  ui_story_5051_50510701_231_dialog_content = "這把佩劍，蜜雅妳還是拿著吧。",
  ui_story_5051_50510701_232_dialog_content = "對，千萬別傷到自己。",
  ui_story_5051_50510701_233_dialog_content = "我是怕蜜雅傷到你！",
  ui_story_5051_50510701_234_dialog_content = "啊、啊？",
  ui_story_5051_50510701_235_dialog_content = "說得也是。",
  ui_story_5051_50510701_236_dialog_content = "你老是叫蜜雅蜜雅的……",
  ui_story_5051_50510701_237_dialog_content = "我眼前這個喜歡亂來的小姑娘，真的是那個柔弱的薇羅妮卡公主嗎？",
  ui_story_5051_50510701_238_dialog_content = "當、當然是了！蜜雅只是……",
  ui_story_5051_50510701_239_dialog_content = "蜜雅只是，我們之間專屬的暱稱罷了！",
  ui_story_5051_50510701_240_dialog_content = "喔、喔……",
  ui_story_5051_50510701_241_dialog_content = "時候不早了，那就待會擂台上見，公主殿下。",
  ui_story_5051_50510701_242_dialog_content = "好的！你一定要不留遺憾地跟我戰到最後一刻……！",
  ui_story_5051_50510701_243_dialog_content = "遵、遵命……",
  ui_story_5051_50510701_244_dialog_content = "（我不是只是來打工的嗎？怎麼感覺像是被按著頭看了一齣青春戀愛劇……）",
  ui_story_5051_50510802_1_dialog_content = "（浪潮般的歡呼聲，連從這裡都聽得到。）",
  ui_story_5051_50510802_2_dialog_content = "（看來是節日慶典開始了。）",
  ui_story_5051_50510802_3_dialog_content = "（是時候去盜走「永憶鏡晶」了……）",
  ui_story_5051_50510802_4_dialog_content = "喂，前面的人，站住。",
  ui_story_5051_50510802_5_dialog_content = "（嘖，怎麼還有守衛在這裡！）",
  ui_story_5051_50510802_6_dialog_content = "麻煩報出你的身分。",
  ui_story_5051_50510802_7_dialog_content = "報出身分？我凱萊布·麥格努斯爵士，還需要向誰自報身分？",
  ui_story_5051_50510802_8_dialog_content = "凱萊布·麥格努斯爵士……？！",
  ui_story_5051_50510802_9_dialog_content = "不對，前幾天爵士來找過約書亞夫人。",
  ui_story_5051_50510802_10_dialog_content = "雖然樣貌有幾分相像……但是他的頭髮沒那麼長，身材也和你不一樣！",
  ui_story_5051_50510802_11_dialog_content = "入侵者，快給我束手就……",
  ui_story_5051_50510802_12_dialog_content = "吵死了，別把其他士兵引過來。",
  ui_story_5051_50510802_13_dialog_content = "（這是第二次節外生枝了，今天真是不順。）",
  ui_story_5051_50510802_14_dialog_content = "（得趕緊在光能耗盡前偷到「永憶鏡晶」……）",
  ui_story_5051_50510802_15_dialog_content = "飲料我買來了！",
  ui_story_5051_50510802_16_dialog_content = "喔，回來啦。",
  ui_story_5051_50510802_17_dialog_content = "嗯～？怎麼是醒酒茶啊？",
  ui_story_5051_50510802_18_dialog_content = "誰叫妳現在醉醺醺的，都不能好好跟我說話……",
  ui_story_5051_50510802_19_dialog_content = "誰叫妳突然哭著撲過來，弄得我一身鼻涕。",
  ui_story_5051_50510802_20_dialog_content = "我不管～我要喝酒～",
  ui_story_5051_50510802_21_dialog_content = "好吧好吧……酒我也買了，給妳。",
  ui_story_5051_50510802_22_dialog_content = "咕嚕咕嚕……噗哈～好酒好酒！還是喝這個才爽！",
  ui_story_5051_50510802_23_dialog_content = "妳喝飽了，現在願意傳授我占卜的知識了嗎？",
  ui_story_5051_50510802_24_dialog_content = "嗯……好吧，妳想聽什麼？",
  ui_story_5051_50510802_25_dialog_content = "關於進入「永憶鏡晶」的咒語，妳瞭解多少？",
  ui_story_5051_50510802_26_dialog_content = "為什麼唸了咒語之後，進入的人不只沒辦法隱身，還會分散到世界各處啊……",
  ui_story_5051_50510802_27_dialog_content = "「永憶」……「鏡晶」……？",
  ui_story_5051_50510802_28_dialog_content = "小丫頭，這不是妳該知道的事情。",
  ui_story_5051_50510802_29_dialog_content = "妳到底是什麼來頭？",
  ui_story_5051_50510802_30_dialog_content = "我不是跟妳說了嘛！我是妳的女兒，加晴！",
  ui_story_5051_50510802_31_dialog_content = "開什麼玩笑～加晴？",
  ui_story_5051_50510802_32_dialog_content = "雖然我的確不愛回家……但加晴也不可能從路都不會走……",
  ui_story_5051_50510802_33_dialog_content = "一下子變得這麼高吧！！",
  ui_story_5051_50510802_34_dialog_content = "我才覺得妳在開玩笑呢！",
  ui_story_5051_50510802_35_dialog_content = "媽媽……媽媽不是個神祕、偉大、不食人間煙火的占卜師嗎？",
  ui_story_5051_50510802_36_dialog_content = "怎麼會是個大酒鬼啊！！",
  ui_story_5051_50510802_37_dialog_content = "妳……妳說誰大酒鬼啊？",
  ui_story_5051_50510802_38_dialog_content = "請叫我，嗝，如北風般難以捉摸的女人——博阿姿！",
  ui_story_5051_50510802_39_dialog_content = "唉……什麼跟什麼啊……",
  ui_story_5051_50510802_40_dialog_content = "我本來不該跟妳說這件事的，但事到如今我也只能靠妳了。",
  ui_story_5051_50510802_41_dialog_content = "我只說一遍，妳一定要好好聽清楚喔！",
  ui_story_5051_50510802_42_dialog_content = "啊？",
  ui_story_5051_50510802_43_dialog_content = "我的母親，就是妳，博阿姿。",
  ui_story_5051_50510802_44_dialog_content = "是妳製作了那顆「永憶鏡晶」，而現在這裡正是「永憶鏡晶」中的世界。",
  ui_story_5051_50510802_45_dialog_content = "距今十二年後，「永憶鏡晶」的啟動者已經離世。",
  ui_story_5051_50510802_46_dialog_content = "為了進入這個世界，我根據妳留下的筆記，編了一段咒語。",
  ui_story_5051_50510802_47_dialog_content = "但是進入這個世界後，卻無法隱身，還和同伴失散了……",
  ui_story_5051_50510802_48_dialog_content = "現在我該怎麼辦？",
  ui_story_5051_50510802_49_dialog_content = "……這樣啊。",
  ui_story_5051_50510802_50_dialog_content = "妳理解了……？",
  ui_story_5051_50510802_51_dialog_content = "原來妳的媽媽和我同名，還抄襲了我的作品啊！",
  ui_story_5051_50510802_52_dialog_content = "都說我的名字能為人帶來好運，但是妳媽媽～嗯，還差一點喔～",
  ui_story_5051_50510802_53_dialog_content = "唔——妳這個——",
  ui_story_5051_50510802_54_dialog_content = "妳這個大酒鬼！妳愛喝就喝吧！",
  ui_story_5051_50510802_55_dialog_content = "喝得顛三倒四把什麼都忘了！把我跟爸爸也都忘掉算了！妳再也別回來了！！",
  ui_story_5051_50510802_56_dialog_content = "小丫頭，說話別這麼難聽。",
  ui_story_5051_50510802_57_dialog_content = "妳說妳靠媽媽的筆記，編了一段進入「永憶鏡晶」的咒語？",
  ui_story_5051_50510802_58_dialog_content = "開什麼玩笑，這種事我都做不到。",
  ui_story_5051_50510802_59_dialog_content = "如果有人能做到，那她一定是前所未有的天才！",
  ui_story_5051_50510802_60_dialog_content = "天、天才……？",
  ui_story_5051_50510802_61_dialog_content = "我是前所未有的天才？",
  ui_story_5051_50510802_62_dialog_content = "哈哈哈哈哈，我要是妳媽媽，我一定會樂歪的！",
  ui_story_5051_50510802_63_dialog_content = "嘿嘿……是嗎……",
  ui_story_5051_50510802_64_dialog_content = "不對！這種事不重要！",
  ui_story_5051_50510802_65_dialog_content = "我現在到底該怎麼辦啊！",
  ui_story_5051_50510802_66_dialog_content = "嗯……妳把妳編的那段咒語唸給我聽。",
  ui_story_5051_50510802_67_dialog_content = "喔，好。",
  ui_story_5051_50510802_68_dialog_content = "艾·普勒塔立吐姆，艾·普勒塔立吐姆，艾·普勒塔立吐姆！",
  ui_story_5051_50510802_69_dialog_content = "讓我們走進那段往日時光吧！",
  ui_story_5051_50510802_70_dialog_content = "阿布拉「哈」達布拉！",
  ui_story_5051_50510802_71_dialog_content = "就這樣……",
  ui_story_5051_50510802_72_dialog_content = "嗯？嗯～妳這咒語，唸錯了。",
  ui_story_5051_50510802_73_dialog_content = "啊？",
  ui_story_5051_50510802_74_dialog_content = "不是「阿布拉『哈』達布拉」，而是「阿布拉『卡』達布拉」才對。",
  ui_story_5051_50510802_75_dialog_content = "妳怎麼回事呀～當占卜師這麼不嚴謹～",
  ui_story_5051_50510802_76_dialog_content = "不是啊，媽媽留下的筆記上就是這樣寫的！妳看！",
  ui_story_5051_50510802_77_dialog_content = "我看看……哈哈哈哈，這人字怎麼這麼爛。",
  ui_story_5051_50510802_78_dialog_content = "這裡，筆跡都撇到天上去了，怪不得妳會看錯。",
  ui_story_5051_50510802_79_dialog_content = "她是不是喝醉寫的啊？",
  ui_story_5051_50510802_80_dialog_content = "不就是妳寫的嗎！！",
  ui_story_5051_50510802_81_dialog_content = "哈哈哈哈……",
  ui_story_5051_50510802_82_dialog_content = "這個咒語，不錯嘛～",
  ui_story_5051_50510802_83_dialog_content = "但是實際施咒的時候，還有很多細節要注意喔。",
  ui_story_5051_50510802_84_dialog_content = "你們進來的時候，有沒有手牽著手呀？",
  ui_story_5051_50510802_85_dialog_content = "沒有……",
  ui_story_5051_50510802_86_dialog_content = "那就難怪傳送後會失散了。",
  ui_story_5051_50510802_87_dialog_content = "不過，我跟大家說了，千萬不可以改變這個世界。",
  ui_story_5051_50510802_88_dialog_content = "所以，應該不會出大問題吧……？",
  ui_story_5051_50510802_89_dialog_content = "哎～不對喲～",
  ui_story_5051_50510802_90_dialog_content = "只要你們不是隱身狀態，哪怕只是呼吸都會改變這個世界喔。",
  ui_story_5051_50510802_91_dialog_content = "什麼……",
  ui_story_5051_50510802_92_dialog_content = "只要「永憶鏡晶」裡的世界能感知到你們的存在，一切就會受到你們影響而漸漸調整。",
  ui_story_5051_50510802_93_dialog_content = "調整到最後……",
  ui_story_5051_50510802_94_dialog_content = "調整到最後……？",
  ui_story_5051_50510802_95_dialog_content = "你們就會成為世界的一部分，<color=#FFB400>永遠都出不去</color>囉。",
  ui_story_5051_50510802_96_dialog_content = "<size=45>什麼？！</size>",
  ui_story_5051_50510802_97_dialog_content = "哎喲，小聲點，小聲點……",
  ui_story_5051_50510802_98_dialog_content = "那我們現在還來得及嗎？還有多少時間？",
  ui_story_5051_50510802_99_dialog_content = "嗯～「永憶鏡晶」能儲存的時間大概是一天……",
  ui_story_5051_50510802_100_dialog_content = "只要這一天沒過完，就沒事吧～大概啦～",
  ui_story_5051_50510802_101_dialog_content = "那還來得及！要趕快跟大家會合，把大家一起送出去！",
  ui_story_5051_50510802_102_dialog_content = "謝謝媽媽！再見！總有一天我會把妳抓回家的！！",
  ui_story_5051_50510802_103_dialog_content = "啊？等等，妳要去哪裡啊？",
  ui_story_5051_50510802_104_dialog_content = "哇？！妳、妳幹什麼啊！我先說我已經沒錢買酒給妳了！",
  ui_story_5051_50510802_105_dialog_content = "妳、已經找了一上午的人了吧？",
  ui_story_5051_50510802_106_dialog_content = "要不是我出手相助……是不是一個都沒找到？",
  ui_story_5051_50510802_107_dialog_content = "對……",
  ui_story_5051_50510802_108_dialog_content = "嗯～看在妳媽媽和我同名的份上，幫妳一次吧。",
  ui_story_5051_50510802_109_dialog_content = "我來教妳使用占卜術。",
  ui_story_5051_50510802_110_dialog_content = "真的？！",
  ui_story_5051_50510802_111_dialog_content = "真的真的……好啦，趁我興致還在，趕快開始吧。",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>……</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>狄……</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>安……</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>狄安理……</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>薇羅妮卡……卡蓮……</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>狄安理……薇羅妮卡……卡蓮……</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>狄安理！薇羅妮卡！卡蓮！</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>轟隆隆——！</color>",
  ui_story_5051_50510901_9_dialog_content = "啊？！",
  ui_story_5051_50510901_10_dialog_content = "PlayerName，您怎麼了？",
  ui_story_5051_50510901_11_dialog_content = "臉色怎麼忽然變得這麼難看？",
  ui_story_5051_50510901_12_dialog_content = "沒、沒什麼，我剛才被打雷的聲音嚇了一跳。",
  ui_story_5051_50510901_13_dialog_content = "打雷的聲音？",
  ui_story_5051_50510901_14_dialog_content = "早上我就有聽到一聲，不過剛才這聲比早上更響了。",
  ui_story_5051_50510901_15_dialog_content = "看樣子，待會恐怕要下暴雨了吧。",
  ui_story_5051_50510901_16_dialog_content = "卡蓮怎麼沒有聽到打雷的聲音？",
  ui_story_5051_50510901_17_dialog_content = "咦，剛才的雷聲那麼大聲，妳都沒聽到嗎？",
  ui_story_5051_50510901_18_dialog_content = "就算聽到了，卡蓮也不害怕。",
  ui_story_5051_50510901_19_dialog_content = "呃哈哈哈，卡蓮……卡蓮殿下真是個勇敢的小朋友。",
  ui_story_5051_50510901_20_dialog_content = "卡蓮，已經不是小孩子了。",
  ui_story_5051_50510901_21_dialog_content = "……",
  ui_story_5051_50510901_22_dialog_content = "咦，卡蓮？",
  ui_story_5051_50510901_23_dialog_content = "（又跑回約書亞夫人身邊了嗎？）",
  ui_story_5051_50510901_24_dialog_content = "（剛剛那個眼神……真是和現在沒什麼差別啊。）",
  ui_story_5051_50510901_25_dialog_content = "卡蓮公主就是這樣，如果把她當小孩子看，她可能會生悶氣喔。",
  ui_story_5051_50510901_26_dialog_content = "不過說也奇怪，能讓卡蓮公主感興趣的人，您還是第一位呢。",
  ui_story_5051_50510901_27_dialog_content = "感興趣？",
  ui_story_5051_50510901_28_dialog_content = "您沒有發現嗎？卡蓮公主剛才站在附近觀察您很久了。",
  ui_story_5051_50510901_29_dialog_content = "難道她還在警惕我嗎……",
  ui_story_5051_50510901_30_dialog_content = "啊，蜜雅……薇羅妮卡還在跟士兵切磋，這種關鍵時刻我怎麼可以分心！",
  ui_story_5051_50510901_31_dialog_content = "這就是，我的力量！",
  ui_story_5051_50510901_32_dialog_content = "呃……咳咳咳。",
  ui_story_5051_50510901_33_dialog_content = "薇羅妮卡公主似乎並未使出全力，但在比試中明顯處於優勢。",
  ui_story_5051_50510901_34_dialog_content = "才幾日未見，薇羅妮卡公主的劍術竟然就有這麼驚人的進步。",
  ui_story_5051_50510901_35_dialog_content = "我實在很好奇，PlayerName究竟給了薇羅妮卡公主什麼靈丹妙藥？",
  ui_story_5051_50510901_36_dialog_content = "（這一路上，蜜雅似乎都不肯相信自己的力量。）",
  ui_story_5051_50510901_37_dialog_content = "（過去的她在大家眼中，原來一直都是不擅長戰鬥的形象嗎？）",
  ui_story_5051_50510901_38_dialog_content = "用沉默回應我嗎？看來這件事又是我不能知道的祕密呢。",
  ui_story_5051_50510901_39_dialog_content = "其實，這不是什麼祕密。",
  ui_story_5051_50510901_40_dialog_content = "薇羅妮卡她一直都很強大，只不過是過去的她沒有發現而已。",
  ui_story_5051_50510901_41_dialog_content = "喔？",
  ui_story_5051_50510901_42_dialog_content = "喔喔——好險，那個衛兵差點就被薇羅妮卡公主殿下擊中了？",
  ui_story_5051_50510901_43_dialog_content = "劍刃之間的火花從這裡都清晰可見……這是一場真刀真槍的決鬥啊！",
  ui_story_5051_50510901_44_dialog_content = "薇羅妮卡公主，現在開始我們只為您歡呼！",
  ui_story_5051_50510901_45_dialog_content = "喔喔——！",
  ui_story_5051_50510901_46_dialog_content = "薇羅妮卡公主的劍法又贏得了大家的歡呼和掌聲呢。",
  ui_story_5051_50510901_47_dialog_content = "話說，您剛才是不是將這些掌聲錯聽成雷聲？",
  ui_story_5051_50510901_48_dialog_content = "是這樣嗎……",
  ui_story_5051_50510901_49_dialog_content = "（咦，等等！）",
  ui_story_5051_50510901_50_dialog_content = "（……怎麼回事，怎麼感覺背後有股寒意襲來？）",
  ui_story_5051_50510901_51_dialog_content = "（有人！有人在盯著我看！）",
  ui_story_5051_50510901_52_dialog_content = "（不是卡蓮，也不是那位正在觀看女兒比試的城主大人和約書亞夫人。）",
  ui_story_5051_50510901_53_dialog_content = "（這種感覺，難道是……）",
  ui_story_5051_50510901_54_dialog_content = "PlayerName，您去哪裡？",
  ui_story_5051_50510901_55_dialog_content = "我、我想去一下洗手間。",
  ui_story_5051_50510901_56_dialog_content = "既然如此，就讓我為您帶路吧。",
  ui_story_5051_50510901_57_dialog_content = "我自己去就可以！",
  ui_story_5051_50510901_58_dialog_content = "PlayerName……跑得倒是挺快的。",
  ui_story_5051_50510901_59_dialog_content = "薇羅妮卡公主的這位朋友，還真是有趣呢。",
  ui_story_5051_50510901_60_dialog_content = "剛剛目光的源頭，應該就在這附近吧……",
  ui_story_5051_50510901_61_dialog_content = "咳。",
  ui_story_5051_50510901_62_dialog_content = "城主大人，真的是您！",
  ui_story_5051_50510901_63_dialog_content = "不愧是PlayerName，你的感覺還是很敏銳。",
  ui_story_5051_50510901_64_dialog_content = "您是怎麼找到這裡的？",
  ui_story_5051_50510901_65_dialog_content = "年輕人愛湊熱鬧，我想也許會在這裡找到你。",
  ui_story_5051_50510901_66_dialog_content = "只是我沒有想到，你這麼快就和<color=#FFB400>這個世界的我</color>見面了。",
  ui_story_5051_50510901_67_dialog_content = "那是因為……",
  ui_story_5051_50510901_68_dialog_content = "你應該已經明白，我們被捲入了「永憶鏡晶」所記錄的歷史當中。",
  ui_story_5051_50510901_69_dialog_content = "理應隱身觀察這個世界的我們，卻能夠被這個世界的人看到。",
  ui_story_5051_50510901_70_dialog_content = "我也很奇怪，到底是哪裡出了問題？",
  ui_story_5051_50510901_71_dialog_content = "年輕人，現在想這個為時已晚。",
  ui_story_5051_50510901_72_dialog_content = "問題已經發生，當務之急是規避可能發生的風險、尋找解決問題的辦法。",
  ui_story_5051_50510901_73_dialog_content = "加晴說過，不要試圖影響「永憶鏡晶」中的歷史，否則會產生難以預料的嚴重後果。",
  ui_story_5051_50510901_74_dialog_content = "為了不和這個世界產生糾葛，我們必須低調行事。",
  ui_story_5051_50510901_75_dialog_content = "我和蜜雅也是為了進城找大家，所以才不得不……",
  ui_story_5051_50510901_76_dialog_content = "……",
  ui_story_5051_50510901_77_dialog_content = "城主大人？您為何忽然露出這種表情？",
  ui_story_5051_50510901_78_dialog_content = "蜜雅……跟他們相認了嗎？",
  ui_story_5051_50510901_79_dialog_content = "「他們」是指……？",
  ui_story_5051_50510901_80_dialog_content = "你知道我說的是誰。",
  ui_story_5051_50510901_81_dialog_content = "咳咳，如果您說的是約書亞夫人、小卡蓮，還有這裡的舒瓦茲大人……",
  ui_story_5051_50510901_82_dialog_content = "是的，他們接納了蜜雅，還把蜜雅喚做「薇羅妮卡」。",
  ui_story_5051_50510901_83_dialog_content = "蜜雅如今的樣貌，的確和當年的她一模一樣。",
  ui_story_5051_50510901_84_dialog_content = "這麼說……您承認了？",
  ui_story_5051_50510901_85_dialog_content = "蜜雅就是「薇羅妮卡」公主，您的女兒？",
  ui_story_5051_50510901_86_dialog_content = "……我們的行動已經干擾了這個世界。",
  ui_story_5051_50510901_87_dialog_content = "你竟然還讓蜜雅冒著生命危險去和衛兵決鬥？",
  ui_story_5051_50510901_88_dialog_content = "你有沒有想過，如果她受傷了怎麼辦？",
  ui_story_5051_50510901_89_dialog_content = "蜜雅身為白夜城城主之女，一直被當作瘋狂的病人藏在影鎮……",
  ui_story_5051_50510901_90_dialog_content = "她的父親有沒有想過，如果蜜雅在影鎮受傷了怎麼辦？",
  ui_story_5051_50510901_91_dialog_content = "年輕人，記住。",
  ui_story_5051_50510901_92_dialog_content = "不瞭解事情的全貌，就不要隨意評斷。",
  ui_story_5051_50510901_93_dialog_content = "抱歉，我的確不瞭解你們父女之間到底發生了什麼事。",
  ui_story_5051_50510901_94_dialog_content = "但您好像也不瞭解蜜雅真正的實力。",
  ui_story_5051_50510901_95_dialog_content = "嗯？",
  ui_story_5051_50510901_96_dialog_content = "好劍法！",
  ui_story_5051_50510901_97_dialog_content = "薇羅妮卡公主！薇羅妮卡公主！薇羅妮卡公主！",
  ui_story_5051_50510901_98_dialog_content = "您看，蜜雅的劍法得到了所有人的認同和歡呼。",
  ui_story_5051_50510901_99_dialog_content = "曾經的蜜雅，並不擅長戰鬥。",
  ui_story_5051_50510901_100_dialog_content = "而現在的她已經有如此強大的戰鬥能力了嗎……",
  ui_story_5051_50510901_101_dialog_content = "蜜雅似乎很想把握這次機會，讓父親相信她的實力不只如此。",
  ui_story_5051_50510901_102_dialog_content = "但現在不是個好時機。",
  ui_story_5051_50510901_103_dialog_content = "PlayerName，要想辦法讓蜜雅快點結束這場決鬥。",
  ui_story_5051_50510901_104_dialog_content = "為什麼？我不懂，蜜雅馬上就要贏了。",
  ui_story_5051_50510901_105_dialog_content = "您還是不相信她嗎？",
  ui_story_5051_50510901_106_dialog_content = "PlayerName，你知道當年的儀式上發生了什麼事嗎？",
  ui_story_5051_50510901_107_dialog_content = "咦？",
  ui_story_5051_50510901_108_dialog_content = "薇羅妮卡公主，接下來我要使出全力了！",
  ui_story_5051_50510901_109_dialog_content = "嗯……請不要手下留情。",
  ui_story_5051_50510901_110_dialog_content = "喝啊！",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>鏘！</color>",
  ui_story_5051_50510901_112_dialog_content = "什麼？連這招都能擋下來？",
  ui_story_5051_50510901_113_dialog_content = "……承讓了。",
  ui_story_5051_50510901_114_dialog_content = "（剛才對方的力氣好大，差一點就接不住了。）",
  ui_story_5051_50510901_115_dialog_content = "（不知道PlayerName有沒有看到？）",
  ui_story_5051_50510901_116_dialog_content = "（咦，PlayerName在哪裡？）",
  ui_story_5051_50510901_117_dialog_content = "（找到了！但是他身邊的人是……）",
  ui_story_5051_50510901_118_dialog_content = "姐姐，小心啊！",
  ui_story_5051_50510901_119_dialog_content = "喝——啊！",
  ui_story_5051_50510901_120_dialog_content = "（怎麼辦？！我、我可能會接不住這一招。）",
  ui_story_5051_50510901_121_dialog_content = "（要躲開嗎？不、不行，父親他正看著我，要是被他看到……）",
  ui_story_5051_50510901_122_dialog_content = "（對，還有時間，我可以累積力量來反擊！）",
  ui_story_5051_50510901_123_dialog_content = "她是要把<color=#FFB400>那個東西</color>給放出來嗎？",
  ui_story_5051_50510901_124_dialog_content = "薇羅妮卡……",
  ui_story_5051_50510901_125_dialog_content = "（不行！父親不喜歡我召喚希頗喀，我怎麼能忘了這件事？）",
  ui_story_5051_50510901_126_dialog_content = "（可是手上這股力量已經……再這樣下去會傷到對面的衛兵。）",
  ui_story_5051_50510901_127_dialog_content = "（怎麼辦？怎麼辦？怎麼辦？）",
  ui_story_5051_50510901_128_dialog_content = "（旁邊那些木箱子是做什麼用的？也許那些箱子可以擋住我這股力量？）",
  ui_story_5051_50510901_129_dialog_content = "怎麼回事，蜜雅為什麼要跑向旁邊？",
  ui_story_5051_50510901_130_dialog_content = "她明明差一點就可以召出她的光能召喚物了！",
  ui_story_5051_50510901_131_dialog_content = "……",
  ui_story_5051_50510901_132_dialog_content = "薇羅妮卡，以後不要讓別人看到妳召喚出的怪物。",
  ui_story_5051_50510901_133_dialog_content = "希頗喀牠、牠不是怪物。",
  ui_story_5051_50510901_134_dialog_content = "長著馬頭的蜘蛛怪物，妳還幫牠取名字？",
  ui_story_5051_50510901_135_dialog_content = "卡蓮不是也有她的白馬嗎？",
  ui_story_5051_50510901_136_dialog_content = "薇羅妮卡，妳並沒有戰鬥的天賦，不要再糾結這些事了。",
  ui_story_5051_50510901_137_dialog_content = "咦……",
  ui_story_5051_50510901_138_dialog_content = "看樣子，她還記得那件事。",
  ui_story_5051_50510901_139_dialog_content = "蜜雅要撞到那些木箱了！",
  ui_story_5051_50510901_140_dialog_content = "什麼？！",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>吼——！</anim>",
  ui_story_5051_50510901_143_dialog_content = "暗鬼？是暗鬼啊！",
  ui_story_5051_50510901_144_dialog_content = "那些裝飾用的箱子怎麼會藏著這麼多暗鬼啊？",
  ui_story_5051_50510901_145_dialog_content = "快逃啊！",
  ui_story_5051_50510901_146_dialog_content = "咦，怎、怎麼回事？",
  ui_story_5051_50510901_147_dialog_content = "是、是因為我嗎？",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>吼！</anim>",
  ui_story_5051_50510901_149_dialog_content = "我果然不應該上場出風頭……",
  ui_story_5051_50510901_150_dialog_content = "每次我決定要做什麼事，最後都會變成這樣。",
  ui_story_5051_50510901_151_dialog_content = "總是會帶來不好的結果……",
  ui_story_5051_50510901_152_dialog_content = "加入騎士團？薇羅妮卡，我不求妳有多出眾，至少別讓妳母親擔心！",
  ui_story_5051_50510901_153_dialog_content = "公主殿下，您不用隨我們去戰鬥，只要待在安全區就行了！",
  ui_story_5051_50510901_154_dialog_content = "薇羅妮卡，妳怎麼了……？",
  ui_story_5051_50510901_155_dialog_content = "不——！",
  ui_story_5051_50510901_156_dialog_content = "都是因為我、都是因為我才……",
  ui_story_5051_50510901_157_dialog_content = "注意敵人，後退！",
  ui_story_5051_50510901_158_dialog_content = "咦？",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>吼！！</anim>",
  ui_story_5051_50510901_160_dialog_content = "主宰之刃！",
  ui_story_5051_50510901_161_dialog_content = "父親？是、是真正的父親？",
  ui_story_5051_50510901_162_dialog_content = "蜜雅，妳還好嗎？",
  ui_story_5051_50510901_163_dialog_content = "PlayerName……我很好，只是不小心分神了。",
  ui_story_5051_50510901_164_dialog_content = "妳真的沒事嗎？",
  ui_story_5051_50510901_165_dialog_content = "我、我沒事！",
  ui_story_5051_50510901_166_dialog_content = "很好，我們一起衝出去。",
  ui_story_5051_50510901_167_dialog_content = "第一次……這是父親第一次與我並肩戰鬥。",
  ui_story_5051_50510901_168_dialog_content = "還有……",
  ui_story_5051_50510901_169_dialog_content = "如果妳想召喚出希頗喀，就讓牠出來吧。",
  ui_story_5051_50510901_170_dialog_content = "咦，父親？",
  ui_story_5051_50510901_171_dialog_content = "準備好了嗎？",
  ui_story_5051_50510901_172_dialog_content = "……嗯！",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>另一邊</color>",
  ui_story_5051_50510901_174_dialog_content = "那些黑色的怪物……是暗鬼？！",
  ui_story_5051_50510901_175_dialog_content = "母親，卡蓮可以保護大家！",
  ui_story_5051_50510901_176_dialog_content = "卡蓮，我相信妳有這樣的能力，但現在還不是時候，好嗎？",
  ui_story_5051_50510901_177_dialog_content = "……好。",
  ui_story_5051_50510901_178_dialog_content = "約書亞，紅女士會保護妳和卡蓮撤退，快走！",
  ui_story_5051_50510901_179_dialog_content = "狄安理，我也……",
  ui_story_5051_50510901_180_dialog_content = "放心，約書亞。",
  ui_story_5051_50510901_181_dialog_content = "我會把薇羅妮卡好好帶回來的。",
  ui_story_5051_50510901_182_dialog_content = "我要妳們兩個都安然無恙地回家。",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>吼啊！</anim>",
  ui_story_5051_50510901_184_dialog_content = "主宰一切！",
  ui_story_5051_50510901_185_dialog_content = "這群傢伙已經擴散到這裡了嗎。",
  ui_story_5051_50510901_186_dialog_content = "呵，你們這是自討苦吃。",
  ui_story_5051_50511001_1_dialog_content = "因瓦尼勒嗚姆～因瓦尼勒嗚姆～因瓦尼勒嗚姆～",
  ui_story_5051_50511001_2_dialog_content = "請告訴我，我心中所想的那位城主大人，現在在哪裡？",
  ui_story_5051_50511001_3_dialog_content = "<size=42>阿布拉卡達布拉！</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>嗡嗡嗡！</color>",
  ui_story_5051_50511001_5_dialog_content = "哇，我的小占卜球第一次這麼熱烈地回應我耶！",
  ui_story_5051_50511001_6_dialog_content = "原來我以前真的都沒把最後一句咒語唸對呀？",
  ui_story_5051_50511001_7_dialog_content = "但我還是很好奇……",
  ui_story_5051_50511001_8_dialog_content = "為什麼每次唸完咒，都要加上一句「阿布拉卡達布拉」？",
  ui_story_5051_50511001_9_dialog_content = "「阿布拉卡達布拉」這句話，有什麼特殊的含義嗎？",
  ui_story_5051_50511001_10_dialog_content = "嗯？是什麼意思來著……",
  ui_story_5051_50511001_11_dialog_content = "啊～我想起來了～",
  ui_story_5051_50511001_12_dialog_content = "「不聽我的就消滅你」！",
  ui_story_5051_50511001_13_dialog_content = "咦——？！",
  ui_story_5051_50511001_14_dialog_content = "哈哈哈哈哈！看看妳大驚小怪的樣子，好好玩哈哈哈。",
  ui_story_5051_50511001_15_dialog_content = "唔？妳是在取笑我？！",
  ui_story_5051_50511001_16_dialog_content = "<size=30>小時候媽媽對我的溫柔回憶，難道都是被大腦加工過的嗎……</size>",
  ui_story_5051_50511001_17_dialog_content = "喂，還在碎唸什麼？再不回應妳的小占卜球，上面的結果就要消失囉。",
  ui_story_5051_50511001_18_dialog_content = "啊，差點把正事給忘了！",
  ui_story_5051_50511001_19_dialog_content = "小占卜球上顯示……",
  ui_story_5051_50511001_20_dialog_content = "舒瓦茲大人、PlayerName和蜜雅都在同一個方位？",
  ui_story_5051_50511001_21_dialog_content = "原來他們已經會合了呀。",
  ui_story_5051_50511001_22_dialog_content = "……那我豈不是在這裡浪費了好多時間？",
  ui_story_5051_50511001_23_dialog_content = "怎麼會是浪費時間呢～？",
  ui_story_5051_50511001_24_dialog_content = "我可是把我的獨門咒語都教給妳了喔～",
  ui_story_5051_50511001_25_dialog_content = "對哦，有道理耶！",
  ui_story_5051_50511001_26_dialog_content = "這還是我第一次這麼準確地占卜到目標的方位！",
  ui_story_5051_50511001_27_dialog_content = "不過……",
  ui_story_5051_50511001_28_dialog_content = "現在可以告訴我「阿布拉卡達布拉」到底是什麼意思了嗎？",
  ui_story_5051_50511001_29_dialog_content = "啊頭痛，頭好痛！",
  ui_story_5051_50511001_30_dialog_content = "再給我來點好喝的我才能想起來啊。",
  ui_story_5051_50511001_31_dialog_content = "唉，又來了嗎？",
  ui_story_5051_50511001_32_dialog_content = "這裡應該已經沒事了吧？",
  ui_story_5051_50511001_33_dialog_content = "還是跑遠一點吧，快跟上！",
  ui_story_5051_50511001_34_dialog_content = "咦？為什麼大家忽然從廣場那邊跑出來了？",
  ui_story_5051_50511001_35_dialog_content = "大家稍安勿躁，小心不要跌倒！",
  ui_story_5051_50511001_36_dialog_content = "騎士大人！請問……",
  ui_story_5051_50511001_37_dialog_content = "嗯？",
  ui_story_5051_50511001_38_dialog_content = "哇，看樣子年紀好像比我還小啊？",
  ui_story_5051_50511001_39_dialog_content = "妳有何事？",
  ui_story_5051_50511001_40_dialog_content = "喔，我是想問，廣場那裡發生什麼事了嗎？",
  ui_story_5051_50511001_41_dialog_content = "詳細情況還不甚瞭解，但上面命令吾等疏散民眾。",
  ui_story_5051_50511001_42_dialog_content = "可是我要找的人還在廣場那裡！",
  ui_story_5051_50511001_43_dialog_content = "稍等，妳的模樣……",
  ui_story_5051_50511001_44_dialog_content = "啊哈，大家都說我長得像我媽……啊不，長得像博阿姿。",
  ui_story_5051_50511001_45_dialog_content = "紅色長髮、綠色眼眸……妳是加晴？",
  ui_story_5051_50511001_46_dialog_content = "咦？你怎麼知道我的名字？",
  ui_story_5051_50511001_47_dialog_content = "等等等等等等，難道你也是被我不小心帶進來的人？",
  ui_story_5051_50511001_48_dialog_content = "抱歉，我聽不懂妳在說什麼。",
  ui_story_5051_50511001_49_dialog_content = "但是薇羅妮卡公主的朋友PlayerName，曾經拜託我尋找妳和另外兩名男士的下落。",
  ui_story_5051_50511001_50_dialog_content = "對，我也要去找PlayerName！",
  ui_story_5051_50511001_51_dialog_content = "但他現在似乎還在中央廣場。",
  ui_story_5051_50511001_52_dialog_content = "先跟我來，等事態穩定下來，我再帶妳去找PlayerName。",
  ui_story_5051_50511001_53_dialog_content = "謝謝你的好意，可是……",
  ui_story_5051_50511001_54_dialog_content = "我怕到時候就來不及了，我得快一點跟大家會合！",
  ui_story_5051_50511001_55_dialog_content = "妳的意思是，妳打算帶著一位醉醺醺的女士，闖進暗鬼橫行的區域？",
  ui_story_5051_50511001_56_dialog_content = "暗鬼？",
  ui_story_5051_50511001_57_dialog_content = "喂喂喂，妳才醉醺醺咧！",
  ui_story_5051_50511001_58_dialog_content = "嗯……好像是有點不太方便。",
  ui_story_5051_50511001_59_dialog_content = "那麼小騎士，可以麻煩你幫忙照顧這位女士嗎？",
  ui_story_5051_50511001_60_dialog_content = "妳要獨自前往廣場找人嗎？",
  ui_story_5051_50511001_61_dialog_content = "嘿嘿，別看我這樣，區區暗鬼可嚇不倒我。",
  ui_story_5051_50511001_62_dialog_content = "妳這丫頭……才剛偷完師就想丟下我落跑啊。",
  ui_story_5051_50511001_63_dialog_content = "妳以為我博阿姿會怕暗鬼嗎？",
  ui_story_5051_50511001_64_dialog_content = "謝謝妳教我咒語的正確讀法。",
  ui_story_5051_50511001_65_dialog_content = "雖然只能這樣匆忙地見妳一面，但我已經很知足了。如果可以……",
  ui_story_5051_50511001_66_dialog_content = "我也不想現在就和妳分開。",
  ui_story_5051_50511001_67_dialog_content = "可是，我也不能拋棄我的朋友們！",
  ui_story_5051_50511001_68_dialog_content = "要不是我的話……他們現在也不會面臨那些危險。",
  ui_story_5051_50511001_69_dialog_content = "聽不懂，帶我走！妳一定要帶我走！",
  ui_story_5051_50511001_70_dialog_content = "妳不想拜師了嗎？況且，我還沒有喝夠呢！",
  ui_story_5051_50511001_71_dialog_content = "……",
  ui_story_5051_50511001_72_dialog_content = "在此等危難時刻仍然為朋友著想，加晴，我很敬佩妳。",
  ui_story_5051_50511001_73_dialog_content = "實不相瞞，我也想去廣場那邊幫忙作戰。",
  ui_story_5051_50511001_74_dialog_content = "如果妳們堅持要過去的話，我可以送妳們一程。",
  ui_story_5051_50511001_75_dialog_content = "咦？真的嗎？",
  ui_story_5051_50511001_76_dialog_content = "跟上我，我幫妳們解決前方的暗鬼！",
  ui_story_5051_50511002_1_dialog_content = "情況如何？",
  ui_story_5051_50511002_2_dialog_content = "這附近的暗鬼應該都除乾淨了。",
  ui_story_5051_50511002_3_dialog_content = "很好。",
  ui_story_5051_50511002_4_dialog_content = "前面有條小路，可以快速離開暗鬼橫行的區域。",
  ui_story_5051_50511002_5_dialog_content = "你們兩個，跟緊我。",
  ui_story_5051_50511002_6_dialog_content = "咦，現在就要走嗎？",
  ui_story_5051_50511002_7_dialog_content = "妳已經戰鬥太久了，需要休息。",
  ui_story_5051_50511002_8_dialog_content = "可是……",
  ui_story_5051_50511002_9_dialog_content = "沒有什麼「可是」。",
  ui_story_5051_50511002_10_dialog_content = "不能在這裡浪費太多時間和精力。",
  ui_story_5051_50511002_11_dialog_content = "我還想、還想幫大家對付暗鬼……",
  ui_story_5051_50511002_12_dialog_content = "<size=45>別想這些了，快走！</size>",
  ui_story_5051_50511002_13_dialog_content = "咦？",
  ui_story_5051_50511002_14_dialog_content = "薇羅妮卡，妳並沒有戰鬥的天賦，不要再糾結這些事了。",
  ui_story_5051_50511002_15_dialog_content = "唔……",
  ui_story_5051_50511002_X15_dialog_content = "（蜜雅這表情，簡直和決鬥前一模一樣。）",
  ui_story_5051_50511002_X16_dialog_content = "（難道蜜雅又想到什麼不好的事情了嗎？）",
  ui_story_5051_50511002_16_dialog_content = "蜜雅，妳想起什麼了嗎？",
  ui_story_5051_50511002_17_dialog_content = "對、對不起！",
  ui_story_5051_50511002_18_dialog_content = "都是我不好，都是我的錯……",
  ui_story_5051_50511002_19_dialog_content = "城主大人，您剛才的話是不是嚇到蜜雅了？",
  ui_story_5051_50511002_20_dialog_content = "她的病才剛好轉，還沒辦法承受太多刺激。",
  ui_story_5051_50511002_21_dialog_content = "……",
  ui_story_5051_50511002_22_dialog_content = "我、我還是無法讓父親滿意。",
  ui_story_5051_50511002_23_dialog_content = "我不配、不配成為父親的孩子，我不配。",
  ui_story_5051_50511002_X21_dialog_content = "我承認我不該多嘴過問您的家事。",
  ui_story_5051_50511002_X22_dialog_content = "可是，一個孩子會如此懼怕自己的父親，根本不正常！",
  ui_story_5051_50511002_24_dialog_content = "城主大人，為什麼蜜雅這麼畏懼您？",
  ui_story_5051_50511002_25_dialog_content = "是因為……",
  ui_story_5051_50511002_26_dialog_content = "您這些年把蜜雅拋棄在影鎮，不聞不問嗎？",
  ui_story_5051_50511002_27_dialog_content = "我從未有一天放棄過蜜雅！",
  ui_story_5051_50511002_28_dialog_content = "……這些事，你不需要知道。",
  ui_story_5051_50511002_X28_dialog_content = "你沒有資格評判我的家庭。",
  ui_story_5051_50511002_X29_dialog_content = "父親，請您別對PlayerName這麼兇……",
  ui_story_5051_50511002_X30_dialog_content = "安靜，我自有分寸。",
  ui_story_5051_50511002_X31_dialog_content = "不，您不可以對PlayerName這麼兇……!",
  ui_story_5051_50511002_X32_dialog_content = "蜜雅……？",
  ui_story_5051_50511002_X33_dialog_content = "「白夜城城主」……「家族的守護者」……您有很多偉大的頭銜。",
  ui_story_5051_50511002_X34_dialog_content = "但這些頭銜……只會讓我窒息。",
  ui_story_5051_50511002_X35_dialog_content = "或許在大家的眼裡，您非常偉大，非常崇高。",
  ui_story_5051_50511002_X36_dialog_content = "但在我面前，您總是那麼兇，總會讓周圍的人傷心……",
  ui_story_5051_50511002_X37_dialog_content = "……",
  ui_story_5051_50511002_29_dialog_content = "我承認我不該多嘴過問您的家事。",
  ui_story_5051_50511002_30_dialog_content = "可是，我相信蜜雅她比我更需要一個答案！",
  ui_story_5051_50511002_31_dialog_content = "……",
  ui_story_5051_50511002_32_dialog_content = "都是我的錯，我是大家的累贅……",
  ui_story_5051_50511002_33_dialog_content = "蜜雅，聽我說！完全沒那回事！",
  ui_story_5051_50511002_34_dialog_content = "我知道，你不用安慰我，我只會害了大家。",
  ui_story_5051_50511002_35_dialog_content = "剛才、剛才要不是我打壞那些木箱，也不會有暗鬼跑出來……",
  ui_story_5051_50511002_36_dialog_content = "那些暗鬼是想謀反的人故意藏在箱子裡的，跟蜜雅一點關係都沒有！",
  ui_story_5051_50511002_37_dialog_content = "正好相反，蜜雅一直在幫助大家！",
  ui_story_5051_50511002_38_dialog_content = "我，在幫助大家嗎？",
  ui_story_5051_50511002_39_dialog_content = "在城外的時候，是妳把我從暗鬼手中救了出來。",
  ui_story_5051_50511002_40_dialog_content = "進城的時候，也是妳幫大家擋住想混進城內的暗鬼。",
  ui_story_5051_50511002_41_dialog_content = "還有剛才，妳也從暗鬼手中救出許多手無寸鐵的民眾。",
  ui_story_5051_50511002_42_dialog_content = "蜜雅，這些還不能證明妳的能力嗎？",
  ui_story_5051_50511002_43_dialog_content = "那、那些都是巧合……我只是運氣好。",
  ui_story_5051_50511002_44_dialog_content = "蜜雅，我該怎麼說才能讓妳相信我呢。",
  ui_story_5051_50511002_45_dialog_content = "城主大人，您應該比我懂更多大道理。",
  ui_story_5051_50511002_46_dialog_content = "我想您一定有很多話要對蜜雅說吧？",
  ui_story_5051_50511002_47_dialog_content = "……",
  ui_story_5051_50511002_X38_dialog_content = "這、這些是我的真實想法。",
  ui_story_5051_50511002_X39_dialog_content = "如果您生氣的話，請衝著我來，不要為難我朋友……！",
  ui_story_5051_50511002_48_dialog_content = "唔……",
  ui_story_5051_50511002_49_dialog_content = "妳，在害怕嗎？",
  ui_story_5051_50511002_50_dialog_content = "我……我不可以說自己害怕。",
  ui_story_5051_50511002_51_dialog_content = "身為父親的長女，我必須要做到最好，父親才不會失望。",
  ui_story_5051_50511002_52_dialog_content = "無論是我喜歡的音樂、美術，還是我不擅長的治國與戰鬥……",
  ui_story_5051_50511002_53_dialog_content = "我都必須要做好。",
  ui_story_5051_50511002_54_dialog_content = "我的孩子，妳已經做得很好了。",
  ui_story_5051_50511002_55_dialog_content = "但我還是沒能幫父親分擔任何壓力。",
  ui_story_5051_50511002_56_dialog_content = "我想起來了，都想起來了。",
  ui_story_5051_50511002_57_dialog_content = "我曾經鼓起勇氣加入騎士團，可是很快就被暗鬼打傷。",
  ui_story_5051_50511002_58_dialog_content = "後來，是媽媽救了我，對嗎？",
  ui_story_5051_50511002_59_dialog_content = "我什麼都沒做，反而幫了倒忙。",
  ui_story_5051_50511002_60_dialog_content = "還有……我剛剛是不是也搞砸了？",
  ui_story_5051_50511002_61_dialog_content = "要不然、要不然父親就不會對我生氣，不會要我快點離開。",
  ui_story_5051_50511002_X61_dialog_content = "因為我太沒用了，所以父親才會一直生氣，是這樣嗎……？",
  ui_story_5051_50511002_62_dialog_content = "我沒有那個意思，蜜雅。",
  ui_story_5051_50511002_63_dialog_content = "您又要……把我送到<color=#FFB400>很遠的地方</color>嗎？",
  ui_story_5051_50511002_64_dialog_content = "！！！",
  ui_story_5051_50511002_65_dialog_content = "把妳送去影鎮隱姓埋名接受治療，是我不得已做出的選擇。",
  ui_story_5051_50511002_66_dialog_content = "但我承認，那時的我還太年輕。",
  ui_story_5051_50511002_67_dialog_content = "如果時間可以重來，我一定會找到更好的方法去兼顧一切。",
  ui_story_5051_50511002_68_dialog_content = "現在說這些已經於事無補，但無論如何……那是我做過最糟糕的決定。",
  ui_story_5051_50511002_69_dialog_content = "這些年來，妳一個人受苦了。",
  ui_story_5051_50511002_70_dialog_content = "父親……",
  ui_story_5051_50511002_71_dialog_content = "我、我好想念媽媽和妹妹，也好想念……您。",
  ui_story_5051_50511002_72_dialog_content = "我都知道，我的孩子。",
  ui_story_5051_50511002_73_dialog_content = "妳在影鎮生活期間，伊斯塔萬一直在向我傳述妳的情況。",
  ui_story_5051_50511002_74_dialog_content = "我知道妳的病情已經有所好轉，或許某一天該向妳說清這一切。",
  ui_story_5051_50511002_75_dialog_content = "只是沒想到，會被捲入這樣的事情之中……",
  ui_story_5051_50511002_76_dialog_content = "我保證，出去之後會把真相一五一十告訴妳。不過當務之急是離開這裡。",
  ui_story_5051_50511002_77_dialog_content = "我……呃……",
  ui_story_5051_50511002_79_dialog_content = "可、可是一旦我們離開這個世界，我是不是就永遠都見不到媽媽了？",
  ui_story_5051_50511002_80_dialog_content = "……",
  ui_story_5051_50511002_81_dialog_content = "是因為我嗎？",
  ui_story_5051_50511002_82_dialog_content = "媽媽她，是因為我才去世的嗎？",
  ui_story_5051_50511002_83_dialog_content = "孩子，那些事我們以後再說。",
  ui_story_5051_50511002_84_dialog_content = "我們先離開這裡。",
  ui_story_5051_50511002_85_dialog_content = "離開……這裡？",
  ui_story_5051_50511002_86_dialog_content = "我不想看到妳再出事了，好嗎？",
  ui_story_5051_50511002_87_dialog_content = "……嗯。",
  ui_story_5051_50511002_88_dialog_content = "來，還站得起來嗎？",
  ui_story_5051_50511002_89_dialog_content = "把手給我，我們一起走。",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>嗖！</color>",
  ui_story_5051_50511002_91_dialog_content = "嗯？",
  ui_story_5051_50511002_92_dialog_content = "這是……什麼情況？",
  ui_story_5051_50511002_93_dialog_content = "父親！",
  ui_story_5051_50511002_94_dialog_content = "薇羅妮卡，離遠一點。",
  ui_story_5051_50511002_95_dialog_content = "別靠近這個人！他想綁架妳！",
  ui_story_5051_50511002_96_dialog_content = "……",
  ui_story_5051_50511002_97_dialog_content = "（年輕的舒瓦茲竟然沒有認出對面的人就是自己？！）",
  ui_story_5051_50511002_98_dialog_content = "（不過也是……）",
  ui_story_5051_50511002_99_dialog_content = "（如果不知道實情，我肯定不會相信眼前的這兩人其實是同一個人。）",
  ui_story_5051_50511002_100_dialog_content = "你既然有膽挾持我舒瓦茲的女兒……",
  ui_story_5051_50511002_101_dialog_content = "為何現在沒膽與我正面對決？",
  ui_story_5051_50511002_102_dialog_content = "我不想引起一些不必要的誤會。",
  ui_story_5051_50511002_103_dialog_content = "不必要的誤會？",
  ui_story_5051_50511002_104_dialog_content = "我並沒有見過你的印象。",
  ui_story_5051_50511002_105_dialog_content = "你來自特洛伊家族？不、不像。",
  ui_story_5051_50511002_106_dialog_content = "那麼，就是卡爾帝瑪家族？",
  ui_story_5051_50511002_107_dialog_content = "都不是，我是薇羅妮卡的……",
  ui_story_5051_50511002_108_dialog_content = "朋友。",
  ui_story_5051_50511002_109_dialog_content = "「朋友」？",
  ui_story_5051_50511002_110_dialog_content = "朋友的朋友，仍舊是朋友。",
  ui_story_5051_50511002_111_dialog_content = "有趣，但我只聽過「敵人的敵人，就是朋友」。",
  ui_story_5051_50511002_112_dialog_content = "現在你聽過了。",
  ui_story_5051_50511002_113_dialog_content = "你的口氣，聽起來可不像是想跟我成為朋友。",
  ui_story_5051_50511002_114_dialog_content = "父親，他的確是……我在影鎮認識的朋友。",
  ui_story_5051_50511002_115_dialog_content = "剛才他還出手幫了我。",
  ui_story_5051_50511002_116_dialog_content = "早晚不出現，偏偏和暗鬼一起出現。",
  ui_story_5051_50511002_117_dialog_content = "這未免太湊巧了一點。",
  ui_story_5051_50511002_118_dialog_content = "薇羅妮卡，以後交朋友要多讓妳母親替妳把關。",
  ui_story_5051_50511002_119_dialog_content = "……",
  ui_story_5051_50511002_120_dialog_content = "（咳，舒瓦茲一定快要被年輕的自己氣死了吧。）",
  ui_story_5051_50511002_121_dialog_content = "（可是，再這樣下去不是辦法……）",
  ui_story_5051_50511002_122_dialog_content = "（又不能直接告訴年輕舒瓦茲「這是十幾年以後的你」。）",
  ui_story_5051_50511002_123_dialog_content = "（只能豁出去了……）",
  ui_story_5051_50511002_124_dialog_content = "其實！",
  ui_story_5051_50511002_125_dialog_content = "嗯？",
  ui_story_5051_50511002_126_dialog_content = "城主大人，請您手下留情。",
  ui_story_5051_50511002_127_dialog_content = "其實他是我的父親……臨空。",
  ui_story_5051_50511002_128_dialog_content = "這次我跟薇羅妮卡公主回訪白夜城，沒有告訴他。",
  ui_story_5051_50511002_129_dialog_content = "他才會託朋友來白夜城找我。",
  ui_story_5051_50511002_130_dialog_content = "沒想到我們剛見面，就遇上暗鬼的襲擊。",
  ui_story_5051_50511002_131_dialog_content = "沒、沒錯！",
  ui_story_5051_50511002_132_dialog_content = "哈哈，看，我都說了這是場誤會。",
  ui_story_5051_50511002_133_dialog_content = "但我也要謝謝您和家人此前對PlayerName的關照。",
  ui_story_5051_50511002_134_dialog_content = "如果真是這樣，那是我招待不周了。",
  ui_story_5051_50511002_135_dialog_content = "只是……",
  ui_story_5051_50511002_136_dialog_content = "還是不相信我？",
  ui_story_5051_50511002_137_dialog_content = "PlayerName的年齡看起來沒大薇羅妮卡多少歲。",
  ui_story_5051_50511002_138_dialog_content = "我還以為，你會是PlayerName的爺爺。",
  ui_story_5051_50511002_139_dialog_content = "哈哈哈……年輕人就是年輕人。",
  ui_story_5051_50511002_140_dialog_content = "謝謝你讓我意識到，我年輕的時候原來真的有點惹人厭。",
  ui_story_5051_50511002_141_dialog_content = "可以想像。",
  ui_story_5051_50511002_142_dialog_content = "還好，等你到我這個年紀，就不會想去計較這些了。",
  ui_story_5051_50511002_143_dialog_content = "沒猜錯的話，您應該還有其他更重要的事要處理吧？",
  ui_story_5051_50511002_144_dialog_content = "那又如何？",
  ui_story_5051_50511002_145_dialog_content = "別看我髮鬚盡白，在對付暗鬼方面也頗有心得。",
  ui_story_5051_50511002_146_dialog_content = "我願意帶著薇羅妮卡和PlayerName去安全的地方避難。",
  ui_story_5051_50511002_147_dialog_content = "謝謝你的好意，我心領了。",
  ui_story_5051_50511002_148_dialog_content = "不過，薇羅妮卡是我的女兒。",
  ui_story_5051_50511002_149_dialog_content = "我的女兒，我自己會保護。",
  ui_story_5051_50511002_150_dialog_content = "用不著其他人來插手。",
  ui_story_5051_50511002_151_dialog_content = "……",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>父親</color>……",
  ui_story_5051_50511002_153_dialog_content = "（此刻的蜜雅……）",
  ui_story_5051_50511002_154_dialog_content = "（究竟是在對誰喊「<color=#FFB400>父親</color>」呢？）",
  ui_story_5051_50511101_1_dialog_content = "小占卜球的反應越來越強烈了。",
  ui_story_5051_50511101_2_dialog_content = "PlayerName他們一定就在這附近！",
  ui_story_5051_50511101_3_dialog_content = "好安靜。",
  ui_story_5051_50511101_4_dialog_content = "真的耶……這裡完全不像來的路上那麼「熱鬧」。",
  ui_story_5051_50511101_5_dialog_content = "我們還是去熱鬧的地方玩吧！",
  ui_story_5051_50511101_6_dialog_content = "這附近也太冷清了。",
  ui_story_5051_50511101_7_dialog_content = "一看就沒什麼賣好酒的店嘛～",
  ui_story_5051_50511101_8_dialog_content = "咳咳，我們也不是來逛街的啦。",
  ui_story_5051_50511101_9_dialog_content = "還沒拜師成功，就想糊弄我嗎？",
  ui_story_5051_50511101_10_dialog_content = "剛才那群穿黑禮服的人一直吵吵鬧鬧，不就是想拉客嘛。",
  ui_story_5051_50511101_11_dialog_content = "「穿黑禮服的人」？該不會是說暗鬼吧？！",
  ui_story_5051_50511101_12_dialog_content = "原來妳已經醉到連暗鬼都分不清楚了嗎？",
  ui_story_5051_50511101_13_dialog_content = "<size=30>怪不得連我都沒認出來……</size>",
  ui_story_5051_50511101_14_dialog_content = "大致檢查了一下，這附近的暗鬼似乎都已經消滅乾淨了。",
  ui_story_5051_50511101_15_dialog_content = "城主大人和公主殿下所在的地方警備比較充足。",
  ui_story_5051_50511101_16_dialog_content = "妳的朋友和城主大人、公主殿下在一起，一定不會有事。",
  ui_story_5051_50511101_17_dialog_content = "謝謝你喔，小騎士。",
  ui_story_5051_50511101_18_dialog_content = "要不是你剛才一刀一個解決掉那些暗鬼，天曉得我什麼時候才能走到這裡呢。",
  ui_story_5051_50511101_19_dialog_content = "你真是我在白夜城見過最可靠的騎士啦！",
  ui_story_5051_50511101_20_dialog_content = "不必靠我的小占卜球，我都能看出來……",
  ui_story_5051_50511101_21_dialog_content = "你以後一定會成為一位叱吒風雲的大人物！",
  ui_story_5051_50511101_22_dialog_content = "過獎了。",
  ui_story_5051_50511101_23_dialog_content = "我現在只不過是一名預備騎士。",
  ui_story_5051_50511101_24_dialog_content = "妳能相信我，就是對我最大的鼓勵。",
  ui_story_5051_50511101_25_dialog_content = "沒關係呀，你現在還年輕嘛！以後一定有機會……",
  ui_story_5051_50511101_26_dialog_content = "咦，等等！",
  ui_story_5051_50511101_27_dialog_content = "（「永憶鏡晶」裡記錄的是十二年前發生過的事情。）",
  ui_story_5051_50511101_28_dialog_content = "（也就是說，這位看起來年紀輕輕的騎士，在現實中其實比我還大很多嗎？！）",
  ui_story_5051_50511101_29_dialog_content = "咳咳，小騎士，你今年……幾歲？",
  ui_story_5051_50511101_30_dialog_content = "妳這丫頭，剛才想認我當師父的時候倒是很有氣勢。",
  ui_story_5051_50511101_31_dialog_content = "怎麼現在忽然變得扭扭捏捏的？",
  ui_story_5051_50511101_32_dialog_content = "喜歡就大膽說出來嘛！",
  ui_story_5051_50511101_33_dialog_content = "咦，我、我不是那個意思啦！",
  ui_story_5051_50511101_34_dialog_content = "呃？",
  ui_story_5051_50511101_35_dialog_content = "當然啦，我也不是討厭小騎士的意思！",
  ui_story_5051_50511101_36_dialog_content = "就是那個，哎呀，我也說不清楚。",
  ui_story_5051_50511101_37_dialog_content = "不過，如果你十二年後還在白夜城當騎士的話……",
  ui_story_5051_50511101_38_dialog_content = "我們一定還會再見喔～",
  ui_story_5051_50511101_39_dialog_content = "又是那種「多少年以後我會去找妳，要等我回來」的戲碼嗎？",
  ui_story_5051_50511101_40_dialog_content = "這種套路從我八歲就已經過時了，能不能來點新意呀？",
  ui_story_5051_50511101_41_dialog_content = "呃哈哈哈……",
  ui_story_5051_50511101_42_dialog_content = "這位醉酒的女士是在胡言亂語啦，小騎士，你千萬別放心上喔！",
  ui_story_5051_50511101_43_dialog_content = "一言為定！",
  ui_story_5051_50511101_44_dialog_content = "咦？",
  ui_story_5051_50511101_45_dialog_content = "雖然我的族人因為種種顧慮，並不看好我。",
  ui_story_5051_50511101_46_dialog_content = "但是如果沒有他們輪流養育我，我不可能有今天。",
  ui_story_5051_50511101_47_dialog_content = "我希望，有一天能向族人證明我的價值，重寫卡爾帝瑪家族的榮耀。",
  ui_story_5051_50511101_48_dialog_content = "十二年以後嗎……",
  ui_story_5051_50511101_49_dialog_content = "等妳再來見我的時候，我一定會成為統御千軍萬馬的最強騎士！",
  ui_story_5051_50511101_50_dialog_content = "哇，聽起來好威風耶！",
  ui_story_5051_50511101_51_dialog_content = "那就這麼定囉！我一定會去騎士團找你的！",
  ui_story_5051_50511101_52_dialog_content = "啊不過，我好像還不知道你的名字呢。",
  ui_story_5051_50511101_53_dialog_content = "「希羅娜·卡爾帝瑪」。",
  ui_story_5051_50511101_54_dialog_content = "「希羅娜」，這個名字好可愛呀。",
  ui_story_5051_50511101_55_dialog_content = "等等……",
  ui_story_5051_50511101_56_dialog_content = "原來妳是女孩子啊？！",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>街道的另一邊</color>",
  ui_story_5051_50511101_58_dialog_content = "年輕人，不要太過急躁。",
  ui_story_5051_50511101_59_dialog_content = "我明白你的處境，也明白你的心情。",
  ui_story_5051_50511101_60_dialog_content = "我活了很久才明白「以柔制剛」這個道理。",
  ui_story_5051_50511101_61_dialog_content = "希望你能好好想想，不要讓家人也牽扯進別的事情。",
  ui_story_5051_50511101_62_dialog_content = "有機會的話，我一定要把你介紹給元老院的諸位。",
  ui_story_5051_50511101_63_dialog_content = "你們應該會有很多共同話題，而且也都喜歡當「年輕人」的老師。",
  ui_story_5051_50511101_64_dialog_content = "……你這樣覺得嗎？",
  ui_story_5051_50511101_65_dialog_content = "原來如此，我竟然忘了……",
  ui_story_5051_50511101_66_dialog_content = "年輕時，我最厭煩的就是「自以為是」的說教。",
  ui_story_5051_50511101_67_dialog_content = "<size=45>嗚哇——！</size>",
  ui_story_5051_50511101_68_dialog_content = "嗯？",
  ui_story_5051_50511101_69_dialog_content = "終於找到大家啦！大家都還好嗎？",
  ui_story_5051_50511101_70_dialog_content = "四肢健全、表情鮮活，看來大家都沒事！太好啦，太好啦。",
  ui_story_5051_50511101_71_dialog_content = "加晴……",
  ui_story_5051_50511101_72_dialog_content = "PlayerName，不用擔心我！你看，我不是好好的嘛～",
  ui_story_5051_50511101_73_dialog_content = "既然這樣，我們還是別在這裡呆站著了。",
  ui_story_5051_50511101_74_dialog_content = "咳咳，因為一些特殊的原因……",
  ui_story_5051_50511101_75_dialog_content = "我們必須要在「今天內」離開這個地方！",
  ui_story_5051_50511101_76_dialog_content = "噓……",
  ui_story_5051_50511101_77_dialog_content = "咦，PlayerName有什麼問題嗎？",
  ui_story_5051_50511101_78_dialog_content = "啊～你是想問我身邊這位醉醺醺的女士是誰嗎？",
  ui_story_5051_50511101_79_dialog_content = "這個說起來有點複雜……不過我可以介紹一下旁邊那位幫助我們的騎士！",
  ui_story_5051_50511101_80_dialog_content = "嗯？人呢？",
  ui_story_5051_50511101_81_dialog_content = "發現我找到朋友，她就悄悄地離開了嗎？",
  ui_story_5051_50511101_82_dialog_content = "真是的，白夜城的人都不喜歡好好說聲再見嘛～？",
  ui_story_5051_50511101_83_dialog_content = "喂，丫頭，這就是妳要找的人嗎？",
  ui_story_5051_50511101_84_dialog_content = "怎麼看起來有點眼熟啊？",
  ui_story_5051_50511101_85_dialog_content = "博阿姿？昨夜並沒有啟程返回北境嗎？",
  ui_story_5051_50511101_86_dialog_content = "難得來一趟白夜城，嗝～我也想放鬆一下。",
  ui_story_5051_50511101_87_dialog_content = "喔～我想起來了，你就是昨天那個……",
  ui_story_5051_50511101_88_dialog_content = "那個城主大人嘛！",
  ui_story_5051_50511101_89_dialog_content = "（咦？這、這是……這裡的城主大人？）",
  ui_story_5051_50511101_90_dialog_content = "（難怪剛才PlayerName一直在對我使眼色……）",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName，過來過來！</size>",
  ui_story_5051_50511101_92_dialog_content = "慢點，不要一直拉我啊……",
  ui_story_5051_50511101_93_dialog_content = "喂，現在是什麼情況啊？",
  ui_story_5051_50511101_94_dialog_content = "我也很想搞清楚現在的情況，但是似乎因為妳的出現變得更加複雜了……",
  ui_story_5051_50511101_95_dialog_content = "世界上哪有複雜的事？是不是你自己想得太複雜了？",
  ui_story_5051_50511101_96_dialog_content = "總而言之，城主大人剛才發現了城主大人，以為城主大人是綁架犯……",
  ui_story_5051_50511101_97_dialog_content = "我怎麼越聽越糊塗了？",
  ui_story_5051_50511101_98_dialog_content = "所以才說情況很複雜……",
  ui_story_5051_50511101_99_dialog_content = "重點是，我們要怎麼區分這兩個城主大人啊？",
  ui_story_5051_50511101_100_dialog_content = "剛才我告訴他們，跟我們一起進入這裡的城主大人叫「臨空」，是我的父親……",
  ui_story_5051_50511101_101_dialog_content = "「臨空」？這是PlayerName巨像的名字吧？",
  ui_story_5051_50511101_102_dialog_content = "情況緊急，我一時想不到別的假名……",
  ui_story_5051_50511101_103_dialog_content = "一個是老舒瓦茲，一個是小舒瓦茲，這樣區分他們是不是比較簡單呀？",
  ui_story_5051_50511101_104_dialog_content = "雖然有點對不起城主大人，但是為了方便理解……",
  ui_story_5051_50511101_105_dialog_content = "剛才老舒瓦茲想要帶走蜜雅，結果被小舒瓦茲誤以為要綁架她。",
  ui_story_5051_50511101_106_dialog_content = "現在我們正在想辦法脫身！",
  ui_story_5051_50511101_107_dialog_content = "哈～這樣講我就懂了！",
  ui_story_5051_50511101_108_dialog_content = "看我的！",
  ui_story_5051_50511101_109_dialog_content = "……沒事，我真～的沒有喝醉！",
  ui_story_5051_50511101_110_dialog_content = "好，那可以介紹一下妳身邊的這位是誰嗎？",
  ui_story_5051_50511101_111_dialog_content = "我自己來介紹～！我啊，就是博阿姿的徒弟，嘿嘿嘿。",
  ui_story_5051_50511101_112_dialog_content = "我並不知道女王陛下這次派了兩位使者前來。",
  ui_story_5051_50511101_113_dialog_content = "城主大人當然不知道啦，因為使者確實只有一位。",
  ui_story_5051_50511101_114_dialog_content = "我只是個小跟班嘛～不過小跟班也有任務喔！",
  ui_story_5051_50511101_115_dialog_content = "我的任務和博阿姿不同，所以就沒有去見您和城主夫人。",
  ui_story_5051_50511101_116_dialog_content = "喔？妳的任務是什麼？",
  ui_story_5051_50511101_117_dialog_content = "邀請PlayerName前往北境，去參加女王陛下舉辦的宴會。",
  ui_story_5051_50511101_118_dialog_content = "啊？！",
  ui_story_5051_50511101_119_dialog_content = "看樣子PlayerName並不知情。",
  ui_story_5051_50511101_120_dialog_content = "咳咳，他當然不知道啦。畢竟我才剛找到他嘛～",
  ui_story_5051_50511101_121_dialog_content = "PlayerName，怎麼樣？你想去嗎？",
  ui_story_5051_50511101_122_dialog_content = "<size=30>咳、快答應呀！</size>",
  ui_story_5051_50511101_123_dialog_content = "啊？喔……",
  ui_story_5051_50511101_124_dialog_content = "女王陛下的邀請，我當然不會拒絕！",
  ui_story_5051_50511101_125_dialog_content = "喔，這樣嗎？那真是再好不過啦～",
  ui_story_5051_50511101_126_dialog_content = "師父的任務完成了，我的任務也完成了。",
  ui_story_5051_50511101_127_dialog_content = "那我們可以高高興興地一起回北境啦～",
  ui_story_5051_50511101_128_dialog_content = "（加晴真是個天才！）",
  ui_story_5051_50511101_129_dialog_content = "（這樣一來，小舒瓦茲一定會放我們走了吧。）",
  ui_story_5051_50511101_130_dialog_content = "……",
  ui_story_5051_50511101_131_dialog_content = "（可是，為何老舒瓦茲並沒有一絲鬆懈？）",
  ui_story_5051_50511101_132_dialog_content = "（我跟加晴還是把事情想得太簡單了嗎？）",
  ui_story_5051_50511101_133_dialog_content = "原來是這樣。",
  ui_story_5051_50511101_134_dialog_content = "（是錯覺嗎？為什麼小舒瓦茲似乎輕輕笑了一聲……）",
  ui_story_5051_50511101_135_dialog_content = "我向來尊敬北境的女王陛下，既然是她的客人，便也是我的客人。",
  ui_story_5051_50511101_136_dialog_content = "非常抱歉讓諸位看到白夜城如此混亂的一面。",
  ui_story_5051_50511101_137_dialog_content = "但我保證不會讓這種混亂的局面持續太久。",
  ui_story_5051_50511101_138_dialog_content = "接下來，還請諸位跟在我身後。",
  ui_story_5051_50511101_139_dialog_content = "我會保護諸位的人身安全！",
  ui_story_5051_50511101_140_dialog_content = "<size=30>態度跟剛才完全不同了……？</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>如果有送上來的棋子，PlayerName，你會不用嗎？</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>棋子？</size>",
  ui_story_5051_50511101_143_dialog_content = "（什麼意思？我們都變成了小舒瓦茲的棋子？）",
  ui_story_5051_50511101_144_dialog_content = "（但憑我們幾個，又對他有什麼好處呢？）",
  ui_story_5051_50511101_145_dialog_content = "（而且……老舒瓦茲之所以這麼說，）",
  ui_story_5051_50511101_146_dialog_content = "（是因為曾經的他……就是這樣把別人當作棋子嗎？）",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName，下棋並不是放鬆休閒的遊戲，現在你應該明白了。</size>",
  ui_story_5051_50511101_148_dialog_content = "父親！",
  ui_story_5051_50511101_149_dialog_content = "這個聲音……",
  ui_story_5051_50511101_150_dialog_content = "父親！！",
  ui_story_5051_50511101_151_dialog_content = "卡……",
  ui_story_5051_50511101_152_dialog_content = "卡蓮，妳怎麼在這裡？",
  ui_story_5051_50511101_153_dialog_content = "是我帶她找過來的。",
  ui_story_5051_50511101_154_dialog_content = "……",
  ui_story_5051_50511101_155_dialog_content = "妳們怎麼回來了？第二批暗鬼已經解決完了嗎？",
  ui_story_5051_50511101_156_dialog_content = "「第二批暗鬼」？",
  ui_story_5051_50511101_157_dialog_content = "喔……我是在擔心，也許其它地方還會出現更多暗鬼。",
  ui_story_5051_50511101_158_dialog_content = "雖然無法確定，但現在還不能掉以輕心。",
  ui_story_5051_50511101_159_dialog_content = "紅女士呢？我請她隨妳們一同撤離，她為何擅離職守？",
  ui_story_5051_50511101_160_dialog_content = "紅女士並沒有擅離職守，比起護送我，附近民眾更需要她的幫助。",
  ui_story_5051_50511101_161_dialog_content = "約書亞，妳真是亂來……",
  ui_story_5051_50511101_162_dialog_content = "狄安理，你又不是第一天認識我了。",
  ui_story_5051_50511101_163_dialog_content = "什麼時候你才能想起來，我的劍術並不比你遜色呢？",
  ui_story_5051_50511101_164_dialog_content = "你這裡似乎有很多需要幫助的朋友……",
  ui_story_5051_50511101_165_dialog_content = "讓我替你分擔一些吧，狄安理。",
  ui_story_5051_50511101_166_dialog_content = "約書亞！",
  ui_story_5051_50511101_167_dialog_content = "咳咳咳咳咳……",
  ui_story_5051_50511101_168_dialog_content = "嗯？這位先生沒事吧？",
  ui_story_5051_50511101_169_dialog_content = "您看起來……似乎有點面熟？",
  ui_story_5051_50511101_170_dialog_content = "是嗎？我們第一次見面的時候，妳也是這麼說的。",
  ui_story_5051_50511101_171_dialog_content = "我們……曾經在哪裡見過嗎？",
  ui_story_5051_50511101_172_dialog_content = "（剛才是誰警告我不要和這個世界產生糾葛的……）",
  ui_story_5051_50511101_173_dialog_content = "咳咳，原來父親以前認識城主夫人嗎？",
  ui_story_5051_50511101_174_dialog_content = "……抱歉，我好像認錯人了。",
  ui_story_5051_50511101_175_dialog_content = "原來是PlayerName的父親，難怪會覺得有些眼熟呢～",
  ui_story_5051_50511101_176_dialog_content = "呀——！",
  ui_story_5051_50511101_177_dialog_content = "暗鬼……怎麼又來了這麼多暗鬼！",
  ui_story_5051_50511101_178_dialog_content = "城主大人剛才的推測好厲害，果然出現了第二批暗鬼？！",
  ui_story_5051_50511101_179_dialog_content = "難道他也會占卜嗎？比我更厲害的那種占卜？！",
  ui_story_5051_50511101_180_dialog_content = "……",
  ui_story_5051_50511101_181_dialog_content = "狄安理！",
  ui_story_5051_50511101_182_dialog_content = "大家小心四周，提防暗鬼！",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>咚咚咚咚！</color>",
  ui_story_5051_50511101_184_dialog_content = "這整齊劃一的腳步聲……",
  ui_story_5051_50511101_185_dialog_content = "應該不是暗鬼才對！",
  ui_story_5051_50511101_186_dialog_content = "太好了！",
  ui_story_5051_50511101_187_dialog_content = "是來支援的衛兵！",
  ui_story_5051_50511101_188_dialog_content = "等一下。",
  ui_story_5051_50511101_189_dialog_content = "這些衛兵，似乎並不是來支援我們的。",
  ui_story_5051_50511101_190_dialog_content = "欸？",
  ui_story_5051_50511101_191_dialog_content = "衝！",
  ui_story_5051_50511101_192_dialog_content = "哇呀——！",
  ui_story_5051_50511101_193_dialog_content = "他們為什麼要把武器對準我們啊？！",
  ui_story_5051_50511102_1_dialog_content = "加晴，小心妳的左後方！",
  ui_story_5051_50511102_2_dialog_content = "別過來呀！",
  ui_story_5051_50511102_3_dialog_content = "呃啊……",
  ui_story_5051_50511102_4_dialog_content = "咦？PlayerName，是你救了我？",
  ui_story_5051_50511102_5_dialog_content = "不、不是呀？",
  ui_story_5051_50511102_6_dialog_content = "喂喂喂，你們這些成精的笨石頭！走路給我看路啊！",
  ui_story_5051_50511102_7_dialog_content = "要是我徒弟受傷了，誰要買酒給我喝！",
  ui_story_5051_50511102_8_dialog_content = "……我印象裡強大、無畏的那個博阿姿終於回來啦！",
  ui_story_5051_50511102_9_dialog_content = "頭好暈，剛才用力過猛了嗎？",
  ui_story_5051_50511102_10_dialog_content = "丫頭，後面就交給妳了，我不行了……",
  ui_story_5051_50511102_11_dialog_content = "不——！我還來不及和妳好好「敘舊」啊！",
  ui_story_5051_50511102_12_dialog_content = "……真是的，在這種時候還能睡著？我要收回剛才的話！",
  ui_story_5051_50511102_13_dialog_content = "PlayerName，你帶著加晴跟蜜雅從右邊的缺口突圍出去，我來掩護你們！",
  ui_story_5051_50511102_14_dialog_content = "我們要丟下其他人……逃跑嗎？",
  ui_story_5051_50511102_15_dialog_content = "來不及了，<color=#FFB400>叛亂</color>已經發生，在這裡多待一秒都危險至極！",
  ui_story_5051_50511102_16_dialog_content = "叛亂……嗎？",
  ui_story_5051_50511102_17_dialog_content = "我、我為什麼想起不起來……那時的我知道這件事嗎？",
  ui_story_5051_50511102_18_dialog_content = "蜜雅，不要勉強自己去回想了！",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>嗖——！</color>",
  ui_story_5051_50511102_20_dialog_content = "什麼人？",
  ui_story_5051_50511102_21_dialog_content = "好像是從空中飛下來的？感覺像是衝著某個目標來的？",
  ui_story_5051_50511102_22_dialog_content = "目標難道是<color=#FFB400>小舒瓦茲</color>？！",
  ui_story_5051_50511102_23_dialog_content = "小舒瓦茲被敵人包圍，似乎沒有注意到頭上的危險？",
  ui_story_5051_50511102_24_dialog_content = "怎麼會……就算是現在的城主，也應該注意得到才對啊！",
  ui_story_5051_50511102_25_dialog_content = "……",
  ui_story_5051_50511102_26_dialog_content = "狄安理，小心！！！",
  ui_story_5051_50511102_27_dialog_content = "喝啊——！",
  ui_story_5051_50511102_28_dialog_content = "呃……",
  ui_story_5051_50511102_29_dialog_content = "哇啊啊啊，看起來好痛啊！",
  ui_story_5051_50511102_30_dialog_content = "肩膀被刺傷了嗎？",
  ui_story_5051_50511102_31_dialog_content = "趁注意力都被吸引到另一邊，我們快走！",
  ui_story_5051_50511102_32_dialog_content = "可、可是……",
  ui_story_5051_50511102_33_dialog_content = "父親！",
  ui_story_5051_50511102_34_dialog_content = "卡蓮要去幫父親！",
  ui_story_5051_50511102_35_dialog_content = "是嗎？",
  ui_story_5051_50511102_36_dialog_content = "「卡蓮」……",
  ui_story_5051_50511102_37_dialog_content = "糟糕，躲在一旁的小卡蓮被反叛軍發現了！",
  ui_story_5051_50511102_38_dialog_content = "……什麼？",
  ui_story_5051_50511102_39_dialog_content = "你、你也是壞蛋嗎？",
  ui_story_5051_50511102_40_dialog_content = "小公主，妳好啊。",
  ui_story_5051_50511102_41_dialog_content = "別、別以為卡蓮會怕你！",
  ui_story_5051_50511102_42_dialog_content = "我的劍術很厲害！已經贏過很多衛兵！",
  ui_story_5051_50511102_43_dialog_content = "可惜，我不像那些衛兵一樣會對妳手下留情。",
  ui_story_5051_50511102_44_dialog_content = "哇啊……",
  ui_story_5051_50511102_45_dialog_content = "哈哈哈，我都還沒出全力呢，妳怎麼就跌倒了？",
  ui_story_5051_50511102_46_dialog_content = "別白費力氣爬起來了，反正妳還會再摔倒的。",
  ui_story_5051_50511102_47_dialog_content = "啊——！",
  ui_story_5051_50511102_48_dialog_content = "主宰之刃！",
  ui_story_5051_50511102_49_dialog_content = "怎麼……會……",
  ui_story_5051_50511102_50_dialog_content = "（老舒瓦茲嘴上說要我們快跑，結果還是忍不住保護了卡蓮？）",
  ui_story_5051_50511102_51_dialog_content = "卡蓮……得救了？父親，是父親嗎……",
  ui_story_5051_50511102_52_dialog_content = "……",
  ui_story_5051_50511102_53_dialog_content = "卡蓮！！！",
  ui_story_5051_50511102_54_dialog_content = "讓我看看，有沒有哪裡受傷？",
  ui_story_5051_50511102_55_dialog_content = "母親，別擔心，卡蓮……沒有受傷。",
  ui_story_5051_50511102_56_dialog_content = "這孩子，到這種時候還是這麼嘴硬……",
  ui_story_5051_50511102_57_dialog_content = "……她應該只是受到驚嚇而已。",
  ui_story_5051_50511102_58_dialog_content = "PlayerName的父親，多謝您救了卡蓮一命！",
  ui_story_5051_50511102_59_dialog_content = "不必謝我。這是……應該的。",
  ui_story_5051_50511102_60_dialog_content = "我可憐的小卡蓮。",
  ui_story_5051_50511102_61_dialog_content = "母親，父親咳咳……父親他怎麼樣了？",
  ui_story_5051_50511102_62_dialog_content = "妳父親他……",
  ui_story_5051_50511102_63_dialog_content = "不用擔心，妳父親馬上就能抓住壞蛋了。",
  ui_story_5051_50511102_64_dialog_content = "母親，妳快去幫父親吧，卡蓮沒事……沒事的！",
  ui_story_5051_50511102_65_dialog_content = "傻孩子。",
  ui_story_5051_50511102_66_dialog_content = "喝啊！",
  ui_story_5051_50511102_67_dialog_content = "咳……",
  ui_story_5051_50511102_68_dialog_content = "狄安理！",
  ui_story_5051_50511102_69_dialog_content = "不必擔心，他一個人足夠應付刺客了。",
  ui_story_5051_50511102_70_dialog_content = "可是他已經受傷了，我擔心……",
  ui_story_5051_50511102_71_dialog_content = "那麼，我去幫「妳的丈夫」，妳留在此處。",
  ui_story_5051_50511102_72_dialog_content = "咦？您不必冒著生命危險去做這件事！",
  ui_story_5051_50511102_73_dialog_content = "看得出來那些反叛軍的目標並不是你們，而是我和我的家人。",
  ui_story_5051_50511102_74_dialog_content = "這種情況下，我們無須再分你我。",
  ui_story_5051_50511102_75_dialog_content = "等著。",
  ui_story_5051_50511102_76_dialog_content = "PlayerName，你和加晴、蜜雅也留在這裡。",
  ui_story_5051_50511102_77_dialog_content = "我馬上回來。",
  ui_story_5051_50511102_78_dialog_content = "等一下！",
  ui_story_5051_50511102_79_dialog_content = "我、我也想去。",
  ui_story_5051_50511102_80_dialog_content = "……",
  ui_story_5051_50511102_81_dialog_content = "妳從左路，我從右路，出發！",
  ui_story_5051_50511102_82_dialog_content = "……好、好的！",
  ui_story_5051_50511102_83_dialog_content = "是錯覺嗎？",
  ui_story_5051_50511102_84_dialog_content = "居然從PlayerName的父親身上，看到了狄安理的影子……",
  ui_story_5051_50511102_85_dialog_content = "呃……",
  ui_story_5051_50511102_86_dialog_content = "我等你很久了。",
  ui_story_5051_50511102_87_dialog_content = "什麼？",
  ui_story_5051_50511102_88_dialog_content = "呵，這點傷比我想像中輕太多了。",
  ui_story_5051_50511102_89_dialog_content = "……你早就料到了。",
  ui_story_5051_50511102_90_dialog_content = "少廢話，速戰速決。",
  ui_story_5051_50511102_91_dialog_content = "我、我也來幫忙！",
  ui_story_5051_50511102_92_dialog_content = "撤退！！！",
  ui_story_5051_50511102_93_dialog_content = "所有人，快撤退！",
  ui_story_5051_50511102_94_dialog_content = "謝謝你們給我這個機會……",
  ui_story_5051_50511102_95_dialog_content = "光之所至，萬物皆明！",
  ui_story_5051_50511102_96_dialog_content = "呃啊！",
  ui_story_5051_50511102_97_dialog_content = "我說過……",
  ui_story_5051_50511102_98_dialog_content = "身為一城之主，我不會只是個擺設。",
  ui_story_5051_50511201_1_dialog_content = "呼……呼……呼……",
  ui_story_5051_50511201_2_dialog_content = "舅父大人，您還好嗎？",
  ui_story_5051_50511201_3_dialog_content = "希羅娜？！",
  ui_story_5051_50511201_4_dialog_content = "我不是要妳回家休息半天嗎？妳怎麼在這裡？",
  ui_story_5051_50511201_5_dialog_content = "早晨我們答應替薇羅妮卡公主的朋友找人，我想或許我可以幫忙……",
  ui_story_5051_50511201_6_dialog_content = "沒能聽從舅父大人的安排，這件事是希羅娜的不對。",
  ui_story_5051_50511201_7_dialog_content = "但現在城中忽然出現暗鬼，身為一名預備騎士，我理應站出來守護大家！",
  ui_story_5051_50511201_8_dialog_content = "而且，我也擔心在城中巡邏的卡爾帝瑪家族成員……還有您。",
  ui_story_5051_50511201_9_dialog_content = "也罷。",
  ui_story_5051_50511201_10_dialog_content = "妳現在馬上回家，帶著妳的舅母還有弟妹們離開白夜城！",
  ui_story_5051_50511201_11_dialog_content = "就用我停在後花園的那架飛空艇。",
  ui_story_5051_50511201_12_dialog_content = "舅父大人，為、為什麼？",
  ui_story_5051_50511201_13_dialog_content = "別問為什麼，妳照做就對了！",
  ui_story_5051_50511201_14_dialog_content = "舅父大人，您看這條街上的暗鬼，牠們好像並不會主動攻擊我和您。",
  ui_story_5051_50511201_15_dialog_content = "我們卡爾帝瑪家族的血脈，說不定就是暗鬼的剋星。",
  ui_story_5051_50511201_16_dialog_content = "如果這一次，我們舉家族之力為白夜城驅除這些暗鬼……",
  ui_story_5051_50511201_17_dialog_content = "我們一定會得到城主大人的重視，重新找回卡爾帝瑪家族的榮耀！",
  ui_story_5051_50511201_18_dialog_content = "這種時候，您為什麼還要我帶著家人逃跑……",
  ui_story_5051_50511201_19_dialog_content = "妳提醒了我，你們離開白夜城之後，也許還會遇到其他暗鬼……",
  ui_story_5051_50511201_20_dialog_content = "我的書房裡放著一把卡爾帝瑪家族世代傳承下來的太刀，名叫「火藍」。",
  ui_story_5051_50511201_21_dialog_content = "妳記得帶著它一起離開！",
  ui_story_5051_50511201_22_dialog_content = "舅父大人，我不明白……",
  ui_story_5051_50511201_23_dialog_content = "也許那個預言是對的，只是我從來都不願相信。",
  ui_story_5051_50511201_24_dialog_content = "能夠拯救卡爾帝瑪家族的人是妳……",
  ui_story_5051_50511201_25_dialog_content = "而不是我。",
  ui_story_5051_50511201_26_dialog_content = "……",
  ui_story_5051_50511201_27_dialog_content = "這些事，和當年是一樣的嗎？",
  ui_story_5051_50511201_28_dialog_content = "相差無幾。",
  ui_story_5051_50511201_29_dialog_content = "只是當年，卡蓮的傷要稍微嚴重一點，我也沒能在現場保護她。",
  ui_story_5051_50511201_30_dialog_content = "所以您聽到小卡蓮的聲音之後，才會忍不住趕過去。",
  ui_story_5051_50511201_31_dialog_content = "您是想要彌補當年的遺憾嗎？",
  ui_story_5051_50511201_32_dialog_content = "如果說我不遺憾，那一定是謊言。",
  ui_story_5051_50511201_33_dialog_content = "卡蓮怎麼樣了？",
  ui_story_5051_50511201_34_dialog_content = "傷得不重，只是手腳都破皮了。",
  ui_story_5051_50511201_35_dialog_content = "倒是你，肩膀不是都流血了？",
  ui_story_5051_50511201_36_dialog_content = "這點小傷，和蚊子咬沒什麼區別。",
  ui_story_5051_50511201_37_dialog_content = "我們好久沒有一起練習劍術了。",
  ui_story_5051_50511201_38_dialog_content = "要是從前，你一定不會被那種程度的偷襲刺傷……",
  ui_story_5051_50511201_39_dialog_content = "事發突然，我剛才可能也有些亂了陣腳。",
  ui_story_5051_50511201_40_dialog_content = "在慶祝「舒瓦茲家族日」這一天，先是安排暗鬼襲城，又是派出私兵趁亂刺殺……",
  ui_story_5051_50511201_41_dialog_content = "是什麼人對我們有這麼大的仇恨？",
  ui_story_5051_50511201_42_dialog_content = "城主殿下、城主夫人。",
  ui_story_5051_50511201_43_dialog_content = "請原諒我和我的小隊來得太晚。",
  ui_story_5051_50511201_44_dialog_content = "讓小公主和城主殿下受傷，是我們的失職……",
  ui_story_5051_50511201_45_dialog_content = "紅女士，這不能怪妳。",
  ui_story_5051_50511201_46_dialog_content = "妳保護了附近民眾的安全，這才是妳們該做的。",
  ui_story_5051_50511201_47_dialog_content = "謝謝您，城主夫人。",
  ui_story_5051_50511201_48_dialog_content = "還有其他事嗎？",
  ui_story_5051_50511201_49_dialog_content = "有的，城主殿下。",
  ui_story_5051_50511201_50_dialog_content = "我們剛才在附近進行地毯式搜查，活捉了幾名反叛軍的成員。",
  ui_story_5051_50511201_51_dialog_content = "嗯，有什麼發現，說吧。",
  ui_story_5051_50511201_52_dialog_content = "我們從他們身上搜出印有特殊紋章的武器。",
  ui_story_5051_50511201_53_dialog_content = "經過比對，證實那種特殊紋章是卡爾帝瑪家族的標誌。",
  ui_story_5051_50511201_54_dialog_content = "卡爾帝瑪家族？",
  ui_story_5051_50511201_55_dialog_content = "我不久前還和邁木的夫人在晚宴上相談甚歡。",
  ui_story_5051_50511201_56_dialog_content = "她的兒女和卡蓮差不多大……",
  ui_story_5051_50511201_57_dialog_content = "不對……這太奇怪了。",
  ui_story_5051_50511201_58_dialog_content = "那些人怎麼會攜帶這麼容易暴露身分的武器？",
  ui_story_5051_50511201_59_dialog_content = "自大的人往往都很天真。",
  ui_story_5051_50511201_60_dialog_content = "他們一定以為能在今天解決掉我，終結「舒瓦茲家族」的統治。",
  ui_story_5051_50511201_61_dialog_content = "紅女士。",
  ui_story_5051_50511201_62_dialog_content = "聽憑吩咐，城主殿下。",
  ui_story_5051_50511201_63_dialog_content = "通知審判庭，卡爾帝瑪家族成員圖謀造反，證據確鑿。",
  ui_story_5051_50511201_64_dialog_content = "即刻發布通緝，追捕卡爾帝瑪家族的<color=#FFB400>所有成員</color>。",
  ui_story_5051_50511201_65_dialog_content = "請審判庭緊急起草通緝令，並協助我們實施追捕程序。",
  ui_story_5051_50511201_66_dialog_content = "如遇抵抗，當場處決。",
  ui_story_5051_50511201_67_dialog_content = "好的，城主殿下。",
  ui_story_5051_50511201_68_dialog_content = "「卡爾帝瑪家族的所有成員」？狄安理，你這是……？",
  ui_story_5051_50511201_69_dialog_content = "今年已經發生過太多這種事情。",
  ui_story_5051_50511201_70_dialog_content = "皮洛斯家族和戈蒂埃家族的那麼多亡魂，還不夠嗎？",
  ui_story_5051_50511201_71_dialog_content = "約書亞……",
  ui_story_5051_50511201_72_dialog_content = "卡蓮需要休息，妳先帶她回家吧。",
  ui_story_5051_50511201_73_dialog_content = "……",
  ui_story_5051_50511201_74_dialog_content = "正好，約書亞……夫人，我也想帶著孩子離開。",
  ui_story_5051_50511201_75_dialog_content = "我來送你們回去吧。",
  ui_story_5051_50511201_76_dialog_content = "謝謝您的好意。",
  ui_story_5051_50511201_77_dialog_content = "既然城內的暗鬼已悉數殲滅，我想我可以自己帶著孩子回去。",
  ui_story_5051_50511201_78_dialog_content = "臨空先生……沒記錯的話，你是叫「臨空」沒錯吧？",
  ui_story_5051_50511201_79_dialog_content = "嗯。",
  ui_story_5051_50511201_80_dialog_content = "我很抱歉之前對你有疑慮。",
  ui_story_5051_50511201_81_dialog_content = "你對付暗鬼的能力，的確如你所說，頗富實力。",
  ui_story_5051_50511201_82_dialog_content = "像你這樣有出色戰鬥能力的人，不該這樣沒沒無聞。",
  ui_story_5051_50511201_83_dialog_content = "今日招待多有不周，等一切穩定後，我們也許可以好好聊聊。",
  ui_story_5051_50511201_84_dialog_content = "我不過是個普通的老人。",
  ui_story_5051_50511201_85_dialog_content = "只希望自己的孩子可以安全回家。",
  ui_story_5051_50511201_86_dialog_content = "太遺憾了，我本以為我們會有很多共同話題。",
  ui_story_5051_50511201_87_dialog_content = "太過相似的人，也許並不適合做朋友。",
  ui_story_5051_50511201_88_dialog_content = "呵，是嗎？",
  ui_story_5051_50511201_89_dialog_content = "好吧，薇羅妮卡，我們走。",
  ui_story_5051_50511201_90_dialog_content = "我、我嗎？",
  ui_story_5051_50511201_91_dialog_content = "這裡還有別人叫薇羅妮卡嗎？",
  ui_story_5051_50511201_92_dialog_content = "我們要去哪裡？",
  ui_story_5051_50511201_93_dialog_content = "去追捕卡爾帝瑪家族剩下的反叛軍。",
  ui_story_5051_50511201_94_dialog_content = "我希望妳可以從今天開始，和我一起學習如何戰鬥。",
  ui_story_5051_50511201_95_dialog_content = "父親覺得、覺得我有這個資格嗎……",
  ui_story_5051_50511201_96_dialog_content = "薇羅妮卡公主的能力大家有目共睹。",
  ui_story_5051_50511201_97_dialog_content = "但她年齡尚幼，今日已經費了許多體力。",
  ui_story_5051_50511201_98_dialog_content = "還是讓她早點回去休息吧。",
  ui_story_5051_50511201_99_dialog_content = "臨空先生，也許PlayerName是需要休息，但薇羅妮卡是我的女兒。",
  ui_story_5051_50511201_100_dialog_content = "我們各自管好自己的孩子就夠了。",
  ui_story_5051_50511201_101_dialog_content = "<size=30>那、那個……</size>",
  ui_story_5051_50511201_102_dialog_content = "她需要休息。",
  ui_story_5051_50511201_103_dialog_content = "她需要學習。",
  ui_story_5051_50511201_104_dialog_content = "<size=45>那個！</size>",
  ui_story_5051_50511201_105_dialog_content = "嗯？",
  ui_story_5051_50511201_106_dialog_content = "我、我……",
  ui_story_5051_50511201_107_dialog_content = "我想去！",
  ui_story_5051_50511201_108_dialog_content = "？！",
  ui_story_5051_50511201_109_dialog_content = "父親從未如此肯定過我的能力……",
  ui_story_5051_50511201_110_dialog_content = "我、我一定不會讓父親再對我失望的！",
  ui_story_5051_50511201_111_dialog_content = "而且我也想看看，這段我從未體驗過的歷史，究竟是什麼樣的感覺。",
  ui_story_5051_50511201_112_dialog_content = "……",
  ui_story_5051_50511201_113_dialog_content = "薇羅妮卡，走了！",
  ui_story_5051_50511201_114_dialog_content = "是、是的！",
  ui_story_5051_50511201_115_dialog_content = "那我也要跟著一起去！",
  ui_story_5051_50511201_116_dialog_content = "你們……太任性了。",
  ui_story_5051_50511201_117_dialog_content = "老舒瓦茲，博阿姿她睡得太死了，有點不太正常……",
  ui_story_5051_50511201_118_dialog_content = "城主夫人說會帶她回家中治療，我、我沒辦法放著她不管。",
  ui_story_5051_50511201_119_dialog_content = "你們如果要去別的地方，一定要注意安全。",
  ui_story_5051_50511201_120_dialog_content = "還有，一定要在今天結束之前回來，否則我們可能會被困在這裡永遠都出不去……",
  ui_story_5051_50511201_121_dialog_content = "……我知道了。",
  ui_story_5051_50511201_122_dialog_content = "不過，妳剛才叫我什麼？",
  ui_story_5051_50511201_123_dialog_content = "啊……不小心說溜嘴了。",
  ui_story_5051_50511201_124_dialog_content = "總之，你們快點回來！",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>奧托宅邸</color>",
  ui_story_5051_50511201_126_dialog_content = "特洛伊公爵，你是不是早就知曉此事？",
  ui_story_5051_50511201_127_dialog_content = "嗯？不知道赫密士公爵說的是哪件事？",
  ui_story_5051_50511201_128_dialog_content = "外面都亂成了一鍋粥，你也不必跟我賣關子。",
  ui_story_5051_50511201_129_dialog_content = "喔！你是說有人利用暗鬼製造動亂，試圖刺殺城主殿下的那件事？",
  ui_story_5051_50511201_130_dialog_content = "正是！",
  ui_story_5051_50511201_131_dialog_content = "我就算再看不慣舒瓦茲的做法，也不必用這麼低劣的手段玷汙我家族的名聲。",
  ui_story_5051_50511201_132_dialog_content = "所以，你真的不知情？",
  ui_story_5051_50511201_133_dialog_content = "我說赫密士公爵，你怎麼天天疑神疑鬼的，誰都要懷疑一遍嗎？",
  ui_story_5051_50511201_134_dialog_content = "我不是想要懷疑特洛伊公爵。",
  ui_story_5051_50511201_135_dialog_content = "而是……你知道的，赫密士家族的後代都已加入騎士團。",
  ui_story_5051_50511201_136_dialog_content = "舒瓦茲現在要讓整支騎士團都去支援影鎮，這件事我一直都很反對！",
  ui_story_5051_50511201_137_dialog_content = "那些暗鬼原本在地上橫行，又影響不到我們白夜城。",
  ui_story_5051_50511201_138_dialog_content = "我們為什麼要趕著去送死？",
  ui_story_5051_50511201_139_dialog_content = "這麼想的應該不只我一個人吧？",
  ui_story_5051_50511201_140_dialog_content = "赫密士公爵，城主殿下也有他的考慮。",
  ui_story_5051_50511201_141_dialog_content = "如果能保住影鎮，我們白夜城不就能收緊一點對影鎮的支配權嗎？",
  ui_story_5051_50511201_142_dialog_content = "這道理，赫密士公爵你也不是不懂。",
  ui_story_5051_50511201_143_dialog_content = "哼，就那點小小的權利，到時候恐怕也會收歸到舒瓦茲一個人的手裡。",
  ui_story_5051_50511201_144_dialog_content = "還好意思慶祝什麼「舒瓦茲家族日」。",
  ui_story_5051_50511201_145_dialog_content = "白夜城能夠走到今天，赫密士與特洛伊兩大家族功不可沒！",
  ui_story_5051_50511201_146_dialog_content = "憑什麼好處都讓他們舒瓦茲家族占去？",
  ui_story_5051_50511201_147_dialog_content = "要是卡爾帝瑪家能提前透露計畫，我們幾個家族聯合起來……",
  ui_story_5051_50511201_148_dialog_content = "還需要怕舒瓦茲嗎？",
  ui_story_5051_50511201_149_dialog_content = "赫密士公爵，說話小心一點……",
  ui_story_5051_50511201_150_dialog_content = "我剛得到消息，城主殿下已經下令逮捕卡爾帝瑪家族的所有成員。",
  ui_story_5051_50511201_151_dialog_content = "我們用腳趾頭都能想到他們的下場。",
  ui_story_5051_50511201_152_dialog_content = "難不成還會跟皮洛斯家族、戈蒂埃家族他們一樣嗎？",
  ui_story_5051_50511201_153_dialog_content = "唉，你還不懂嗎？問題就在這裡。",
  ui_story_5051_50511201_154_dialog_content = "嗯？你是說……",
  ui_story_5051_50511201_155_dialog_content = "等等，我明白了，這下全都聯繫在一起了！",
  ui_story_5051_50511201_156_dialog_content = "愚蠢的卡爾帝瑪！",
  ui_story_5051_50511201_157_dialog_content = "他們這樣做反倒給了舒瓦茲樹德立威的機會……",
  ui_story_5051_50511201_158_dialog_content = "舒瓦茲正好可以趁機煽動騎士團，甚至所有擁私兵的家族，一起去影鎮送死了。",
  ui_story_5051_50511201_159_dialog_content = "邁木·卡爾帝瑪，四肢發達、頭腦簡單的傢伙！",
  ui_story_5051_50511201_160_dialog_content = "事已至此，赫密士公爵，還是少說為妙。",
  ui_story_5051_50511201_161_dialog_content = "剛才的話，我就當作自己打了個瞌睡，沒聽到。",
  ui_story_5051_50511201_162_dialog_content = "……多謝特洛伊公爵。那我也不便打擾了，告辭。",
  ui_story_5051_50511201_163_dialog_content = "來人。",
  ui_story_5051_50511201_164_dialog_content = "是。",
  ui_story_5051_50511201_165_dialog_content = "把和卡爾帝瑪家族往來的書信全部處理乾淨。",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>匡當！</color>",
  ui_story_5051_50511201_167_dialog_content = "怎麼回事？！",
  ui_story_5051_50511201_168_dialog_content = "我馬上去確認。",
  ui_story_5051_50511201_169_dialog_content = "看見是誰了嗎？",
  ui_story_5051_50511201_170_dialog_content = "是羅熙小姐，您約好與她晚飯前見面。",
  ui_story_5051_50511201_171_dialog_content = "她已經在門外等了一陣子。",
  ui_story_5051_50511201_172_dialog_content = "但剛才又慌慌張張地跑走了。",
  ui_story_5051_50511201_173_dialog_content = "這些傢伙，真是不讓人省心……",
  ui_story_5051_50511301_1_dialog_content = "城主殿下，卡爾帝瑪家族的這座宅邸也沒有任何發現。",
  ui_story_5051_50511301_2_dialog_content = "目前卡爾帝瑪家族在高庭的所有房地產都查封了，除了傭人並未發現其他武裝人員。",
  ui_story_5051_50511301_3_dialog_content = "除了一艘不顧警告擅自離開白夜城的飛空艇……",
  ui_story_5051_50511301_4_dialog_content = "卡爾帝瑪家族的其他成員應該還躲在白夜城內。",
  ui_story_5051_50511301_5_dialog_content = "中庭和下城的情況呢？",
  ui_story_5051_50511301_6_dialog_content = "已經派人去查了，不過還需要一點時間才能確認情況。",
  ui_story_5051_50511301_7_dialog_content = "沒有逃跑，反而躲在白夜城裡嗎？",
  ui_story_5051_50511301_8_dialog_content = "看來，他們還在等待機會反攻。",
  ui_story_5051_50511301_9_dialog_content = "卡爾帝瑪家族的成員眾多，近年來有不少依附他們的人。",
  ui_story_5051_50511301_10_dialog_content = "這樣看來，情況比想像中還要危險……",
  ui_story_5051_50511301_11_dialog_content = "不能坐以待斃。",
  ui_story_5051_50511301_12_dialog_content = "我們繼續往中庭搜查。",
  ui_story_5051_50511301_13_dialog_content = "請等一下。",
  ui_story_5051_50511301_14_dialog_content = "您、您還是來了！",
  ui_story_5051_50511301_15_dialog_content = "……",
  ui_story_5051_50511301_16_dialog_content = "<size=30>蜜雅，別害怕，我不是來帶妳回去的。</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>我想清楚了，妳有知曉這段歷史的權利。</size>",
  ui_story_5051_50511301_18_dialog_content = "喔？臨空先生，我就知道我們很快會再見面。",
  ui_story_5051_50511301_19_dialog_content = "但沒想到這麼快。",
  ui_story_5051_50511301_20_dialog_content = "只是忽然想起來，我這裡也許會有你們想要的線索。",
  ui_story_5051_50511301_21_dialog_content = "希望你不是在拖延我的時間。",
  ui_story_5051_50511301_22_dialog_content = "當然不會。我也希望我叛逆的孩子可以早點心甘情願隨我回去。",
  ui_story_5051_50511301_23_dialog_content = "但我希望你答應我，不要問我情報的來源。",
  ui_story_5051_50511301_24_dialog_content = "好，我答應你不問情報的來源。你說說看，是什麼線索？",
  ui_story_5051_50511301_25_dialog_content = "在下城區一片未開發的荒野，近來似乎有私兵駐紮的痕跡。",
  ui_story_5051_50511301_26_dialog_content = "紅女士，妳聽過這個消息嗎？",
  ui_story_5051_50511301_27_dialog_content = "靠近城外的荒野……",
  ui_story_5051_50511301_28_dialog_content = "難道是那座岩石山丘？",
  ui_story_5051_50511301_29_dialog_content = "我的確聽聞那裡偶爾傳來詭異的動物叫聲，附近人跡罕至……",
  ui_story_5051_50511301_30_dialog_content = "臨空先生，你的意思是，卡爾帝瑪家族的成員很有可能都藏在那裡？",
  ui_story_5051_50511301_31_dialog_content = "是百分之百確定。",
  ui_story_5051_50511301_32_dialog_content = "你為何如此肯定？到底是從哪裡得知這個消息的？",
  ui_story_5051_50511301_33_dialog_content = "你答應過不會逼問我。",
  ui_story_5051_50511301_34_dialog_content = "但我可以保證，如果消息不實，我願意接受任何懲罰。",
  ui_story_5051_50511301_35_dialog_content = "好。紅女士，就讓我們先去那片荒野上看看吧。",
  ui_story_5051_50511301_36_dialog_content = "城主殿下，這條線索真的能相信嗎？",
  ui_story_5051_50511301_37_dialog_content = "卡爾帝瑪家族遲早會敗陣投降。",
  ui_story_5051_50511301_38_dialog_content = "信他一次，不會妨礙到我們什麼。",
  ui_story_5051_50511301_39_dialog_content = "當然，其他地區的搜查也不能停下來。",
  ui_story_5051_50511301_40_dialog_content = "好的，城主殿下。",
  ui_story_5051_50511301_41_dialog_content = "嗯……",
  ui_story_5051_50511301_42_dialog_content = "有話想問我？",
  ui_story_5051_50511301_43_dialog_content = "剛才那個線索，當年也有人告訴您嗎？",
  ui_story_5051_50511301_44_dialog_content = "沒有，當年我們沒能在主城區搜查到有用的情報。",
  ui_story_5051_50511301_45_dialog_content = "我們在入夜後才發現荒野上的動靜，後來遭到反叛軍的猛烈攻擊。",
  ui_story_5051_50511301_46_dialog_content = "只不過，他們最後沒能逃脫失敗的命運。",
  ui_story_5051_50511301_47_dialog_content = "您是為了讓我們早點跟您回去，才刻意加速推進歷史嗎？",
  ui_story_5051_50511301_48_dialog_content = "有時我會想，如果當年我馬上就找到反叛軍……",
  ui_story_5051_50511301_49_dialog_content = "那些跟隨我多年的衛兵，也許現在也會有幾個令他們操心的兒女。",
  ui_story_5051_50511301_50_dialog_content = "您不是一直害怕我們影響到這個世界嗎？",
  ui_story_5051_50511301_51_dialog_content = "都影響得這麼多了，應該也不差我這一次吧。",
  ui_story_5051_50511301_52_dialog_content = "您好像……和我認識的舒瓦茲大人不太一樣了。",
  ui_story_5051_50511301_53_dialog_content = "是嗎？放下城主的身分後，我也覺得自己好像有哪裡不太一樣了。",
  ui_story_5051_50511301_54_dialog_content = "尤其是看到過去的自己之後……",
  ui_story_5051_50511301_55_dialog_content = "就是這裡嗎？",
  ui_story_5051_50511301_56_dialog_content = "偵察人員回報，卡爾帝瑪家族的成員的確都聚集在前方的山丘上。",
  ui_story_5051_50511301_57_dialog_content = "他們似乎打算破釜沉舟，負隅頑抗！",
  ui_story_5051_50511301_58_dialog_content = "薇羅妮卡，妳來說說看。",
  ui_story_5051_50511301_59_dialog_content = "現在這種情況，若妳是總指揮，會怎麼做？",
  ui_story_5051_50511301_60_dialog_content = "如果是我的話……",
  ui_story_5051_50511301_61_dialog_content = "我會派一名使者過去，動之以情，曉之以理。",
  ui_story_5051_50511301_62_dialog_content = "讓他們主動承認錯誤，未來將功贖罪。",
  ui_story_5051_50511301_63_dialog_content = "不對，薇羅妮卡。",
  ui_story_5051_50511301_64_dialog_content = "如果妳想要承擔更多責任，就必須逼自己<color=#FFB400>不擇手段</color>取勝。",
  ui_story_5051_50511301_65_dialog_content = "不擇手段……取勝？",
  ui_story_5051_50511301_66_dialog_content = "上至高庭，下至影鎮，有太多雙眼睛在盯著這場決鬥。",
  ui_story_5051_50511301_67_dialog_content = "他們都在等著我們分出勝負。他們只會向勝者獻上讚美，無論勝者為何方。",
  ui_story_5051_50511301_68_dialog_content = "戰場之上，勝者為王、敗者為寇。",
  ui_story_5051_50511301_69_dialog_content = "白夜城的歷史，很可能在接下來發生改變。",
  ui_story_5051_50511301_70_dialog_content = "薇羅妮卡，妳需要學的東西還有太多。",
  ui_story_5051_50511301_71_dialog_content = "不擇手段？他的價值觀聽起來有點……難以認同。",
  ui_story_5051_50511301_72_dialog_content = "是嗎？",
  ui_story_5051_50511301_73_dialog_content = "（啊，差點忘了，吐槽過去的他，也是在吐槽他本人？！）",
  ui_story_5051_50511301_74_dialog_content = "那個，我不是故意這麼說您的……",
  ui_story_5051_50511301_75_dialog_content = "站在高處時，有些事情身不由己……雖然這聽起來像是推卸責任的藉口。",
  ui_story_5051_50511301_76_dialog_content = "現在的我，不會趾高氣昂地告訴你，我是個毫無瑕疵的完人。",
  ui_story_5051_50511301_77_dialog_content = "只希望……",
  ui_story_5051_50511301_78_dialog_content = "你能夠在未來的成長過程中另闢蹊徑，找到一條屬於你自己的道路。",
  ui_story_5051_50511301_79_dialog_content = "嗯！",
  ui_story_5051_50511301_80_dialog_content = "希望我老去的時候，不會懊悔年輕時的自己。",
  ui_story_5051_50511301_81_dialog_content = "啊……我、我不是想要諷刺您！",
  ui_story_5051_50511301_82_dialog_content = "哈哈哈哈！",
  ui_story_5051_50511301_83_dialog_content = "（印象中，這還是我第一次看到舒瓦茲這樣爽朗地大笑。）",
  ui_story_5051_50511301_84_dialog_content = "（我這才發現，也許除了眼前的老舒瓦茲和小舒瓦茲之外……）",
  ui_story_5051_50511301_85_dialog_content = "（在更久遠的過去，這世界上也曾有過一個涉世未深、可以開懷大笑的……狄安理。）",
  ui_story_5051_50511301_86_dialog_content = "前面好像有什麼動靜？",
  ui_story_5051_50511301_87_dialog_content = "……是埋伏在外的反叛軍？！",
  ui_story_5051_50511302_1_dialog_content = "所有重要的房間我都搜了一遍。",
  ui_story_5051_50511302_2_dialog_content = "怎麼就是找不到？！",
  ui_story_5051_50511302_3_dialog_content = "難道舒瓦茲還有什麼不為人知的密室？",
  ui_story_5051_50511302_4_dialog_content = "一定是這樣。",
  ui_story_5051_50511302_5_dialog_content = "依舒瓦茲的個性，他一定有許多瞞著姐姐的祕密。",
  ui_story_5051_50511302_6_dialog_content = "密室的入口，會在舒瓦茲的書房裡嗎？",
  ui_story_5051_50511302_7_dialog_content = "嗯？書架上那個是……",
  ui_story_5051_50511302_8_dialog_content = "「永憶鏡晶」？！",
  ui_story_5051_50511302_9_dialog_content = "沒錯，這的確是「永憶鏡晶」！",
  ui_story_5051_50511302_10_dialog_content = "最危險的地方，就是最安全的地方嗎？",
  ui_story_5051_50511302_11_dialog_content = "哈哈哈哈哈哈！",
  ui_story_5051_50511302_12_dialog_content = "如此貴重的東西，舒瓦茲竟然這麼隨便地擺在這裡。",
  ui_story_5051_50511302_13_dialog_content = "就像我親愛的姐姐，被他……",
  ui_story_5051_50511302_14_dialog_content = "城主夫人，您回來了！",
  ui_story_5051_50511302_15_dialog_content = "是姐姐……",
  ui_story_5051_50511302_16_dialog_content = "發生什麼事了嗎？你好像很慌張？",
  ui_story_5051_50511302_17_dialog_content = "……屬下無能！",
  ui_story_5051_50511302_18_dialog_content = "今天下午一名護衛在門口被人打暈了，現在還躺在病房裡。",
  ui_story_5051_50511302_19_dialog_content = "但我們四處搜查後，並沒有發現那位歹徒……",
  ui_story_5051_50511302_20_dialog_content = "又是卡爾帝瑪家族的人嗎？",
  ui_story_5051_50511302_21_dialog_content = "這件事我知道了。",
  ui_story_5051_50511302_22_dialog_content = "今晚有客人在，拜託你們在門外多留意一點。",
  ui_story_5051_50511302_23_dialog_content = "是，城主夫人！",
  ui_story_5051_50511302_24_dialog_content = "另外，讓那位受傷的護衛安心養傷。",
  ui_story_5051_50511302_25_dialog_content = "他的醫療費用全數由我負擔。",
  ui_story_5051_50511302_26_dialog_content = "謝謝城主夫人！！",
  ui_story_5051_50511302_27_dialog_content = "卡爾帝瑪家族……",
  ui_story_5051_50511302_28_dialog_content = "妳似乎也認識卡爾帝瑪家族的人？",
  ui_story_5051_50511302_29_dialog_content = "是……但我並不知道她是這場叛亂的一份子。",
  ui_story_5051_50511302_30_dialog_content = "她明明看起來很正直、善良。",
  ui_story_5051_50511302_31_dialog_content = "她還告訴我她未來想成為一名威風的騎士長！",
  ui_story_5051_50511302_32_dialog_content = "看來妳這位朋友也是無辜的，她似乎並不知情。",
  ui_story_5051_50511302_33_dialog_content = "如果她被抓到……會怎麼樣？",
  ui_story_5051_50511302_34_dialog_content = "現在還不知道。",
  ui_story_5051_50511302_35_dialog_content = "但妳放心，我會盡力保護那些無辜之人。",
  ui_story_5051_50511302_36_dialog_content = "就算她的族人曾經想刺殺您和家人？",
  ui_story_5051_50511302_37_dialog_content = "罪人應該受到懲罰。",
  ui_story_5051_50511302_38_dialog_content = "但我想，無罪之人不應因為血脈而受到牽連……",
  ui_story_5051_50511302_39_dialog_content = "還是先不說這個了。",
  ui_story_5051_50511302_40_dialog_content = "我還是先去準備晚餐，還有博阿姿的醒酒湯吧。",
  ui_story_5051_50511302_41_dialog_content = "您……不擔心城主大人嗎？",
  ui_story_5051_50511302_42_dialog_content = "呵呵，我當然擔心啊～",
  ui_story_5051_50511302_43_dialog_content = "但我比較想相信狄安理，他一定會安然無恙。",
  ui_story_5051_50511302_44_dialog_content = "所以，我才要做好晚餐，等他回來喲～",
  ui_story_5051_50511302_45_dialog_content = "約書亞夫人，我已經開始想念您了！",
  ui_story_5051_50511302_46_dialog_content = "那加晴以後可以常常來白夜城玩喔～",
  ui_story_5051_50511302_47_dialog_content = "小薇和小卡蓮，應該會非常喜歡加晴這樣的朋友呢。",
  ui_story_5051_50511302_48_dialog_content = "嗚嗚嗚！",
  ui_story_5051_50511302_49_dialog_content = "噓——",
  ui_story_5051_50511302_50_dialog_content = "博阿姿和小卡蓮還在睡覺，小心不要嚇到她們喔～",
  ui_story_5051_50511401_1_dialog_content = "本來以為利用暗鬼製造混亂，就可以輕鬆拿下舒瓦茲。",
  ui_story_5051_50511401_2_dialog_content = "沒想到，我還是低估了舒瓦茲的實力。",
  ui_story_5051_50511401_3_dialog_content = "對外宣稱身體抱恙……都是故意的嗎。",
  ui_story_5051_50511401_4_dialog_content = "看來他早就知道我的計畫了。",
  ui_story_5051_50511401_5_dialog_content = "要論狡猾，白夜城之內沒人比得過舒瓦茲。",
  ui_story_5051_50511401_6_dialog_content = "呵，我還以為這麼多年來，自己已經變得夠狡猾了……",
  ui_story_5051_50511401_7_dialog_content = "……",
  ui_story_5051_50511401_8_dialog_content = "怎麼會這樣？邁木，你為什麼會覺醒<color=#FFB400>龍脈</color>？",
  ui_story_5051_50511401_9_dialog_content = "這在卡爾帝瑪家族是不可饒恕的！",
  ui_story_5051_50511401_10_dialog_content = "我不是故意的，母親，救救我！",
  ui_story_5051_50511401_11_dialog_content = "我的孩子，不要把這件事告訴任何人。",
  ui_story_5051_50511401_12_dialog_content = "但、但是我的頭，痛得快要裂開了……",
  ui_story_5051_50511401_13_dialog_content = "忍住，邁木！告訴我，告訴我你可以壓抑這股力量！",
  ui_story_5051_50511401_14_dialog_content = "能夠成為卡爾帝瑪家族之首的人，一定要是你！",
  ui_story_5051_50511401_15_dialog_content = "痛……我、我做不到！",
  ui_story_5051_50511401_16_dialog_content = "你一定要做到！",
  ui_story_5051_50511401_17_dialog_content = "你敢再說一遍？",
  ui_story_5051_50511401_18_dialog_content = "就算把我囚禁在這搖搖欲墜的高塔上，咳咳咳……",
  ui_story_5051_50511401_19_dialog_content = "我也還是會說一樣的話！",
  ui_story_5051_50511401_20_dialog_content = "邁木，你無法拯救卡爾帝瑪家族。",
  ui_story_5051_50511401_21_dialog_content = "卡爾帝瑪家族的首領，不是你！",
  ui_story_5051_50511401_22_dialog_content = "沒錯，我是覺醒了龍脈，但那又怎樣呢？",
  ui_story_5051_50511401_23_dialog_content = "我現在已經成為了卡爾帝瑪家族的首領，這是事實。",
  ui_story_5051_50511401_X23_dialog_content = "覺醒了龍脈？！",
  ui_story_5051_50511401_X24_dialog_content = "你竟然瞞過了那些視「龍脈」為罪惡的族人……倒是有點能耐。",
  ui_story_5051_50511401_X25_dialog_content = "可是我還是要說，可以拯救卡爾迪瑪家族的人，不是你。",
  ui_story_5051_50511401_X26_dialog_content = "這與你有沒有覺醒龍脈，並沒有關係。",
  ui_story_5051_50511401_X27_dialog_content = "很可惜，沒有人會相信你的預言。",
  ui_story_5051_50511401_24_dialog_content = "哈哈哈哈哈哈，咳咳……",
  ui_story_5051_50511401_25_dialog_content = "顫抖吧！那個可以拯救卡爾帝瑪家族的女孩，即將出現在你身邊。",
  ui_story_5051_50511401_26_dialog_content = "你已經徹底瘋了。",
  ui_story_5051_50511401_27_dialog_content = "……其他族人都不喜歡這孩子，沒人願意收養她。",
  ui_story_5051_50511401_28_dialog_content = "邁木大人，晚上好。",
  ui_story_5051_50511401_29_dialog_content = "我是……希羅娜。",
  ui_story_5051_50511401_30_dialog_content = "！！！",
  ui_story_5051_50511401_31_dialog_content = "難道長老說的人，是妳？",
  ui_story_5051_50511401_32_dialog_content = "我保證不會給您添麻煩的。",
  ui_story_5051_50511401_33_dialog_content = "這個孩子，我收養了。",
  ui_story_5051_50511401_34_dialog_content = "謝、謝謝邁木大人！",
  ui_story_5051_50511401_35_dialog_content = "做好心理準備。在我這裡，妳永遠都不會有出頭之日。",
  ui_story_5051_50511401_36_dialog_content = "咦……",
  ui_story_5051_50511401_37_dialog_content = "邁木大人、邁木大人……",
  ui_story_5051_50511401_38_dialog_content = "什麼事？",
  ui_story_5051_50511401_39_dialog_content = "卡爾帝瑪家族士兵與所有族人已經集結完畢。",
  ui_story_5051_50511401_40_dialog_content = "到頭來還是連累了諸位嗎……",
  ui_story_5051_50511401_41_dialog_content = "大人，您千萬別這麼說！",
  ui_story_5051_50511401_42_dialog_content = "舒瓦茲一直在稀釋我們卡爾帝瑪家族手中的權力。",
  ui_story_5051_50511401_43_dialog_content = "要不是您，卡爾帝瑪家族早就被舒瓦茲徹底瓦解了。",
  ui_story_5051_50511401_44_dialog_content = "算了，不談這些。",
  ui_story_5051_50511401_45_dialog_content = "不，我要說！我們要說！",
  ui_story_5051_50511401_46_dialog_content = "這些年您為卡爾帝瑪家族做出的貢獻，眾人都有目共睹。",
  ui_story_5051_50511401_47_dialog_content = "我們跟著您心甘情願、沒有一絲怨言！",
  ui_story_5051_50511401_48_dialog_content = "但那個舒瓦茲，他明知各大家族都反對派兵支援影鎮……",
  ui_story_5051_50511401_49_dialog_content = "卻要您在今天的儀式上宣誓支持他派兵支援影鎮。",
  ui_story_5051_50511401_50_dialog_content = "這擺明要讓我們卡爾帝瑪家族成為其他家族的眾矢之的，好成就他的光輝偉岸。",
  ui_story_5051_50511401_51_dialog_content = "與其為了舒瓦茲的利益，慘死在暗鬼手中……",
  ui_story_5051_50511401_52_dialog_content = "倒不如為了卡爾帝瑪家族而亡！",
  ui_story_5051_50511401_53_dialog_content = "<size=45>為卡爾帝瑪而亡！為卡爾帝瑪而亡！為卡爾帝瑪而亡！</size>",
  ui_story_5051_50511401_54_dialog_content = "哈哈哈，好！但有一點我不同意。",
  ui_story_5051_50511401_55_dialog_content = "這一戰，還未分勝負！",
  ui_story_5051_50511401_56_dialog_content = "大人……您說得對！",
  ui_story_5051_50511401_57_dialog_content = "我們願意追隨在您身後，奪回卡爾帝瑪家族失落的榮耀！",
  ui_story_5051_50511401_58_dialog_content = "我們已經準備好了，只等您一聲令下。",
  ui_story_5051_50511401_59_dialog_content = "我們誓死，守衛卡爾帝瑪家族的榮光！",
  ui_story_5051_50511401_60_dialog_content = "<size=45>守衛家族榮光！守衛家族榮光！守衛家族榮光！</size>",
  ui_story_5051_50511401_61_dialog_content = "好！",
  ui_story_5051_50511401_62_dialog_content = "現在，讓我來邀請我們的最後一位幫手。",
  ui_story_5051_50511401_63_dialog_content = "幫手？",
  ui_story_5051_50511401_64_dialog_content = "「翱翔天際的飛天之龍，卡爾帝瑪永恆的夥伴。」",
  ui_story_5051_50511401_65_dialog_content = "「展開妳的雙翼，劃破廣袤無垠的黑夜。」",
  ui_story_5051_50511401_66_dialog_content = "「來到我的身邊吧。」",
  ui_story_5051_50511401_67_dialog_content = "「來到我們的身邊吧。」",
  ui_story_5051_50511401_68_dialog_content = "「卡爾帝瑪家族從未忘記我們的誓約。」",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>吼——！</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "這個聲音是……",
  ui_story_5051_50511401_71_dialog_content = "大人，您該不會是召喚了<color=#FFB400>飛龍</color>？！",
  ui_story_5051_50511401_72_dialog_content = "飛龍從來都是卡爾帝瑪家族最忠實的朋友。",
  ui_story_5051_50511401_73_dialog_content = "有人忌憚卡爾帝瑪家族的力量，才讓我們的先祖堅信「龍脈」是不祥之兆。",
  ui_story_5051_50511401_74_dialog_content = "難道是舒瓦茲家族……？",
  ui_story_5051_50511401_75_dialog_content = "<size=45>蓋能，來吧！到你朋友和家人身邊來！</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>嗚——！</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "現在，我們不必再擔心異樣的目光。",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>吼——！</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "卡爾帝瑪的族人們聽好了！",
  ui_story_5051_50511401_80_dialog_content = "如今，飛龍歸來！",
  ui_story_5051_50511401_81_dialog_content = "牠會幫助我們，成為白夜城的主宰！",
  ui_story_5051_50511401_82_dialog_content = "飛龍萬歲！",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>吼嗚——！！！</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>同一時間·影鎮</color>",
  ui_story_5051_50511401_85_dialog_content = "你們剛才有聽見什麼聲音嗎？",
  ui_story_5051_50511401_86_dialog_content = "我還以為我幻聽了！",
  ui_story_5051_50511401_87_dialog_content = "該不會是暗鬼進攻過來了吧？！",
  ui_story_5051_50511401_88_dialog_content = "大家別亂說……快回家吧！",
  ui_story_5051_50511401_89_dialog_content = "走吧走吧，還是回家等死吧。",
  ui_story_5051_50511401_90_dialog_content = "影鎮……比記憶中還要潮濕一點。",
  ui_story_5051_50511401_91_dialog_content = "從這個視角看向白夜城……",
  ui_story_5051_50511401_92_dialog_content = "果然很不一樣。",
  ui_story_5051_50511401_93_dialog_content = "那裡的夜晚，似乎比這裡更冷一些。",
  ui_story_5051_50511401_94_dialog_content = "剛才的那聲嘶鳴……是暗鬼嗎？",
  ui_story_5051_50511401_95_dialog_content = "不，不是暗鬼。",
  ui_story_5051_50511401_96_dialog_content = "那還會是什麼？",
  ui_story_5051_50511401_97_dialog_content = "看，牠來了。",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>吼嗚——！！！</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "龍……是飛龍？",
  ui_story_5051_50511401_100_dialog_content = "呵，他們果然被惡龍的仇恨蒙蔽了雙眼。",
  ui_story_5051_50511401_101_dialog_content = "卡爾帝瑪家族的血脈，永遠都無法逃脫那個久遠的賣身契。",
  ui_story_5051_50511401_102_dialog_content = "龍就快要飛過來了！",
  ui_story_5051_50511401_103_dialog_content = "薇羅妮卡，妳先退後！",
  ui_story_5051_50511401_104_dialog_content = "讓我先來看看，這頭龍究竟有什麼本事。",
  ui_story_5051_50511401_105_dialog_content = "這隻飛龍體型碩大，還會噴出炙熱的烈焰。",
  ui_story_5051_50511401_106_dialog_content = "如果不想傷得太重，妳最好第一招就擊中龍的弱點。",
  ui_story_5051_50511401_107_dialog_content = "這隻龍的弱點是……",
  ui_story_5051_50511401_108_dialog_content = "這個我當然知道。",
  ui_story_5051_50511401_109_dialog_content = "咦，還沒聽完就走了嗎？",
  ui_story_5051_50511401_110_dialog_content = "看來，這場戰鬥還是得費一些時間了。",
  ui_story_5051_50511401_111_dialog_content = "您當年不知道龍的弱點嗎？",
  ui_story_5051_50511401_112_dialog_content = "還是說……您當年沒能一招就擊中龍的弱點？",
  ui_story_5051_50511401_113_dialog_content = "……",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>呼——呼——</color>",
  ui_story_5051_50511401_115_dialog_content = "起風了，這倒是與當年有所不同。",
  ui_story_5051_50511401_116_dialog_content = "（剛才的問題被選擇性忽視了嗎……）",
  ui_story_5051_50511401_117_dialog_content = "風向……如果能好好利用風的方向，也許……",
  ui_story_5051_50511401_118_dialog_content = "也許，這場戰鬥很快就會結束。",
  ui_story_5051_50511401_119_dialog_content = "呼哈——！！！",
  ui_story_5051_50511401_120_dialog_content = "「白夜之光！」",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>嗚！！！</anim>",
  ui_story_5051_50511401_122_dialog_content = "（小舒瓦茲精確地擊中了飛龍的咽喉，所以飛龍才暫時無法噴出火焰嗎？）",
  ui_story_5051_50511401_123_dialog_content = "（難道那裡就是龍的弱點？）",
  ui_story_5051_50511401_124_dialog_content = "（雖然看不清楚，但飛龍的背上……似乎還有一道人影。）",
  ui_story_5051_50511401_125_dialog_content = "是邁木·卡爾帝瑪！",
  ui_story_5051_50511401_126_dialog_content = "是進城時遇到的那位騎士長……",
  ui_story_5051_50511401_127_dialog_content = "呵呵，飛龍的攻擊也只有這點程度而已嗎？",
  ui_story_5051_50511401_128_dialog_content = "看來我甚至不用使出全力。",
  ui_story_5051_50511401_129_dialog_content = "擋住一次攻擊，算你僥倖。",
  ui_story_5051_50511401_130_dialog_content = "尊貴的城主殿下，千萬不要把運氣當作實力。",
  ui_story_5051_50511401_131_dialog_content = "你只是幸運躲過蓋能的火焰……你只是幸運成為城主。",
  ui_story_5051_50511401_132_dialog_content = "蓋能？你還替你的飛龍取了名字。",
  ui_story_5051_50511401_133_dialog_content = "這是一個危險的舉動，邁木。",
  ui_story_5051_50511401_134_dialog_content = "牠死去的時候，你一定會很傷心。",
  ui_story_5051_50511401_135_dialog_content = "廢話少說！",
  ui_story_5051_50511401_136_dialog_content = "蓋能，衝啊！",
  ui_story_5051_50511401_137_dialog_content = "對著眼前這個男人，狠狠獻上最猛烈的火焰吧！",
  ui_story_5051_50511401_138_dialog_content = "我的肩膀已經收過你送的「禮物」了，怎麼好意思再收一份？",
  ui_story_5051_50511401_139_dialog_content = "現在，輪到我來「還禮」了！",
  ui_story_5051_50511401_140_dialog_content = "「暗夜破滅，長日無盡！」",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>轟！！</color>",
  ui_story_5051_50511401_142_dialog_content = "衝啊！",
  ui_story_5051_50511401_143_dialog_content = "反叛軍們也衝出來了……",
  ui_story_5051_50511401_144_dialog_content = "所有人聽令！",
  ui_story_5051_50511401_145_dialog_content = "做好戰鬥準備！",
  ui_story_5051_50511401_146_dialog_content = "……",
  ui_story_5051_50511401_147_dialog_content = "蜜雅，妳也要去嗎？",
  ui_story_5051_50511401_148_dialog_content = "如果可以，我不想讓武器染上同胞的鮮血……",
  ui_story_5051_50511401_149_dialog_content = "父親，為什麼當年我們一定要這樣？",
  ui_story_5051_50511401_150_dialog_content = "因為他們想讓武器染上我們的鮮血。",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>嗚……</anim>",
  ui_story_5051_50511402_2_dialog_content = "蓋能！不！！！",
  ui_story_5051_50511402_3_dialog_content = "這不可能是真的……",
  ui_story_5051_50511402_4_dialog_content = "這一切不該是這樣！！！",
  ui_story_5051_50511402_5_dialog_content = "（小舒瓦茲果然利用風向打敗了飛龍……）",
  ui_story_5051_50511402_6_dialog_content = "（這場戰鬥，比想像中結束得更快。）",
  ui_story_5051_50511402_7_dialog_content = "邁木·卡爾帝瑪！",
  ui_story_5051_50511402_8_dialog_content = "你身為白夜城的騎士長，本應成為守衛白夜城的堅實力量。",
  ui_story_5051_50511402_9_dialog_content = "但你卻選擇背叛白夜城，背叛身為騎士的信條。",
  ui_story_5051_50511402_10_dialog_content = "還對白夜城百姓造成無可挽回的財產損失和傷痛。",
  ui_story_5051_50511402_11_dialog_content = "白夜至上！",
  ui_story_5051_50511402_12_dialog_content = "你的行為已經構成謀反罪。",
  ui_story_5051_50511402_13_dialog_content = "即刻起，將終身褫奪你所有爵位和職位。",
  ui_story_5051_50511402_14_dialog_content = "你就在監獄裡等待審判庭的最終判決吧。",
  ui_story_5051_50511402_15_dialog_content = "呵呵，還等什麼……",
  ui_story_5051_50511402_16_dialog_content = "舒瓦茲，你不如現在就殺了我！",
  ui_story_5051_50511402_17_dialog_content = "你不想見見你的族人嗎？",
  ui_story_5051_50511402_18_dialog_content = "……你！",
  ui_story_5051_50511402_19_dialog_content = "這些事都是我一個人的錯，和其他人無關！",
  ui_story_5051_50511402_20_dialog_content = "是我威脅他們跟著我起兵的……",
  ui_story_5051_50511402_21_dialog_content = "你若還是個正人君子，就放過那些老人和小孩！",
  ui_story_5051_50511402_22_dialog_content = "事已至此，我一個人的意見並不算數。",
  ui_story_5051_50511402_23_dialog_content = "還是把你的懇求留到審判庭再說吧。",
  ui_story_5051_50511402_24_dialog_content = "審判庭會給予你公正的裁決。",
  ui_story_5051_50511402_25_dialog_content = "呵呵……",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>哈哈哈哈哈哈哈哈哈！</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "能夠拯救卡爾帝瑪家族的人，果然不是我嗎……",
  ui_story_5051_50511402_28_dialog_content = "如果長老的話是真的，她一定會完成我未竟的使命！",
  ui_story_5051_50511402_29_dialog_content = "卡爾帝瑪家族是被你親手毀滅的。",
  ui_story_5051_50511402_30_dialog_content = "如果今天你能依照約定，在眾人面前宣誓會隨我一同支援影鎮……",
  ui_story_5051_50511402_31_dialog_content = "也許結局才會有所不同。",
  ui_story_5051_50511402_32_dialog_content = "你……",
  ui_story_5051_50511402_33_dialog_content = "休想！",
  ui_story_5051_50511402_34_dialog_content = "危險！！",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5051_50511402_36_dialog_content = "呃……",
  ui_story_5051_50511402_37_dialog_content = "（明明知道已經無力回天，邁木還是孤注一擲地想要反擊嗎……）",
  ui_story_5051_50511402_38_dialog_content = "我敬佩你的勇氣，邁木·卡爾帝瑪。",
  ui_story_5051_50511402_39_dialog_content = "紅女士，接下來的事就交給妳了。",
  ui_story_5051_50511402_40_dialog_content = "我去確認卡蓮的傷勢，稍後在議事廳等我。",
  ui_story_5051_50511402_41_dialog_content = "是！",
  ui_story_5051_50511501_1_dialog_content = "約書亞，我回來了。",
  ui_story_5051_50511501_2_dialog_content = "狄安理……",
  ui_story_5051_50511501_3_dialog_content = "快讓我看看，身上的傷口有沒有裂開？有沒有新的傷口？",
  ui_story_5051_50511501_4_dialog_content = "放心，約書亞，我說過我不會讓妳擔心。",
  ui_story_5051_50511501_5_dialog_content = "比起這個，卡蓮怎麼樣了？",
  ui_story_5051_50511501_6_dialog_content = "醫生來看過了，沒有大礙，休息幾天就好。",
  ui_story_5051_50511501_7_dialog_content = "那就好。",
  ui_story_5051_50511501_8_dialog_content = "晚餐已經準備好了，稍微吃一點吧。",
  ui_story_5051_50511501_9_dialog_content = "不了。我還有事得去處理。",
  ui_story_5051_50511501_10_dialog_content = "妳早點休息。",
  ui_story_5051_50511501_11_dialog_content = "狄安理，你已經忙了一整天，需要休息的人是你。",
  ui_story_5051_50511501_12_dialog_content = "卡爾帝瑪家族的事，必須快點找元老院和審判庭商議。",
  ui_story_5051_50511501_13_dialog_content = "抱歉，約書亞。",
  ui_story_5051_50511501_14_dialog_content = "等處理完這件事，下次我們一家四口好好吃頓飯，好嗎？",
  ui_story_5051_50511501_15_dialog_content = "狄安理……你可以告訴我，卡爾帝瑪家族會受到怎樣的處置嗎？",
  ui_story_5051_50511501_16_dialog_content = "這件事更不需要妳來操心。卡爾帝瑪家族一定會付出應有的代價。",
  ui_story_5051_50511501_17_dialog_content = "那些對此毫不知情的人呢？",
  ui_story_5051_50511501_18_dialog_content = "他們也會被捲進來嗎？",
  ui_story_5051_50511501_19_dialog_content = "約書亞，不要忘了。",
  ui_story_5051_50511501_20_dialog_content = "今天是卡爾帝瑪家族的人用冰冷的劍指向我們、指向我們的女兒。",
  ui_story_5051_50511501_21_dialog_content = "他們在背叛我們的時候，可從來沒想過我們的女兒也是無辜的！",
  ui_story_5051_50511501_22_dialog_content = "但你……",
  ui_story_5051_50511501_23_dialog_content = "狄安理，我想問你一個問題。",
  ui_story_5051_50511501_24_dialog_content = "你是不是早就知道卡爾帝瑪家族要謀反的事……？",
  ui_story_5051_50511501_25_dialog_content = "是誰告訴妳的？",
  ui_story_5051_50511501_26_dialog_content = "是你，狄安理。你最近的行為很反常。",
  ui_story_5051_50511501_27_dialog_content = "不要胡思亂想了，好嗎？",
  ui_story_5051_50511501_28_dialog_content = "但你怎麼知道今天會出現兩批暗鬼？",
  ui_story_5051_50511501_29_dialog_content = "還有，我左思右想……",
  ui_story_5051_50511501_30_dialog_content = "你與我練習劍術時，明明五十米開外的風吹草動你都觀察得到。",
  ui_story_5051_50511501_31_dialog_content = "為什麼當時刺客那麼明顯的攻擊，你會反應不過來？",
  ui_story_5051_50511501_32_dialog_content = "你……是<color=#FFB400>故意</color>的嗎？",
  ui_story_5051_50511501_33_dialog_content = "但我想不通，你這麼做究竟是為了什麼。",
  ui_story_5051_50511501_34_dialog_content = "是因為你想用傷勢博取同情，坐實卡爾帝瑪家族的罪行嗎？",
  ui_story_5051_50511501_35_dialog_content = "事情不是妳想的那樣。",
  ui_story_5051_50511501_36_dialog_content = "如果我事先知道他們的計畫，怎麼會讓妳和孩子跟我一起去呢？",
  ui_story_5051_50511501_37_dialog_content = "！！！",
  ui_story_5051_50511501_38_dialog_content = "只要我和卡蓮待在你身邊，反叛軍就不會起疑心，而依照原定計畫行事……",
  ui_story_5051_50511501_39_dialog_content = "你把我們當成你的<color=#FFB400>棋子</color>？",
  ui_story_5051_50511501_40_dialog_content = "……",
  ui_story_5051_50511501_41_dialog_content = "我是白夜城的城主，主宰著這座浮空島嶼的未來。",
  ui_story_5051_50511501_42_dialog_content = "為了達成目標，我甚至連自己都可以當成棋子。",
  ui_story_5051_50511501_43_dialog_content = "這是我們肩負的責任，約書亞。",
  ui_story_5051_50511501_44_dialog_content = "我知道，你做這一切都是為了最終能獲得抵抗暗鬼的力量。",
  ui_story_5051_50511501_45_dialog_content = "可是，你為什麼不肯告訴我呢？",
  ui_story_5051_50511501_46_dialog_content = "也許我們可以一起想出兩全其美的辦法。",
  ui_story_5051_50511501_47_dialog_content = "……你可以把我當作棋子，我不會有任何怨言。",
  ui_story_5051_50511501_48_dialog_content = "但你真的捨得讓我們那麼小的孩子也成為你棋局上的一顆棋子嗎？",
  ui_story_5051_50511501_49_dialog_content = "萬一今天小卡蓮真的被……",
  ui_story_5051_50511501_50_dialog_content = "我不會讓那種事發生。",
  ui_story_5051_50511501_51_dialog_content = "事實上，卡蓮現在不是也沒什麼大礙嗎？",
  ui_story_5051_50511501_52_dialog_content = "這一次只是僥倖。要是有個萬一呢？",
  ui_story_5051_50511501_53_dialog_content = "如果還有下一次，你可以答應我，提前告知我一切情況嗎？",
  ui_story_5051_50511501_54_dialog_content = "真實的政治要比紙上談兵複雜千萬倍。",
  ui_story_5051_50511501_55_dialog_content = "約書亞，我愛妳……",
  ui_story_5051_50511501_56_dialog_content = "所以我不希望把妳也捲進這些骯髒的泥淖裡。",
  ui_story_5051_50511501_57_dialog_content = "我們當初一起讀書的時候，你並不是這樣說的。",
  ui_story_5051_50511501_58_dialog_content = "你說，我們會一起改變白夜城。",
  ui_story_5051_50511501_59_dialog_content = "但你現在卻不願意相信我。",
  ui_story_5051_50511501_60_dialog_content = "我從來沒有不相信妳。我把家放心地交給妳打理。",
  ui_story_5051_50511501_61_dialog_content = "同樣地，妳也應該相信我在政治上的判斷。",
  ui_story_5051_50511501_62_dialog_content = "犧牲掉一整個家族，來為你的政權鋪路。",
  ui_story_5051_50511501_63_dialog_content = "如果這就是你慎思熟慮的結果。",
  ui_story_5051_50511501_64_dialog_content = "狄安理……我好像有點不認識你了。",
  ui_story_5051_50511501_65_dialog_content = "為了坐穩城主的位置，你已經開始不擇手段。",
  ui_story_5051_50511501_66_dialog_content = "不、不僅是不擇手段。",
  ui_story_5051_50511501_67_dialog_content = "你還有一顆比北境山巔更冰冷徹骨的心！",
  ui_story_5051_50511501_68_dialog_content = "因為你，薇羅妮卡成了人們眼中的怪物……",
  ui_story_5051_50511501_69_dialog_content = "小卡蓮遲早也有一天會因為你而喪生……",
  ui_story_5051_50511501_70_dialog_content = "而我、我也會離你而去，從這個世界上徹底消失……",
  ui_story_5051_50511501_71_dialog_content = "約書亞……約書亞！",
  ui_story_5051_50511501_72_dialog_content = "我的約書亞！",
  ui_story_5051_50511501_73_dialog_content = "為什麼？",
  ui_story_5051_50511501_74_dialog_content = "<size=45>為什麼要離開我？！</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>呼哧……呼哧……呼哧……</anim>",
  ui_story_5051_50511501_76_dialog_content = "您有哪裡不舒服嗎？",
  ui_story_5051_50511501_77_dialog_content = "約書亞！",
  ui_story_5051_50511501_78_dialog_content = "咦，您這是怎麼了，臨空先生？",
  ui_story_5051_50511501_79_dialog_content = "「父親」，您快要把城主夫人的手抓破了……",
  ui_story_5051_50511501_80_dialog_content = "喔，是我失態了。",
  ui_story_5051_50511501_X80_dialog_content = "不知為何想起我常做的噩夢。",
  ui_story_5051_50511501_81_dialog_content = "年紀大了，可能需要多休息一下了。",
  ui_story_5051_50511501_82_dialog_content = "您好好休息，稍後大家可以一起去吃頓便飯。",
  ui_story_5051_50511501_83_dialog_content = "約書亞，辛苦妳招待客人了。",
  ui_story_5051_50511501_84_dialog_content = "晚餐馬上就準備好，大家一起到餐廳去吧。",
  ui_story_5051_50511501_85_dialog_content = "不了。我還有事必須處理。",
  ui_story_5051_50511501_86_dialog_content = "你們吃完早點休息。",
  ui_story_5051_50511501_87_dialog_content = "狄安理，你已經忙了一整天，需要休息的人是你。",
  ui_story_5051_50511501_88_dialog_content = "……",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName，快想個辦法吸引大家的注意力！</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>咦，為什麼？</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>否則，我們面前將會爆發一場我不想再看到的爭執……</size>",
  ui_story_5051_50511501_92_dialog_content = "卡爾帝瑪家族的事，必須快點找元老院和審判庭商議。",
  ui_story_5051_50511501_93_dialog_content = "抱歉，約書亞。",
  ui_story_5051_50511501_94_dialog_content = "等處理完這件事，下次我們一家四口好好吃頓飯，好嗎？",
  ui_story_5051_50511501_95_dialog_content = "好！我覺得很好！",
  ui_story_5051_50511501_96_dialog_content = "欸？",
  ui_story_5051_50511501_97_dialog_content = "工作沒做完的人去工作，該休息的人留下來休息。",
  ui_story_5051_50511501_98_dialog_content = "我覺得這樣……對大家都好。",
  ui_story_5051_50511501_99_dialog_content = "嗯，我跟孩子們今天一天確實是餓壞了。",
  ui_story_5051_50511501_100_dialog_content = "臨空先生，好好休息，我們改日再聊。",
  ui_story_5051_50511501_101_dialog_content = "那麼，就這樣。",
  ui_story_5051_50511501_102_dialog_content = "……",
  ui_story_5051_50511501_103_dialog_content = "還真的就這樣自顧自走掉了啊。",
  ui_story_5051_50511501_104_dialog_content = "臨空先生，很抱歉還要請大家再稍等片刻。",
  ui_story_5051_50511501_105_dialog_content = "晚餐馬上就好。",
  ui_story_5051_50511501_106_dialog_content = "……有勞了。",
  ui_story_5051_50511501_107_dialog_content = "我實在無法想像，您會與這樣溫柔的約書亞夫人起口角。",
  ui_story_5051_50511501_108_dialog_content = "父親和媽媽，在歷史上的這一天……曾經吵過架嗎？",
  ui_story_5051_50511501_109_dialog_content = "……",
  ui_story_5051_50511501_110_dialog_content = "自己做過的事情，卻不敢承認嗎？",
  ui_story_5051_50511501_111_dialog_content = "凱萊布？！你是從哪跳出來的啊？",
  ui_story_5051_50511501_112_dialog_content = "是……舅父？",
  ui_story_5051_50511501_113_dialog_content = "凱萊布，我聽加晴說你丟下她自己走了。你什麼時候才能穩重一點？",
  ui_story_5051_50511501_114_dialog_content = "不要岔開話題，城主殿下。",
  ui_story_5051_50511501_115_dialog_content = "你連自己做過的事情都不敢承認嗎？",
  ui_story_5051_50511501_116_dialog_content = "那就讓我來幫你回憶一下吧。",
  ui_story_5051_50511501_117_dialog_content = "在那次爭吵後，姐姐帶著小卡蓮離開了舒瓦茲城堡。",
  ui_story_5051_50511501_118_dialog_content = "你們再也沒能好好說上一句話、再也沒能吃上一頓家常的飯菜……",
  ui_story_5051_50511501_119_dialog_content = "直到姐姐從戰場上救回奄奄一息的薇羅妮卡。",
  ui_story_5051_50511501_120_dialog_content = "你假裝埋首於抵抗暗鬼的戰事，事實卻是你根本不敢面對姐姐……",
  ui_story_5051_50511501_121_dialog_content = "後來，你又為了自己的政治目的，把受傷的薇羅妮卡送往啟光實驗室。",
  ui_story_5051_50511501_122_dialog_content = "萬萬沒想到，那所實驗室是由喪心病狂的瘋子所控制的修羅場。",
  ui_story_5051_50511501_123_dialog_content = "姐姐再一次從危險中救回薇羅妮卡，但她卻因此重病不起……",
  ui_story_5051_50511501_124_dialog_content = "我說的對嗎？姐、夫。",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>啟光實驗室</color>……頭、頭好痛。",
  ui_story_5051_50511501_126_dialog_content = "蜜雅，快坐下休息，不要逼自己回想了。",
  ui_story_5051_50511501_127_dialog_content = "……",
  ui_story_5051_50511501_128_dialog_content = "凱萊布，你今天到底跑哪去了？",
  ui_story_5051_50511501_129_dialog_content = "失聯了一整天，我還以為你不想出去了呢！",
  ui_story_5051_50511501_130_dialog_content = "我一直都在這裡，只不過「她」沒認出我現在的樣子。",
  ui_story_5051_50511501_131_dialog_content = "我怕我再出現，會對「姐姐」造成困擾……",
  ui_story_5051_50511501_132_dialog_content = "對，不能再待在這裡了。",
  ui_story_5051_50511501_133_dialog_content = "加晴，快點帶我出去！",
  ui_story_5051_50511501_134_dialog_content = "剛見面就提出這麼直接的要求嗎？",
  ui_story_5051_50511501_135_dialog_content = "現在人也都到齊了，我們還不出去嗎？",
  ui_story_5051_50511501_136_dialog_content = "之前不是妳說要快點離開「永憶鏡晶」，否則會有危險的嗎？",
  ui_story_5051_50511501_137_dialog_content = "話是這麼說沒錯啦。",
  ui_story_5051_50511501_138_dialog_content = "大家，準備好出去了嗎？",
  ui_story_5051_50511501_139_dialog_content = "「媽媽」她，還等著我們一起去吃晚餐……",
  ui_story_5051_50511501_140_dialog_content = "還有時間，我們不妨再駐足片刻。",
  ui_story_5051_50511501_141_dialog_content = "城主大人，您之前不是也一直催促我們快點離開嗎？",
  ui_story_5051_50511501_142_dialog_content = "因為當時大家處在危險之中。",
  ui_story_5051_50511501_143_dialog_content = "現在最危險的時候已經過去了。",
  ui_story_5051_50511501_144_dialog_content = "而且……",
  ui_story_5051_50511501_145_dialog_content = "（也許凱萊布說得沒錯，當年爆發的那場爭執，是一切不幸的開端。）",
  ui_story_5051_50511501_146_dialog_content = "（那一天，雖然我獲得白夜城所有貴族的支持，卻讓自己最愛的人傷透了心。）",
  ui_story_5051_50511501_147_dialog_content = "父親？",
  ui_story_5051_50511501_148_dialog_content = "而且，如果我們現在就走……",
  ui_story_5051_50511501_149_dialog_content = "「約書亞」就又要和當年一樣，獨自捱過這不安穩的一夜了。",
  ui_story_5051_50511501_150_dialog_content = "舒瓦茲，你這樣惺惺作態是想演給誰看？",
  ui_story_5051_50511501_151_dialog_content = "凱萊布，我知道你一直因為約書亞的事而恨我。",
  ui_story_5051_50511501_152_dialog_content = "很多遺憾，事過境遷，早已無法彌補。",
  ui_story_5051_50511501_153_dialog_content = "我接受你對我的所有恨意。",
  ui_story_5051_50511501_154_dialog_content = "如果能夠再給我一次機會，我一定不會讓她……",
  ui_story_5051_50511501_155_dialog_content = "呵呵，現在說這些有意義嗎？",
  ui_story_5051_50511501_156_dialog_content = "這整個世界，說到底都是假的……",
  ui_story_5051_50511501_157_dialog_content = "你在這裡面懺悔，也改變不了任何事！",
  ui_story_5051_50511501_158_dialog_content = "舅、舅父……",
  ui_story_5051_50511501_159_dialog_content = "我也想和「媽媽」好好道別。",
  ui_story_5051_50511501_160_dialog_content = "我知道這個世界不是真的，但是大家的情感並不虛假。",
  ui_story_5051_50511501_161_dialog_content = "就……就再給大家最後一點時間吧。",
  ui_story_5051_50511501_162_dialog_content = "其、其實我也想跟某個人道別。",
  ui_story_5051_50511501_163_dialog_content = "反正現在還有時間，暫時也不會有別的危險……",
  ui_story_5051_50511501_164_dialog_content = "不如大家都好好地說聲再見再回去吧！",
  ui_story_5051_50511501_165_dialog_content = "畢竟，下一次再進來，他們也許又不認識我們了。",
  ui_story_5051_50511501_166_dialog_content = "你們……！",
  ui_story_5051_50511501_167_dialog_content = "PlayerName，可以陪我一起去跟「約書亞」道別嗎？",
  ui_story_5051_50511501_168_dialog_content = "在她眼裡，我只是個陌生的男人，如果不帶著你去，似乎有失禮節。",
  ui_story_5051_50511501_169_dialog_content = "可是您現在的身分是我父親，要怎麼說出您想說的話呢？",
  ui_story_5051_50511501_170_dialog_content = "要是「約書亞」能認出城主大人就好了……",
  ui_story_5051_50511501_171_dialog_content = "對了，加晴！妳不是可以控制「永憶鏡晶」嗎？",
  ui_story_5051_50511501_172_dialog_content = "有沒有什麼辦法，可以讓「約書亞」認出城主大人？",
  ui_story_5051_50511501_173_dialog_content = "辦法嘛，也不是沒有喔！",
  ui_story_5051_50511501_174_dialog_content = "只是……我以前沒試過這種方法，我怕又鬧出什麼問題。",
  ui_story_5051_50511501_175_dialog_content = "無妨，可以試試看。",
  ui_story_5051_50511501_176_dialog_content = "城主大人，您竟然還願意相信我嗎？",
  ui_story_5051_50511501_177_dialog_content = "為了彌補您的遺憾，加晴我也豁出去了！",
  ui_story_5051_50511501_178_dialog_content = "不過……嘻嘻嘻。",
  ui_story_5051_50511501_179_dialog_content = "還是先讓我在書裡找一找吧！",
  ui_story_5051_50511501_180_dialog_content = "咳咳，城主大人，這真的靠得住嗎？",
  ui_story_5051_50511501_181_dialog_content = "年輕人，我已經逃避了十幾年……",
  ui_story_5051_50511501_182_dialog_content = "對我來說，進入這個世界可能並不是單純的意外。",
  ui_story_5051_50511501_183_dialog_content = "也許，冥冥之中是光之神在引導著我。",
  ui_story_5051_50511501_184_dialog_content = "是時候去面對自己的軟弱了。",
  ui_story_5051_50511501_185_dialog_content = "城主大人，事先提醒您，這種幻術只能維持一小段時間。",
  ui_story_5051_50511501_186_dialog_content = "請一定要在穿幫之前回來喔～",
  ui_story_5051_50511501_187_dialog_content = "我準備好了。",
  ui_story_5051_50511501_188_dialog_content = "那就開始囉～！",
  ui_story_5051_50511501_189_dialog_content = "繆塔提歐～繆塔提歐～繆塔提歐！",
  ui_story_5051_50511501_190_dialog_content = "請把狄安理·舒瓦茲變回年輕的樣子吧！",
  ui_story_5051_50511501_191_dialog_content = "阿布拉卡達布拉！",
  ui_story_5051_50511501_192_dialog_content = "<color=#e8d9bb>碰！</color>",
  ui_story_5051_50511501_193_dialog_content = "啊？！",
  ui_story_5051_50511501_194_dialog_content = "PlayerName，怎麼了？為何如此驚訝？",
  ui_story_5051_50511501_195_dialog_content = "城主年輕時的長相果然一如既往地令人……印象深刻。",
  ui_story_5051_50511501_196_dialog_content = "嗚……",
  ui_story_5051_50511501_197_dialog_content = "呃，加晴，妳怎麼把城主變成初階法官的兄弟了……",
  ui_story_5051_50511501_198_dialog_content = "初階法官？！",
  ui_story_5051_50511501_199_dialog_content = "咳咳……我可能剛才太興奮了，沒有在腦海中想像出您年輕的模樣……",
  ui_story_5051_50511501_200_dialog_content = "加晴，我們剛剛不是才見過城主大人年輕的模樣嗎？",
  ui_story_5051_50511501_201_dialog_content = "喔，對喔！！！",
  ui_story_5051_50511501_202_dialog_content = "那就好辦了，請讓我再試一次！",
  ui_story_5051_50511501_203_dialog_content = "繆塔提歐～繆塔提歐～繆塔提歐！",
  ui_story_5051_50511501_204_dialog_content = "請把狄安理·舒瓦茲變回年輕的樣子吧！",
  ui_story_5051_50511501_205_dialog_content = "阿布拉卡達布拉！",
  ui_story_5051_50511501_206_dialog_content = "<color=#e8d9bb>碰！</color>",
  ui_story_5051_50511501_207_dialog_content = "衛兵，是你在門口嗎？",
  ui_story_5051_50511501_208_dialog_content = "晚餐已經準備好了，可以幫我邀請大家過來嗎？",
  ui_story_5051_50511501_209_dialog_content = "……",
  ui_story_5051_50511501_210_dialog_content = "衛兵？",
  ui_story_5051_50511501_211_dialog_content = "是你？",
  ui_story_5051_50511501_212_dialog_content = "………………",
  ui_story_5051_50511501_213_dialog_content = "<size=30>對不起。</size>",
  ui_story_5051_50511501_214_dialog_content = "嗯？你說什麼？",
  ui_story_5051_50511501_215_dialog_content = "沒什麼。",
  ui_story_5051_50511501_216_dialog_content = "狄安理，難道你剛才說的是……「對不起」？",
  ui_story_5051_50511501_217_dialog_content = "約書亞……",
  ui_story_5051_50511501_218_dialog_content = "好了，回來就好。",
  ui_story_5051_50511501_219_dialog_content = "覺得累了，就回家。",
  ui_story_5051_50511501_220_dialog_content = "沒事的。我和孩子們永遠都會陪在你身邊，好嗎？",
  ui_story_5051_50511501_221_dialog_content = "……",
  ui_story_5051_50511501_222_dialog_content = "你先休息一下，我去請人再準備一套餐具。",
  ui_story_5051_50511501_223_dialog_content = "……",
  ui_story_5051_50511501_224_dialog_content = "狄安理，你這樣拉著我，我怎麼走呀？",
  ui_story_5051_50511501_225_dialog_content = "有很多話，想告訴妳。",
  ui_story_5051_50511501_226_dialog_content = "你終於想起來家裡還有個人可以聽你發牢騷了？",
  ui_story_5051_50511501_227_dialog_content = "是什麼話呢？一定要現在說不可嗎？",
  ui_story_5051_50511501_228_dialog_content = "嗯。",
  ui_story_5051_50511501_229_dialog_content = "好吧，那就讓大家先陪你餓一會兒肚子。",
  ui_story_5051_50511501_230_dialog_content = "讓我聽聽你想說什麼吧～",
  ui_story_5051_50511501_231_dialog_content = "………………",
  ui_story_5051_50511501_232_dialog_content = "我……好想妳。",
  ui_story_5051_50511501_233_dialog_content = "欸？",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>一旁的角落裡</color>",
  ui_story_5051_50511501_235_dialog_content = "加晴，快點啦！",
  ui_story_5051_50511501_236_dialog_content = "為什麼一輪到我，妳的咒語就不管用了？",
  ui_story_5051_50511501_237_dialog_content = "咦咦咦、不要催我嘛，咒語能不能生效也很看心情的。",
  ui_story_5051_50511501_238_dialog_content = "還是再試試看剛才的石膏頭，怎麼樣？！",
  ui_story_5051_50511501_239_dialog_content = "妳……！",
  ui_story_5051_50511501_240_dialog_content = "父親他……到底有沒有說出口？",
  ui_story_5051_50511501_241_dialog_content = "嗯，看樣子是說出來了吧？兩人目前相處得好像挺融洽的？",
  ui_story_5051_50511501_242_dialog_content = "<size=45>啊啊啊，舒瓦茲那個鹹豬手！他要對姐姐做什麼！！！</size>",
  ui_story_5051_50511501_243_dialog_content = "PlayerName……你幹嘛突然摀住我的眼睛？",
  ui_story_5051_50511501_244_dialog_content = "蜜雅，不是妳忽然摀住我的眼睛嗎？",
  ui_story_5051_50511501_245_dialog_content = "咳，你們這群小鬼……",
  ui_story_5051_50511501_246_dialog_content = "<size=45>都不許再偷看了！</size>",
  ui_story_5051_50511601_1_dialog_content = "呼……呼……呼……",
  ui_story_5051_50511601_2_dialog_content = "真是的，都喝了醒酒湯了，怎麼還能睡得這麼香啊？",
  ui_story_5051_50511601_3_dialog_content = "不過這樣也好！我就可以毫無顧忌地叫妳一聲……",
  ui_story_5051_50511601_4_dialog_content = "媽、媽媽……",
  ui_story_5051_50511601_5_dialog_content = "咦嘿嘿，怎麼回事嘛，這樣說出來還有點不好意思呢。",
  ui_story_5051_50511601_6_dialog_content = "自從十幾年前妳離開家門、閉關靜修之後，我一直都盼著能和妳再見。",
  ui_story_5051_50511601_7_dialog_content = "我幻想著，也許有一天我能利用占卜術找到妳靜修的地點。",
  ui_story_5051_50511601_8_dialog_content = "也一直想像著，妳是不是還像當年那樣……",
  ui_story_5051_50511601_9_dialog_content = "總是披著面紗，一個人住在森林深處的小屋忙進忙出。",
  ui_story_5051_50511601_10_dialog_content = "可是十幾年過去，我記憶中妳的樣子都已經模糊不清了。",
  ui_story_5051_50511601_11_dialog_content = "沒想到今天，我竟然在白夜城遇到了年輕時候的妳。",
  ui_story_5051_50511601_12_dialog_content = "更沒想到，年輕的妳看起來這麼……靠不住！",
  ui_story_5051_50511601_13_dialog_content = "但也比我印象中的媽媽更開朗、更可愛、更果決勇敢……",
  ui_story_5051_50511601_14_dialog_content = "妳走之後，爸爸也想帶著我離開北境。",
  ui_story_5051_50511601_15_dialog_content = "但是我擔心我們走了，媽媽哪天回家就會找不到親人。所以我就一個人留了下來。",
  ui_story_5051_50511601_16_dialog_content = "但是妳別擔心喔，我有很多很多朋友！",
  ui_story_5051_50511601_17_dialog_content = "還靠媽媽留下的占卜書，學會了咒語……雖然現在還不太熟練，又鬧了很多烏龍。",
  ui_story_5051_50511601_18_dialog_content = "但、但妳等著喔！",
  ui_story_5051_50511601_19_dialog_content = "我一定會成為博阿姿最厲害的徒弟，做出比「永憶鏡晶」還要厲害的水晶球！",
  ui_story_5051_50511601_20_dialog_content = "然後，嘿嘿，說不定還會占卜出妳現在到底藏在北境的哪個地方呢。",
  ui_story_5051_50511601_21_dialog_content = "總之，等妳再見到我的時候，就會知道啦～",
  ui_story_5051_50511601_22_dialog_content = "乖孩子。",
  ui_story_5051_50511601_23_dialog_content = "咦，咦——！妳、妳醒了？",
  ui_story_5051_50511601_24_dialog_content = "咳咳，我剛才都是胡說八道的啦，妳別放在心上喔。",
  ui_story_5051_50511601_25_dialog_content = "不過妳可能也聽不懂我剛才說了什麼吧……對不起吵醒妳了，我只是想跟妳道個別。",
  ui_story_5051_50511601_26_dialog_content = "喔？我的理解能力有那麼差嗎？",
  ui_story_5051_50511601_27_dialog_content = "因為妳一直醉醺醺的……",
  ui_story_5051_50511601_28_dialog_content = "咦？可是妳怎麼忽然變得這麼正經？我都有點不習慣了！",
  ui_story_5051_50511601_29_dialog_content = "想要解開「永憶鏡晶」的奧祕，妳現在這點三腳貓功夫還遠遠不夠。",
  ui_story_5051_50511601_30_dialog_content = "更別提製作一個出來了。",
  ui_story_5051_50511601_31_dialog_content = "加晴，妳確定這是妳想做的事？",
  ui_story_5051_50511601_32_dialog_content = "確定！十分確定！",
  ui_story_5051_50511601_33_dialog_content = "……咦，妳不是不承認我是妳的女兒加晴嗎？",
  ui_story_5051_50511601_34_dialog_content = "「妳」的確不是「我」的女兒加晴。",
  ui_story_5051_50511601_35_dialog_content = "但我知道，妳確實也是加晴。",
  ui_story_5051_50511601_36_dialog_content = "加晴，妳終於回來了。",
  ui_story_5051_50511601_37_dialog_content = "咦嘿嘿，抱歉抱歉，一不小心就說了很多話。",
  ui_story_5051_50511601_38_dialog_content = "妳怎麼了，好像心事重重的？",
  ui_story_5051_50511601_39_dialog_content = "有、有嗎？",
  ui_story_5051_50511601_40_dialog_content = "對了，凱萊布，還要再繼續試嗎？這次我保證一定可以成功把你變年輕！",
  ui_story_5051_50511601_X41_dialog_content = "算了，我可不想再被變成兔子腦袋。",
  ui_story_5051_50511601_42_dialog_content = "噓……",
  ui_story_5051_50511601_43_dialog_content = "別讓父親和媽媽發現我們。",
  ui_story_5051_50511601_44_dialog_content = "嗯？城主大人還在和「約書亞」夫人道別嗎？",
  ui_story_5051_50511601_45_dialog_content = "看樣子，這場道別一時半會是結束不了了……",
  ui_story_5051_50511601_46_dialog_content = "咦？孩子們和客人們怎麼還沒來？",
  ui_story_5051_50511601_47_dialog_content = "他們……已經睡著了。",
  ui_story_5051_50511601_48_dialog_content = "大家今天一定都累壞了吧，但是不吃飯身體怎麼受得了呢？",
  ui_story_5051_50511601_49_dialog_content = "我去派人把食物送到他們房間……",
  ui_story_5051_50511601_50_dialog_content = "這些事我已經吩咐過了，妳不用操心。",
  ui_story_5051_50511601_51_dialog_content = "嗯？很可疑喔狄安理。",
  ui_story_5051_50511601_52_dialog_content = "你是不是做了什麼虧心事？",
  ui_story_5051_50511601_53_dialog_content = "虧心事？",
  ui_story_5051_50511601_54_dialog_content = "對啊，要不然平常日理萬機的城主殿下，今天怎麼有時間體貼夫人了呢？",
  ui_story_5051_50511601_55_dialog_content = "我只是覺得……",
  ui_story_5051_50511601_56_dialog_content = "我們好久沒有像這樣，兩個人坐在一起吃晚餐了。",
  ui_story_5051_50511601_57_dialog_content = "這倒是真的。只不過……我還以為你早就不在意這種事了呢。",
  ui_story_5051_50511601_58_dialog_content = "對不起。",
  ui_story_5051_50511601_59_dialog_content = "好啦，今天怎麼講來講去都是這句話？",
  ui_story_5051_50511601_60_dialog_content = "到底是因為什麼想跟我說「對不起」？",
  ui_story_5051_50511601_61_dialog_content = "現在還沒辦法告訴妳。",
  ui_story_5051_50511601_62_dialog_content = "狄安理……？",
  ui_story_5051_50511601_63_dialog_content = "是因為卡爾帝瑪家族的事嗎？",
  ui_story_5051_50511601_64_dialog_content = "你真的不打算放過他們家族的任何人嗎，狄安理？",
  ui_story_5051_50511601_65_dialog_content = "……",
  ui_story_5051_50511601_66_dialog_content = "當然不是。",
  ui_story_5051_50511601_67_dialog_content = "應該處置的是那些真正有罪的人。",
  ui_story_5051_50511601_68_dialog_content = "你是為了糊弄我，才想用這種說詞搪塞過去嗎？",
  ui_story_5051_50511601_69_dialog_content = "不是的，約書亞！",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>嗶嚓！</color>",
  ui_story_5051_50511601_71_dialog_content = "嗯？約書亞？",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>……欺騙我。</anim>",
  ui_story_5051_50511601_73_dialog_content = "約書亞？",
  ui_story_5051_50511601_74_dialog_content = "妳怎麼了，約書亞！？",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>你……欺……騙……我……</anim>",
  ui_story_5051_50511601_76_dialog_content = "約書亞，是我害妳變成這樣子的嗎？",
  ui_story_5051_50511601_77_dialog_content = "我孤注一擲懲治了卡爾帝瑪家族……",
  ui_story_5051_50511601_78_dialog_content = "我沒能相信妳的判斷，忽視妳對我的忠告……",
  ui_story_5051_50511601_79_dialog_content = "我沒能體諒妳的辛苦，把家庭的責任理所當然地丟給妳承擔……",
  ui_story_5051_50511601_80_dialog_content = "我沒能在妳需要的時候，待在妳身邊……",
  ui_story_5051_50511601_81_dialog_content = "……對不起！",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>嗶嚓！嗶嚓！</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>狄安理……</anim>",
  ui_story_5051_50511601_84_dialog_content = "我在！我在這裡，約書亞！",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>狄安理……薇羅妮卡……卡蓮……</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>啊！！！</anim>",
  ui_story_5051_50511601_87_dialog_content = "約書亞！！！",
  ui_story_5051_50511601_88_dialog_content = "媽媽、媽媽那是怎麼了！？",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>轟隆隆！</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>轟隆隆隆隆隆——！！</color>",
  ui_story_5051_50511601_91_dialog_content = "又是這種打雷的聲音……？",
  ui_story_5051_50511601_92_dialog_content = "地震？是地震了嗎？",
  ui_story_5051_50511601_93_dialog_content = "不對，歷史上這天晚上並沒有地震！",
  ui_story_5051_50511601_94_dialog_content = "我好像……有點看不清楚周遭了。",
  ui_story_5051_50511601_95_dialog_content = "我也是！只能靠所剩無幾的感應能力來辨別方向。",
  ui_story_5051_50511601_96_dialog_content = "加晴，是不是時間快到了？！",
  ui_story_5051_50511601_97_dialog_content = "還有時間，距離這天結束還有很多時間……不應該這樣的啊？",
  ui_story_5051_50511601_98_dialog_content = "難道我們真的要掉進「永憶鏡晶」與現實世界的縫隙中了嗎？",
  ui_story_5051_50511601_99_dialog_content = "加晴，妳還在等什麼？",
  ui_story_5051_50511601_100_dialog_content = "快點帶大家出去啊！",
  ui_story_5051_50511601_101_dialog_content = "大家，快點過來我身邊！",
  ui_story_5051_50511601_102_dialog_content = "可是父親還沒回來……",
  ui_story_5051_50511601_103_dialog_content = "那種偽君子困在這種地方正好！別管他了，我們快走！",
  ui_story_5051_50511601_104_dialog_content = "就算是窮兇惡極的壞蛋，在這種時候我們也不可以丟下不管……",
  ui_story_5051_50511601_105_dialog_content = "呼喊城主",
  ui_story_5051_50511601_106_dialog_content = "城主大人！我們在這裡！！！",
  ui_story_5051_50511601_107_dialog_content = "父親！",
  ui_story_5051_50511601_108_dialog_content = "舒瓦茲殿下！",
  ui_story_5051_50511601_109_dialog_content = "怎麼會一點回應都沒有……",
  ui_story_5051_50511601_110_dialog_content = "感應城主",
  ui_story_5051_50511601_111_dialog_content = "可惡……",
  ui_story_5051_50511601_112_dialog_content = "還是沒辦法在「永憶鏡晶」裡感應到別人！",
  ui_story_5051_50511601_113_dialog_content = "啊……",
  ui_story_5051_50511601_114_dialog_content = "蜜雅，怎麼了？",
  ui_story_5051_50511601_115_dialog_content = "我們身後的空間……慢慢地坍塌消失了！",
  ui_story_5051_50511601_116_dialog_content = "PlayerName，動作快！",
  ui_story_5051_50511601_117_dialog_content = "大家跟著我，我們往城主剛才所在的方向走！",
  ui_story_5051_50511601_118_dialog_content = "加晴，如果直到最後一刻我們還是無法看到城主……",
  ui_story_5051_50511601_119_dialog_content = "就帶我們出去！",
  ui_story_5051_50511601_120_dialog_content = "……好！",
  ui_story_5051_50511601_121_dialog_content = "哼。",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>嗖——！</color>",
  ui_story_5051_50511601_123_dialog_content = "剛剛……是有誰跑過去了嗎？",
  ui_story_5051_50511601_124_dialog_content = "在這種情況下，有誰能跑得那麼快？",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>狄安理……薇羅妮卡……卡蓮……</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "咦，好像有人在喊我的名字？",
  ui_story_5051_50511601_127_dialog_content = "聲音太小了，根本分辨不出是從哪邊傳來的。",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>在，這裡？</anim>",
  ui_story_5051_50511601_129_dialog_content = "咦……",
  ui_story_5051_50511601_130_dialog_content = "小心！！！",
  ui_story_5051_50511601_131_dialog_content = "父親！",
  ui_story_5051_50511601_132_dialog_content = "大家注意，有個不速之客！",
  ui_story_5051_50511601_133_dialog_content = "下手這麼狠……到底是誰在這種情況下還能攻擊我們？",
  ui_story_5051_50511601_134_dialog_content = "我們……已經跌進「永憶鏡晶」與現實世界的縫隙了嗎……",
  ui_story_5051_50511601_135_dialog_content = "不！不——！",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>在，這裡？</anim>",
  ui_story_5051_50511601_137_dialog_content = "啊啊啊！是怪物啊！",
  ui_story_5051_50511601_138_dialog_content = "PlayerName，現在只剩你還能分辨方向了。",
  ui_story_5051_50511601_139_dialog_content = "指揮就交給你了！",
  ui_story_5051_50511602_1_dialog_content = "呼哧……呼哧……",
  ui_story_5051_50511602_2_dialog_content = "蜜雅，稍微休息一下！",
  ui_story_5051_50511602_3_dialog_content = "可是……不行，我還想幫父親、幫大家……",
  ui_story_5051_50511602_4_dialog_content = "在，這裡？",
  ui_story_5051_50511602_5_dialog_content = "水晶球，釋放！",
  ui_story_5051_50511602_6_dialog_content = "啊拜託……這怪物的攻擊根本沒完沒了嘛！",
  ui_story_5051_50511602_7_dialog_content = "加晴，為什麼「永憶鏡晶」裡會有這種怪物？",
  ui_story_5051_50511602_8_dialog_content = "我、我也不知道呀。",
  ui_story_5051_50511602_9_dialog_content = "這真的不是當年白夜城出現過的怪物嗎？",
  ui_story_5051_50511602_10_dialog_content = "……",
  ui_story_5051_50511602_11_dialog_content = "「白夜！庇護！」",
  ui_story_5051_50511602_12_dialog_content = "當年白夜城並沒有出現過這種怪物。",
  ui_story_5051_50511602_13_dialog_content = "但是不要灰心！",
  ui_story_5051_50511602_14_dialog_content = "比起剛才，對方的力量已經明顯削弱，攻擊的間隔也越來越長了。",
  ui_story_5051_50511602_15_dialog_content = "加晴！下一次對方攻擊後，趁間隔時間立刻帶我們出去！",
  ui_story_5051_50511602_16_dialog_content = "好的，城主大人！",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5051_50511602_18_dialog_content = "怎麼忽然沒有動靜了？",
  ui_story_5051_50511602_19_dialog_content = "噓，你們聽見了嗎？",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>狄安理……薇羅妮卡……卡蓮……</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "是牠……牠在喊父親和我們姐妹倆的名字？",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>狄安理、薇羅妮卡、卡蓮。</anim>",
  ui_story_5051_50511602_23_dialog_content = "這個聲音是……",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>還有……凱萊布。</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>姐姐</color>？！",
  ui_story_5051_50511602_26_dialog_content = "怎麼會！",
  ui_story_5051_50511602_27_dialog_content = "什麼？是姐、姐姐！？",
  ui_story_5051_50511602_28_dialog_content = "不對……不對！不對！怎麼會這樣？姐姐不可能會在這裡！",
  ui_story_5051_50511602_29_dialog_content = "難道是……",
  ui_story_5051_50511602_30_dialog_content = "……",
  ui_story_5051_50511602_31_dialog_content = "為什麼牠忽然停下來了？",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>不！</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>不可以這麼做！</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>為什麼不可以？</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>他們是所有痛苦的根源。</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>是阻礙我實現理想的絆腳石！</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>他們是我最在乎的人！</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>除掉他們，我就可以出去了！</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>還在等什麼呢？他們已經快要撐不住了。</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>好吵……好吵啊！</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>快給我出去！</anim>",
  ui_story_5051_50511602_42_dialog_content = "牠是在自言自語嗎？",
  ui_story_5051_50511602_X43_dialog_content = "太奇怪了……感覺像在和自己吵架。",
  ui_story_5051_50511602_44_dialog_content = "姐姐，真的、真的是妳嗎？",
  ui_story_5051_50511602_45_dialog_content = "媽媽……？",
  ui_story_5051_50511602_46_dialog_content = "竟敢冒充約書亞的聲音？",
  ui_story_5051_50511602_47_dialog_content = "不可饒恕！",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>舒瓦……</anim>",
  ui_story_5051_50511602_49_dialog_content = "「我要、諸星都動搖——！！」",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>呃……</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>我……恨……你……！</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "什麼？",
  ui_story_5051_50511602_53_dialog_content = "城主大人的攻擊奏效了！",
  ui_story_5051_50511602_54_dialog_content = "牠看起來好痛苦，但似乎並不是因為身體上的痛？",
  ui_story_5051_50511602_55_dialog_content = "不可能是姐姐，怎麼會是姐姐？如果是姐姐的話……",
  ui_story_5051_50511602_56_dialog_content = "加晴，快點帶我們出去，快帶我們出去啊！",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5051_50511602_58_dialog_content = "這是……時鐘報時的聲音？",
  ui_story_5051_50511602_59_dialog_content = "完了完了完了……十二點的鐘聲已經敲響了！",
  ui_story_5051_50511602_60_dialog_content = "我們要被困在這個地方了嗎？",
  ui_story_5051_50511602_61_dialog_content = "為什麼……好不容易找到這個東西……",
  ui_story_5051_50511602_62_dialog_content = "明明只差一步就好了……",
  ui_story_5051_50511602_63_dialog_content = "為什麼？！",
  ui_story_5051_50511602_64_dialog_content = "咦，凱萊布，你手裡拿著什麼？",
  ui_story_5051_50511602_65_dialog_content = "是存放在這個世界裡的「永憶鏡晶」嗎？",
  ui_story_5051_50511602_66_dialog_content = "「永憶鏡晶」裡的「永憶鏡晶」？",
  ui_story_5051_50511602_67_dialog_content = "呵呵，就算找到了，也沒用了。",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5051_50511602_69_dialog_content = "十二點的鐘聲馬上就要敲完了！",
  ui_story_5051_50511602_70_dialog_content = "凱萊布，你為什麼要在「永憶鏡晶」的世界裡找這個東西？",
  ui_story_5051_50511602_71_dialog_content = "沒用了，說什麼都沒用了。",
  ui_story_5051_50511602_72_dialog_content = "不，也許還有救！！！",
  ui_story_5051_50511602_73_dialog_content = "凱萊布，把「永憶鏡晶」給我！",
  ui_story_5051_50511602_74_dialog_content = "拿去吧。",
  ui_story_5051_50511602_75_dialog_content = "「媽媽」……",
  ui_story_5051_50511602_76_dialog_content = "難道妳當時就已經預測到現在會發生這種事了嗎？",
  ui_story_5051_50511602_77_dialog_content = "人們往往喜歡靠占卜來預知未來。",
  ui_story_5051_50511602_78_dialog_content = "但是後來我發現，人們總是低估自己遺忘的速度。",
  ui_story_5051_50511602_79_dialog_content = "所以某種程度上來說，比未來更「無法預知」的，其實是<color=#FFB400>過去</color>。",
  ui_story_5051_50511602_80_dialog_content = "這就是我創造出「永憶鏡晶」的初衷。",
  ui_story_5051_50511602_81_dialog_content = "我本以為，這是回顧歷史最安全的一種方式。",
  ui_story_5051_50511602_82_dialog_content = "但妳的出現，讓我意識到「永憶鏡晶」還是有發生意外的可能。",
  ui_story_5051_50511602_83_dialog_content = "好在，「永憶鏡晶」的世界裡有一個緊急避難裝置。",
  ui_story_5051_50511602_84_dialog_content = "……「永憶鏡晶」中的「永憶鏡晶」。",
  ui_story_5051_50511602_85_dialog_content = "這是占卜書上唯一沒有記載的內容。",
  ui_story_5051_50511602_86_dialog_content = "希望妳，永遠都用不到這個知識。",
  ui_story_5051_50511602_87_dialog_content = "我、不會讓妳失望的！",
  ui_story_5051_50511602_88_dialog_content = "里特羅，里特羅，里特羅！",
  ui_story_5051_50511602_89_dialog_content = "艾·普勒俄森斯！",
  ui_story_5051_50511602_90_dialog_content = "時光倒流回起點，讓我們回到現實中去吧！",
  ui_story_5051_50511602_91_dialog_content = "<size=45>阿布拉卡達布拉！</size>",
  ui_story_5051_50511602_92_dialog_content = "呃嗚！",
  ui_story_5051_50511602_93_dialog_content = "又來了……這種天旋地轉的感覺……",
  ui_story_5051_50511602_94_dialog_content = "大家抓緊彼此，不要散開！",
  ui_story_5051_50511602_95_dialog_content = "蜜雅、PlayerName，快到我懷裡來！",
  ui_story_5051_50511602_96_dialog_content = "呃啊……怎麼辦？我快要拉不動凱萊布了！",
  ui_story_5051_50511602_97_dialog_content = "姐姐，對不起……我再也沒辦法陪在妳身邊了。",
  ui_story_5051_50511602_98_dialog_content = "不可以……丟下任何一個人！",
  ui_story_5051_50511602_99_dialog_content = "PlayerName？！",
  ui_story_5051_50511602_100_dialog_content = "凱萊布！",
  ui_story_5051_50511602_101_dialog_content = "抓住我的手！",
  ui_story_5051_50511602_102_dialog_content = "呃！",
  ui_story_5051_50511602_103_dialog_content = "PlayerName，你不要再往外探了！父親也快要抓不住你了！",
  ui_story_5051_50511602_104_dialog_content = "不能放棄！",
  ui_story_5051_50511602_105_dialog_content = "PlayerName！！！",
  ui_story_5051_50511602_106_dialog_content = "抓住了！我抓住凱萊布了！",
  ui_story_5051_50511602_107_dialog_content = "……PlayerName？",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5051_50511602_109_dialog_content = "（嗯？這是打破杯子的聲音嗎？）",
  ui_story_5051_50511602_110_dialog_content = "（房裡的杯子就只有……）",
  ui_story_5051_50511602_111_dialog_content = "（看來那杯佳釀還是沒能讓凱萊布先生靜下心來。）",
  ui_story_5051_50511602_112_dialog_content = "喔？「紅女士」，剛才的動靜可不小啊。",
  ui_story_5051_50511602_113_dialog_content = "是哪位「貴賓」如此不小心，在城主的房間裡摔破東西？",
  ui_story_5051_50511602_114_dialog_content = "還是說……是哪位「貴賓」惹得城主如此大怒，要摔東西才能洩憤？",
  ui_story_5051_50511602_115_dialog_content = "公爵大人，我實在是非常佩服您的想像力。",
  ui_story_5051_50511602_116_dialog_content = "城主殿下和貴賓在談什麼、做什麼，實在輪不到我們這些旁人議論。",
  ui_story_5051_50511602_117_dialog_content = "哼，妳已經不是守夜人的隊長了吧？",
  ui_story_5051_50511602_118_dialog_content = "只要我還在為城主殿下服務一天，我就一定不會怠慢。",
  ui_story_5051_50511602_119_dialog_content = "服務？不過是這場宴會的臨時主辦人罷了。",
  ui_story_5051_50511602_120_dialog_content = "如果妳這麼喜歡辦宴會，小犬生日的時候，可否也請「紅女士」來幫忙呢？",
  ui_story_5051_50511602_121_dialog_content = "公爵大人，我剛才似乎表達得不夠清楚。",
  ui_story_5051_50511602_122_dialog_content = "我現在還在為城主殿下服務。",
  ui_story_5051_50511602_123_dialog_content = "無論您說什麼，他今晚都抽不出時間單獨接見您的公子了。",
  ui_story_5051_50511602_124_dialog_content = "哈哈哈，「紅女士」，我可從來沒有提出過這種要求。",
  ui_story_5051_50511602_125_dialog_content = "我只不過是覺得天色已晚，想來提前向城主告辭。",
  ui_story_5051_50511602_126_dialog_content = "像妳這樣以小人之心度君子之腹……",
  ui_story_5051_50511602_127_dialog_content = "可不像是城主殿下的身旁心腹該做的事。",
  ui_story_5051_50511602_128_dialog_content = "哎呀哎呀，還真是不能掉以輕心呢。",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>呼——</color>",
  ui_story_5051_50511602_130_dialog_content = "嗯？",
  ui_story_5051_50511602_131_dialog_content = "外面……",
  ui_story_5051_50511602_132_dialog_content = "起風了呢。",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>同一時間·凱萊布宅邸</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>呼——</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>轟隆隆！</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>轟隆隆隆隆！</color>",
  ui_story_5051_50511602_137_dialog_content = "……",
  ui_story_5051_50511602_138_dialog_content = "…………",
  ui_story_5051_50511602_139_dialog_content = "………………",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>轟隆隆！</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>轟隆隆隆隆！</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>隆咚！</color>",
  ui_story_5051_50511602_143_dialog_content = "未完待續……"
}
return config
